    function normalizeTwodSampleFormula(value) {
      return String(value || "")
        .replace(/[₀₁₂₃₄₅₆₇₈₉]/g, (char) => ({
          "₀": "0",
          "₁": "1",
          "₂": "2",
          "₃": "3",
          "₄": "4",
          "₅": "5",
          "₆": "6",
          "₇": "7",
          "₈": "8",
          "₉": "9"
        }[char] || char))
        .replace(/\s+/g, "")
        .toLowerCase();
    }

    function applyTwodWorkbookSampleData() {
      twodSampleMaterialsFromWorkbook.forEach((sample) => {
        const existing = twodMaterials.find((item) => normalizeTwodSampleFormula(item.formula) === normalizeTwodSampleFormula(sample.formula));
        if (existing) {
          const internalId = existing.id;
          Object.keys(existing).forEach((key) => {
            if (key !== "id") delete existing[key];
          });
          Object.assign(existing, sample, { id: internalId, trueMaterialId: sample.trueMaterialId || sample.id });
          return;
        }
        twodMaterials.push(Object.assign({}, sample));
      });
    }

    applyTwodWorkbookSampleData();

