    function cloneDatasetRecord(record) {
      if (record == null) return {};
      return JSON.parse(JSON.stringify(record));
    }

    function createSupplementedRecords(baseRecords, specs, finalize) {
      return specs.map((spec) => {
        const record = cloneDatasetRecord(baseRecords[spec.seed]);
        const nextRecord = { ...spec };
        delete nextRecord.seed;
        Object.assign(record, nextRecord);
        return typeof finalize === "function" ? finalize(record, spec) : record;
      });
    }

    function syncElectrolyteSupplement(record) {
      record.code = record.id;
      if (record.infoFields?.[0]) record.infoFields[0].value = record.formula;
      if (record.infoFields?.[1]) record.infoFields[1].value = record.cas;
      if (record.infoFields?.[2]) record.infoFields[2].value = record.typeTag;
      if (record.dataFields?.[0]) record.dataFields[0].value = record.source;
      if (record.dataFields?.[1]) record.dataFields[1].value = record.updatedAt;
      if (record.dataFields?.[2]) record.dataFields[2].value = record.quality;
      if (record.dataFields?.[3]) record.dataFields[3].value = record.hazardLevel || record.safety;
      return record;
    }

