    function isLowDimMissing(value) {
      return value == null
        || (typeof value === "string" && value.trim() === "")
        || (typeof value === "number" && !Number.isFinite(value));
    }

    const LOW_DIM_NO_PROPERTY_TEXT = "该材料暂无此性质";

    function isLowDimNoPropertyValue(value) {
      if (isLowDimMissing(value)) return true;
      if (typeof value !== "string") return false;
      const text = value.trim();
      return text === "/"
        || text === "-"
        || text === "\\"
        || text === "—"
        || text === "未记录"
        || text === "暂无"
        || text === "暂无数据"
        || text === "未记录曲线"
        || text === "当前页面无可展示内容。"
        || text === LOW_DIM_NO_PROPERTY_TEXT;
    }

    function formatLowDimNoProperty(value, fallback = LOW_DIM_NO_PROPERTY_TEXT) {
      return isLowDimNoPropertyValue(value) ? fallback : value;
    }

    function toLowDimFiniteNumber(value) {
      if (isLowDimMissing(value)) return null;
      if (typeof value === "number") return Number.isFinite(value) ? value : null;
      const normalized = String(value).trim().replace(/,/g, "");
      if (!normalized) return null;
      const parsed = Number(normalized);
      return Number.isFinite(parsed) ? parsed : null;
    }

    function formatLowDimValue(value, options = {}) {
      if (isLowDimNoPropertyValue(value)) return options.emptyText || LOW_DIM_NO_PROPERTY_TEXT;
      const numericValue = toLowDimFiniteNumber(value);
      if (options.numeric && numericValue == null) return options.emptyText || LOW_DIM_NO_PROPERTY_TEXT;
      if (numericValue != null && (options.numeric || typeof value === "number")) {
        const digits = Number.isInteger(options.digits) ? options.digits : null;
        const text = digits == null ? String(numericValue) : numericValue.toFixed(digits);
        return `${text}${options.suffix || ""}`;
      }
      return `${String(value)}${options.suffix || ""}`;
    }

    function escapeLowDimHtml(value) {
      return String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function getLowDimRealCase(database, materialId) {
      const databases = window.LOW_DIM_REAL_CASES?.databases;
      const bucket = databases?.[database];
      const list = Array.isArray(bucket)
        ? bucket
        : Array.isArray(bucket?.cases)
          ? bucket.cases
          : Array.isArray(bucket?.records)
            ? bucket.records
            : bucket && typeof bucket === "object"
              ? Object.values(bucket).filter((item) => item && typeof item === "object")
              : [];
      return list.find((item) => String(item.id) === String(materialId)) || null;
    }

    function isLowDimRealCase(database, material) {
      if (!material) return false;
      return Boolean(
        material.isRealCase === true
        || material.realCase === true
        || material.__realCase === true
        || getLowDimRealCase(database, material.id)
      );
    }

    function hasLowDimRealCaseDataset(database) {
      const collectionMap = {
        twod: twodMaterials,
        opto: optoMaterials,
        electrolyte: electrolyteMaterials,
        mlff: mlffMaterials,
        catalyst: catalystMaterials
      };
      const list = collectionMap[database] || [];
      return list.length > 0 && list.every((item) => isLowDimRealCase(database, item));
    }

    function renderLowDimRealViewer(database, material, structureKey = "") {
      const realCase = getLowDimRealCase(database, material?.id);
      if (!realCase) return "";
      const target = structureKey
        ? realCase.altStructures?.[structureKey]
        : realCase.structure;
      if (!target?.text) return "";
      const materialId = escapeLowDimHtml(realCase.id);
      const keyAttr = structureKey ? ` data-structure-key="${escapeLowDimHtml(structureKey)}"` : "";
      return `<div class="mol3d-wrap"><div class="mol3d-viewer" data-real-database="${escapeLowDimHtml(database)}" data-material-id="${materialId}" data-case-id="${materialId}"${keyAttr} data-mol-init="0" data-mol-ready="0"></div></div>`;
    }

    function renderLowDimUnavailableState(title = "该项数据", message = LOW_DIM_NO_PROPERTY_TEXT) {
      const displayMessage = LOW_DIM_NO_PROPERTY_TEXT;
      return `
        <div class="twod-detail-page-head">
          <div><h4>${escapeLowDimHtml(title)}</h4><p>${escapeLowDimHtml(displayMessage)}</p></div>
        </div>
        <section class="twod-detail-section-card">
          <div class="twod-detail-empty-state"><strong>${LOW_DIM_NO_PROPERTY_TEXT}</strong><span>${escapeLowDimHtml(displayMessage)}</span></div>
        </section>
      `;
    }

