    function buildTwodDetailDownloadPayload(material) {
      if (twodDetailDownloadState.type === "structure-file") {
        const realFormat = getLowDimRealCase("twod", material?.id)?.structure?.viewerFormat;
        return {
          filename: formatTwodStructureDownloadName(material),
          content: buildTwodStructureFileContent(material),
          mime: realFormat === "xyz" ? "chemical/x-xyz;charset=utf-8" : realFormat === "vasp" ? "text/plain;charset=utf-8" : "chemical/x-cif;charset=utf-8",
          toastTitle: "下载文件",
          toastMessage: `${material.name} 的结构文件已开始下载。`
        };
      }
      if (twodDetailDownloadState.type === "property-page") {
        const tabLabel = MATERIAL_TAB_LABELS[state.selectedMaterialTab] || "当前性质页";
        return {
          filename: formatTwodCurrentPropertyDownloadName(material),
          content: buildTwodCurrentPropertyDownloadContent(material),
          mime: "application/json;charset=utf-8",
          toastTitle: "下载数据",
          toastMessage: `${material.name} 的${tabLabel}已开始下载。`
        };
      }
      if (twodDetailDownloadState.type === "visual-page") {
        const visualPayload = buildTwodCurrentVisualDownloadPayload(material);
        return {
          filename: visualPayload.filename,
          content: visualPayload.content,
          mime: visualPayload.mime,
          toastTitle: "下载图谱",
          toastMessage: `${material.name} 的${visualPayload.label}已开始下载。`
        };
      }
      return null;
    }

    function buildMaterialDiagramMarkup(config) {
      const bonds = (config.bonds || []).map((bond) => {
        const from = config.nodes[bond.from];
        const to = config.nodes[bond.to];
        const dx = to.x - from.x;
        const dy = to.y - from.y;
        const length = Math.sqrt(dx * dx + dy * dy);
        const angle = Math.atan2(dy, dx) * (180 / Math.PI);
        return `<span class="material-bond" style="left:${from.x}%; top:${from.y}%; width:${length}%; transform:rotate(${angle}deg);"></span>`;
      }).join("");
      const nodes = (config.nodes || []).map((node) => `<span class="material-node" style="left:${node.x}%; top:${node.y}%; background:${node.color};">${node.label}</span>`).join("");
      const legend = `<div class="chart-title-note">${(config.legend || []).map((item) => `<span><i style="background:${item.color};"></i>${item.label}</span>`).join("")}</div>`;
      return `<div class="material-atom-cluster material-diagram-stage">${bonds}${nodes}</div>${legend}`;
    }

    function buildMaterialEmptyMarkup(message) {
      return `<div class="material-chart-empty">${escapeLowDimHtml(formatLowDimNoProperty(message))}</div>`;
    }

    function buildChartSvg(config) {
      if (!config) {
        return buildMaterialEmptyMarkup(LOW_DIM_NO_PROPERTY_TEXT);
      }
      if (config.type === "diagram") {
        return buildMaterialDiagramMarkup(config);
      }
      if (config.type === "image") {
        return `
          <figure class="twod-visual-image-frame">
            <img src="${config.src}" alt="${config.alt || config.caption || "材料图谱"}" loading="lazy">
            <figcaption>${config.caption || ""}</figcaption>
          </figure>
        `;
      }
      if (!config.series?.length) {
        return buildMaterialEmptyMarkup(LOW_DIM_NO_PROPERTY_TEXT);
      }
      const width = 900;
      const height = 280;
      const margin = { top: 20, right: 24, bottom: 42, left: 42 };
      const innerWidth = width - margin.left - margin.right;
      const innerHeight = height - margin.top - margin.bottom;
      const flatValues = config.series.flatMap((item) => item.values);
      const maxValue = Math.max(...flatValues, 1);
      const minValue = Math.min(...flatValues, 0);
      const range = maxValue - minValue || 1;
      const steps = 4;

      const gridLines = Array.from({ length: steps + 1 }).map((_, index) => {
        const y = margin.top + (innerHeight / steps) * index;
        return `<line class="chart-gridline" x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}"></line>`;
      }).join("");

      const axis = `
        <line class="chart-axis-line" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
        <line class="chart-axis-line" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
        <text class="chart-label" x="${margin.left + innerWidth / 2}" y="${height - 14}" text-anchor="middle">${config.axisX || "横坐标"}</text>
        <text class="chart-label chart-axis-y-title" x="18" y="${margin.top + innerHeight / 2}" text-anchor="middle" dominant-baseline="middle" transform="rotate(-90 18 ${margin.top + innerHeight / 2})">${config.axisY || "纵坐标"}</text>
      `;

      const xLabels = config.labels.map((label, index) => {
        const x = margin.left + (innerWidth / Math.max(config.labels.length - 1, 1)) * index;
        return `<text class="chart-label" x="${x}" y="${height - 28}" text-anchor="middle">${label}</text>`;
      }).join("");

      const yLabels = Array.from({ length: steps + 1 }).map((_, index) => {
        const ratio = 1 - index / steps;
        const value = minValue + range * ratio;
        const y = margin.top + (innerHeight / steps) * index + 4;
        return `<text class="chart-label" x="${margin.left - 10}" y="${y}" text-anchor="end">${Number(value).toFixed(2)}</text>`;
      }).join("");

      let seriesMarkup = "";
      if (config.type === "bar") {
        const barSeries = config.series[0];
        const count = barSeries.values.length;
        const groupWidth = innerWidth / Math.max(count, 1);
        const barWidth = Math.min(48, groupWidth * 0.52);
        seriesMarkup = barSeries.values.map((value, index) => {
          const x = margin.left + groupWidth * index + (groupWidth - barWidth) / 2;
          const y = margin.top + innerHeight - ((value - minValue) / range) * innerHeight;
          const barHeight = (value - minValue) / range * innerHeight;
          return `<rect class="chart-bar" x="${x}" y="${y}" width="${barWidth}" height="${barHeight}" fill="${barSeries.color}"></rect>`;
        }).join("");
      } else {
        seriesMarkup = config.series.map((series) => {
          const points = series.values.map((value, index) => {
            const x = margin.left + (innerWidth / Math.max(series.values.length - 1, 1)) * index;
            const y = margin.top + innerHeight - ((value - minValue) / range) * innerHeight;
            return `${x},${y}`;
          }).join(" ");
          const dots = series.values.map((value, index) => {
            const x = margin.left + (innerWidth / Math.max(series.values.length - 1, 1)) * index;
            const y = margin.top + innerHeight - ((value - minValue) / range) * innerHeight;
            return `<circle class="chart-series-dot" cx="${x}" cy="${y}" r="4" fill="${series.color}"></circle>`;
          }).join("");
          return `<polyline class="chart-series-line" points="${points}" stroke="${series.color}"></polyline>${dots}`;
        }).join("");
      }

      const legend = `<div class="chart-title-note">${config.series.map((item) => `<span><i style="background:${item.color};"></i>${item.name}</span>`).join("")}</div>`;
      return `<svg viewBox="0 0 ${width} ${height}" class="material-line-chart-svg">${gridLines}${axis}${seriesMarkup}${xLabels}${yLabels}</svg>${legend}`;
    }

    function getMaterialProfile(material) {
      if (state.selectedMaterialSource === "electrolyte") {
        return {
          viewTitle: material.structureView.title,
          infoTitle: "基础信息",
          dataTitle: "数据属性",
          metricsTitle: "材料性质详情",
          chartTitle: "对应图谱与可视化",
          structureView: material.structureView,
          detailTabs: material.detailTabs,
          visualTabs: material.visualTabs,
          visuals: material.visuals
        };
      }

      const visualProfile = buildTwodVisualProfile(material);

      return {
        viewTitle: "3D晶体结构",
        infoTitle: "基本信息",
        dataTitle: "数据信息",
        metricsTitle: "材料性质详情",
        chartTitle: "物性可视化图谱",
        structureView: buildTwodStructureView(material),
        detailTabs: materialDetailTabs,
        visualTabs: visualProfile.visualTabs,
        visuals: visualProfile.visuals
      };
    }

    function renderMaterialInfo(material) {
      const profile = getMaterialProfile(material);
      const infoWrap = document.getElementById("materialInfoGrid");
      const dataWrap = document.getElementById("materialDataGrid");
      const infoFields = state.selectedMaterialSource === "electrolyte"
        ? material.infoFields
        : [
            { label: "化学式", value: material.formula },
            { label: "空间群", value: material.spaceGroup },
            { label: "晶系", value: material.crystalSystem }
          ];
      const dataFields = state.selectedMaterialSource === "electrolyte"
        ? material.dataFields
        : [
            { label: "数据来源", value: material.source },
            { label: "更新时间", value: material.updatedAt },
            { label: "数据质量", value: material.quality },
            { label: "材料状态", value: material.status }
          ];

      document.getElementById("materialInfoPanelTitle").textContent = profile.infoTitle;
      document.getElementById("materialDataPanelTitle").textContent = profile.dataTitle;
      document.getElementById("materialMetricsTitle").textContent = profile.metricsTitle;
      document.getElementById("materialChartTitle").textContent = profile.chartTitle;

      infoWrap.innerHTML = infoFields.map((item) => `<div class="material-info-item"><span>${item.label}</span><strong>${item.value}</strong></div>`).join("");
      dataWrap.innerHTML = dataFields.map((item) => `<div class="material-info-item"><span>${item.label}</span><strong>${item.value}</strong></div>`).join("");
    }

    function renderMaterialStructure(material) {
      const profile = getMaterialProfile(material);
      const structure = profile.structureView;
      const wrap = document.getElementById("materialStructureCanvas");
      const legend = document.getElementById("materialLegend");
      document.getElementById("materialViewTitle").textContent = structure.title;
      document.getElementById("materialStructureCaption").textContent = structure.caption;

      wrap.innerHTML = `
        ${structure.bonds.map((bond) => {
          const from = structure.nodes[bond.from];
          const to = structure.nodes[bond.to];
          const dx = to.x - from.x;
          const dy = to.y - from.y;
          const length = Math.sqrt(dx * dx + dy * dy);
          const angle = Math.atan2(dy, dx) * (180 / Math.PI);
          return `<span class="material-bond" style="left:${from.x}%; top:${from.y}%; width:${length}%; transform:rotate(${angle}deg);"></span>`;
        }).join("")}
        ${structure.nodes.map((node) => `<span class="material-node" style="left:${node.x}%; top:${node.y}%; background:${node.color};">${node.label}</span>`).join("")}
      `;

      legend.innerHTML = (structure.legend || []).map((item) => `<span><i class="legend-dot" style="background:${item.color};"></i>${item.label}</span>`).join("");
    }

    function renderMaterialMetrics(material) {
      const profile = getMaterialProfile(material);
      const detailTabs = profile.detailTabs;
      const firstTab = Object.keys(detailTabs)[0];
      const activeTab = detailTabs[state.selectedMaterialTab] ? state.selectedMaterialTab : firstTab;
      state.selectedMaterialTab = activeTab;
      const metrics = detailTabs[activeTab] || [];
      const wrap = document.getElementById("materialMetricGrid");
      wrap.innerHTML = metrics.map((item) => `
        <article class="material-metric-card">
          <span>${item.label}</span>
          <strong>${formatMetricValue(material, item)}</strong>
        </article>
      `).join("");
    }

    function renderMaterialDetailTabs(material) {
      const profile = getMaterialProfile(material);
      const wrap = document.getElementById("materialDetailTabs");
      if (!wrap) return;
      const keys = Object.keys(profile.detailTabs);
      /* MLFF：唯一标签页就是该材料所属结构，确保选中态不落空 */
      if (state.selectedMaterialSource === "mlff" && keys.length && keys.indexOf(state.selectedMaterialTab) < 0) {
        state.selectedMaterialTab = keys[0];
      }
      wrap.innerHTML = keys.map((key) => `
        <button class="material-tab-btn${state.selectedMaterialTab === key ? " active" : ""}" type="button" data-material-tab="${key}">${MATERIAL_TAB_LABELS[key] || key}</button>
      `).join("");
      /* MLFF：在「材料性质」区追加该材料所属结构的样例记录表（Excel 真实字段）。
         先移除旧节点，保证切换材料 / 重复渲染不叠加。 */
      const host = wrap.closest(".material-section") || wrap.parentElement;
      if (host) {
        const oldHost = host.querySelector(".mlff-topic-sample-host");
        if (oldHost) oldHost.remove();
        if (state.selectedMaterialSource === "mlff" && typeof renderMlffTopicSampleTable === "function") {
          const data = getMlffTopicStructureData(material);
          if (data) {
            const box = document.createElement("div");
            box.className = "mlff-topic-sample-host";
            box.innerHTML = renderMlffTopicSampleTable(data);
            host.appendChild(box);
          }
        }
      }
    }

    function renderMaterialVisuals(material) {
      const profile = getMaterialProfile(material);
      const visuals = profile.visuals;
      const visualTabs = profile.visualTabs;
      const firstVisual = visualTabs[0]?.key;
      const activeVisual = visuals[state.selectedMaterialVisual] ? state.selectedMaterialVisual : firstVisual;
      state.selectedMaterialVisual = activeVisual;
      const currentVisual = visuals[activeVisual];
      const wrap = document.getElementById("materialVisualChips");
      wrap.innerHTML = visualTabs.map((item) => `
        <button class="material-visual-chip${state.selectedMaterialVisual === item.key ? " active" : ""}" type="button" data-material-visual="${item.key}">${item.label}</button>
      `).join("");
      document.getElementById("materialLineChart").innerHTML = buildChartSvg(currentVisual);
      document.getElementById("materialChartCaption").textContent = currentVisual.caption;
    }

    function renderMaterialModal(materialToken) {
      const parsed = parseMaterialToken(materialToken);
      const material = findMaterialBySource(parsed.source, parsed.id);
      state.selectedMaterialSource = parsed.source;
      state.selectedMaterialId = material.id;
      const profile = getMaterialProfile(material);
      state.selectedMaterialTab = Object.keys(profile.detailTabs)[0];
      state.selectedMaterialVisual = profile.visualTabs[0]?.key || "";
      document.getElementById("materialModalTitle").textContent = material.name;
      document.getElementById("materialModalSubtitle").textContent = `ID: ${material.id}${material.alias ? ` / ${material.alias}` : ""}`;
      renderMaterialInfo(material);
      renderMaterialStructure(material);
      renderMaterialDetailTabs(material);
      renderMaterialMetrics(material);
      renderMaterialVisuals(material);
      openModal("materialModal");
    }

    function parseElectrolyteElementText(rawValue) {
      const text = String(rawValue || "").trim();
      if (!text) return [];
      const normalizeSymbol = (token) => {
        const source = String(token || "").trim();
        if (!source) return "";
        return source.charAt(0).toUpperCase() + source.slice(1).toLowerCase();
      };
      const hasSeparator = /[+,，\s]+/.test(text);
      const parts = hasSeparator ? text.split(/[+,，\s]+/).map((item) => item.trim()).filter(Boolean) : [text];
      const symbols = parts.flatMap((part) => {
        const matches = String(part).match(/[A-Za-z][a-z]?/g);
        if (matches && matches.length) return matches.map(normalizeSymbol);
        return [normalizeSymbol(part)];
      }).filter(Boolean);
      return Array.from(new Set(symbols));
    }

    function getElectrolyteTypeTagClass(typeTag) {
      if (typeTag === "有机溶剂") return "tag-blue";
      if (typeTag === "锂盐") return "tag-purple";
      if (typeTag === "固态有机") return "tag-orange";
      return "tag-red";
    }

    function getElectrolyteSafetyTagClass(level) {
      if (level === "低风险") return "tag-green";
      if (level === "中等风险") return "tag-orange";
      return "tag-red";
    }

    function getElectrolyteBaseResults() {
      const category = state.electrolyteCategory;
      const filters = electrolyteUIState.baseFilters[category];
      return electrolyteMaterials.filter((item) => {
        if (item.electrolyteCategory !== category) return false;
        if (category === "solidInorganic") {
          const formulaMatch = !filters.formula || `${item.name} ${item.formula}`.toLowerCase().includes(filters.formula.toLowerCase());
          const keywordMatch = !filters.keyword || item.keywords.some((keyword) => keyword.toLowerCase().includes(filters.keyword.toLowerCase()));
          const elements = parseElectrolyteElementText(filters.elements);
          const elementMatch = !elements.length || elements.every((element) => item.elements.includes(element));
          return formulaMatch && keywordMatch && elementMatch;
        }
        const nameMatch = !filters.name || `${item.name} ${item.alias}`.toLowerCase().includes(filters.name.toLowerCase());
        const formulaMatch = !filters.formula || item.formula.toLowerCase().includes(filters.formula.toLowerCase());
        const codeMatch = !filters.code || item.code.toLowerCase().includes(filters.code.toLowerCase());
        const keywordMatch = !filters.keyword || item.keywords.some((keyword) => keyword.toLowerCase().includes(filters.keyword.toLowerCase()));
        return nameMatch && formulaMatch && codeMatch && keywordMatch;
      });
    }

    function getElectrolytePropertyResults() {
      const category = state.electrolyteCategory;
      const filters = electrolyteUIState.propertyFilters[category];
      return electrolyteMaterials.filter((item) => {
        if (item.electrolyteCategory !== category) return false;

        if (category === "organicLiquid") {
          const numberChecks = [
            ["homo", "homoMin", "homoMax"],
            ["lumo", "lumoMin", "lumoMax"],
            ["dipole", "dipoleMin", "dipoleMax"],
            ["heatForm", "heatMin", "heatMax"],
            ["gibbs", "gibbsMin", "gibbsMax"],
            ["solvation", "solvationMin", "solvationMax"]
          ];
          const numericMatch = numberChecks.every(([key, minKey, maxKey]) => {
            const min = parseNumberValue(filters[minKey]);
            const max = parseNumberValue(filters[maxKey]);
            const current = Number(item[key]);
            if (min != null && current < min) return false;
            if (max != null && current > max) return false;
            return true;
          });
          const spectraMatch = filters.spectra.every((key) => item.visuals[key]);
          const hazardMatch = filters.hazard === "不限" || item.hazardLevel === filters.hazard;
          const ghsMatch = !filters.ghs || item.ghs.toLowerCase().includes(filters.ghs.toLowerCase());
          const referenceMatch = !filters.reference || `${item.name} ${item.alias} ${item.cas}`.toLowerCase().includes(filters.reference.toLowerCase());
          const trendMatch = !filters.trend || item.similarityTrend === filters.trend;
          return numericMatch && spectraMatch && hazardMatch && ghsMatch && referenceMatch && trendMatch;
        }

        if (category === "solidOrganic") {
          const heatMin = parseNumberValue(filters.heatMin);
          const heatMax = parseNumberValue(filters.heatMax);
          const bindMin = parseNumberValue(filters.bindMin);
          const bindMax = parseNumberValue(filters.bindMax);
          const heatMatch = (heatMin == null || item.heatCapacity >= heatMin) && (heatMax == null || item.heatCapacity <= heatMax);
          const bindMatch = (bindMin == null || item.bindingEnergy >= bindMin) && (bindMax == null || item.bindingEnergy <= bindMax);
          const targetMatch = !filters.target || `${item.name} ${item.alias} ${item.solventTarget || ""}`.toLowerCase().includes(filters.target.toLowerCase());
          const solventMatch = filters.solventPreference === "不限" || (filters.solventPreference === "极性醚类" && item.alias === "PEO");
          return heatMatch && bindMatch && targetMatch && solventMatch;
        }

        const formationMin = parseNumberValue(filters.formationMin);
        const formationMax = parseNumberValue(filters.formationMax);
        const fermiMin = parseNumberValue(filters.fermiMin);
        const fermiMax = parseNumberValue(filters.fermiMax);
        const bandGapMin = parseNumberValue(filters.bandGapMin);
        const bandGapMax = parseNumberValue(filters.bandGapMax);
        const formationMatch = (formationMin == null || item.formationEnergy >= formationMin) && (formationMax == null || item.formationEnergy <= formationMax);
        const fermiMatch = (fermiMin == null || item.fermi >= fermiMin) && (fermiMax == null || item.fermi <= fermiMax);
        const bandGapMatch = (bandGapMin == null || item.bandGapValue >= bandGapMin) && (bandGapMax == null || item.bandGapValue <= bandGapMax);
        const elements = parseElectrolyteElementText(filters.elements);
        const elementsMatch = !elements.length || elements.every((element) => item.elements.includes(element));
        const refMatch = !filters.reference || `${item.name} ${item.formula} ${item.source}`.toLowerCase().includes(filters.reference.toLowerCase());
        const linkMatch = !filters.onlyLinked || Boolean(item.detailTabs.external);
        const spectraMatch = filters.spectra.every((key) => item.visuals[key]);
        return formationMatch && fermiMatch && bandGapMatch && elementsMatch && refMatch && linkMatch && spectraMatch;
      });
    }

    function renderElectrolyteResultTable(list) {
      const category = state.electrolyteCategory;
      const isSolidOrganic = category === "solidOrganic";
      const isSolidInorganic = category === "solidInorganic";
      const columns = isSolidOrganic
        ? ["材料编号", "中文名称", "英文简称", "分子式", "燃点", "摩尔体积", "密度", "数据来源", "操作"]
        : isSolidInorganic
          ? ["材料编号", "中文名称", "英文简称", "分子式", "带隙", "密度", "形成能", "数据来源", "操作"]
          : ["材料名称", "分子式", "CAS号", "电解质类型", "电导率", "安全等级", "操作"];
      const valueOrDash = (value) => value == null || value === "" ? "—" : value;
      const detailValue = (item, labels) => valueOrDash(findElectrolyteDetailValue(item, labels));
      const rows = list.length ? list.map((item) => {
        const operation = `<div class="table-actions">
          <button class="electrolyte-link-btn" type="button" data-open-material="electrolyte:${item.id}" onclick="return handleMaterialDetailOpen('electrolyte:${item.id}')">查看详情</button>
          <button class="electrolyte-link-btn" type="button" data-algo-predict-material="${item.id}">发起预测</button>
        </div>`;
        if (isSolidOrganic) return `<tr>
          <td>${valueOrDash(item.code || item.id)}</td>
          <td><strong>${valueOrDash(item.name)}</strong></td>
          <td>${valueOrDash(item.alias)}</td>
          <td>${valueOrDash(item.formula)}</td>
          <td>${valueOrDash(item.ignitionPoint || item.firePoint || findElectrolyteDetailValue(item, ["燃点", "闪点"]))}</td>
          <td>${valueOrDash(item.molarVolume || findElectrolyteDetailValue(item, ["摩尔体积"]))}</td>
          <td>${valueOrDash(item.density || findElectrolyteDetailValue(item, ["密度"]))}</td>
          <td>${valueOrDash(item.source)}</td>
          <td>${operation}</td>
        </tr>`;
        if (isSolidInorganic) return `<tr>
          <td>${valueOrDash(item.code || item.id)}</td>
          <td><strong>${valueOrDash(item.name)}</strong></td>
          <td>${valueOrDash(item.alias)}</td>
          <td>${valueOrDash(item.formula)}</td>
          <td>${valueOrDash(item.bandGapValue || findElectrolyteDetailValue(item, ["带隙"]))}</td>
          <td>${valueOrDash(item.density || findElectrolyteDetailValue(item, ["密度"]))}</td>
          <td>${valueOrDash(item.formationEnergy || findElectrolyteDetailValue(item, ["形成能"]))}</td>
          <td>${valueOrDash(item.source)}</td>
          <td>${operation}</td>
        </tr>`;
        return `<tr>
          <td><div class="electrolyte-name-cell"><strong>${item.name}</strong><span>${item.alias}</span></div></td>
          <td>${item.formula}</td><td>${item.cas}</td>
          <td><span class="${getElectrolyteTypeTagClass(item.typeTag)}">${item.typeTag}</span></td>
          <td>${item.conductivityLabel}</td>
          <td><span class="${getElectrolyteSafetyTagClass(item.safety)}">${item.safety}</span></td>
          <td>${operation}</td>
        </tr>`;
      }).join("") : `<tr><td colspan="${columns.length}" class="table-empty">暂无符合条件的数据</td></tr>`;
      return `
        <div class="card table-card electrolyte-result-card">
          <div class="table-head"><div><h3>检索结果</h3><p class="section-subtitle" style="margin:10px 0 0;">基于当前检索条件返回对应电解质材料数据。</p></div></div>
          <div class="table-wrap"><table><thead><tr>${columns.map((column) => `<th>${column}</th>`).join("")}</tr></thead><tbody>${rows}</tbody></table></div>
          <div class="result-footer"><span>显示 1 - ${list.length || 0} 条，共 ${list.length} 条结果</span><div class="pagination"><div class="pager"><button type="button">上一页</button><button type="button" class="active">1</button><button type="button">下一页</button></div></div></div>
        </div>
      `;
    }
    function buildElectrolyteRangeField(label, minId, maxId, minValue, maxValue) {
      return `
        <div class="field">
          <label>${label}</label>
          <div class="electrolyte-range-row">
            <input id="${minId}" type="text" value="${minValue}" placeholder="最低">
            <span>-</span>
            <input id="${maxId}" type="text" value="${maxValue}" placeholder="最高">
          </div>
        </div>
      `;
    }

    function renderSolidOrganicPropertyPanel(filters) {
      return `
        <div class="electrolyte-inline-meta">
          <div>当前电解质类型：<strong>固态有机电解质</strong></div>
          <div>请在下方的检索表单中输入相关检索要求，系统将为您显示详细的分子性质信息。</div>
        </div>
        <div class="electrolyte-filter-card">
          <h4>固体有机电解质计算信息</h4>
          <div class="electrolyte-range-grid">
            ${buildElectrolyteRangeField("摩尔热容范围 (J/mol·K)", "elyProp_heatMin", "elyProp_heatMax", filters.heatMin, filters.heatMax)}
            ${buildElectrolyteRangeField("结合能范围 (kJ/mol)", "elyProp_bindMin", "elyProp_bindMax", filters.bindMin, filters.bindMax)}
          </div>
        </div>
        <div class="electrolyte-filter-card">
          <h4>溶解溶剂推荐</h4>
          <div class="electrolyte-search-grid two">
            <div class="field">
              <label>目标电解质材料</label>
              <input id="elyProp_target" type="text" value="${filters.target}" placeholder="输入需要溶解的电解质材料名称">
            </div>
            <div class="field">
              <label>溶剂类型偏好</label>
              <select id="elyProp_solventPreference">
                <option ${filters.solventPreference === "不限" ? "selected" : ""}>不限</option>
                <option ${filters.solventPreference === "极性醚类" ? "selected" : ""}>极性醚类</option>
                <option ${filters.solventPreference === "碳酸酯类" ? "selected" : ""}>碳酸酯类</option>
              </select>
            </div>
          </div>
        </div>
      `;
    }

    function renderSolidInorganicPropertyPanel(filters) {
      return `
        <div class="electrolyte-inline-meta">
          <div>当前电解质类型：<strong>固态无机电解质</strong></div>
          <div>请在下方的检索表单中输入相关检索要求，系统将为您显示详细的分子性质信息。</div>
        </div>
        <div class="electrolyte-filter-card">
          <h4>固态无机电解质图谱信息</h4>
          <div class="electrolyte-checkbox-row">
            <label><input type="checkbox" data-ely-prop-check="band" ${filters.spectra.includes("band") ? "checked" : ""}> 能带结构</label>
            <label><input type="checkbox" data-ely-prop-check="dos" ${filters.spectra.includes("dos") ? "checked" : ""}> 态密度</label>
            <label><input type="checkbox" data-ely-prop-check="xrd" ${filters.spectra.includes("xrd") ? "checked" : ""}> X射线衍射谱图</label>
            <label><input type="checkbox" data-ely-prop-check="absorption" ${filters.spectra.includes("absorption") ? "checked" : ""}> X射线吸收谱图</label>
          </div>
        </div>
        <div class="electrolyte-filter-card">
          <h4>固态无机电解质计算信息</h4>
          <div class="electrolyte-range-grid">
            ${buildElectrolyteRangeField("形成能范围 (eV/atom)", "elyProp_formationMin", "elyProp_formationMax", filters.formationMin, filters.formationMax)}
            ${buildElectrolyteRangeField("费米能级范围 (eV)", "elyProp_fermiMin", "elyProp_fermiMax", filters.fermiMin, filters.fermiMax)}
            ${buildElectrolyteRangeField("带隙范围 (eV)", "elyProp_bandGapMin", "elyProp_bandGapMax", filters.bandGapMin, filters.bandGapMax)}
          </div>
        </div>
        <div class="electrolyte-filter-card">
          <h4>外部数据关联</h4>
          <div class="electrolyte-search-grid two">
            <div class="field">
              <label>元素组成筛选</label>
              <input id="elyProp_elements" type="text" value="${filters.elements}" placeholder="如: Li, La, Zr, O">
            </div>
            <div class="field">
              <label>参考文献来源</label>
              <input id="elyProp_reference" type="text" value="${filters.reference}" placeholder="输入作者、期刊或DOI">
            </div>
          </div>
          <div class="electrolyte-checkbox-row" style="margin-top:16px;">
            <label><input id="elyProp_onlyLinked" type="checkbox" ${filters.onlyLinked ? "checked" : ""}> 仅显示有结构信息参考文献的材料</label>
          </div>
        </div>
      `;
    }

    function renderElectrolyteModule() {
      const root = document.getElementById("electrolyteApp");
      if (!root) return;
      const category = electrolyteCategoryConfigs[state.electrolyteCategory];
      const baseResults = getElectrolyteBaseResults();
      const propertyResults = getElectrolytePropertyResults();
      const currentResults = state.electrolyteTab === "property" ? propertyResults : getElectrolyteBaseResults();

      let bodyContent = "";
      if (state.electrolyteTab === "base") {
        const baseFieldsClass = category.baseFields.length === 3 ? "electrolyte-search-grid three" : "electrolyte-search-grid";
        bodyContent = `
          <div class="electrolyte-search-grid ${category.baseFields.length === 3 ? "three" : ""}">
            ${category.baseFields.map((field) => `
              <div class="field">
                <label>${field.label}</label>
                <input id="elyBase_${field.key}" type="text" value="${electrolyteUIState.baseFilters[state.electrolyteCategory][field.key] || ""}" placeholder="${field.placeholder}">
              </div>
            `).join("")}
          </div>
          <div class="electrolyte-actions">
            <div class="action-row">
              <button class="btn-primary" type="button" data-ely-search>搜索</button>
              <button class="btn" type="button" data-ely-reset>重置</button>
            </div>
            <div class="electrolyte-status-count">共找到 <strong>1,248</strong> 条相关数据</div>
          </div>
          ${renderElectrolyteResultTable(baseResults)}
        `;
      } else if (state.electrolyteTab === "property") {
        const filters = electrolyteUIState.propertyFilters[state.electrolyteCategory];
        if (state.electrolyteCategory === "organicLiquid") bodyContent = renderOrganicPropertyPanel(filters);
        if (state.electrolyteCategory === "solidOrganic") bodyContent = renderSolidOrganicPropertyPanel(filters);
        if (state.electrolyteCategory === "solidInorganic") bodyContent = renderSolidInorganicPropertyPanel(filters);
        bodyContent += `
          <div class="electrolyte-actions">
            <button class="btn" type="button" data-ely-reset>重置条件</button>
            <button class="btn-primary" type="button" data-ely-search>搜索性质数据</button>
          </div>
          ${renderElectrolyteResultTable(propertyResults)}
        `;
      } else {
        bodyContent = renderElectrolyteUpdateTable();
      }

      root.innerHTML = `
        <div class="electrolyte-shell">
          <div class="electrolyte-category-panel">
            <div class="electrolyte-category-grid">
              ${Object.values(electrolyteCategoryConfigs).map((item) => `
                <button class="electrolyte-category-card${state.electrolyteCategory === item.key ? " active" : ""}" type="button" data-ely-category="${item.key}">
                  <span class="electrolyte-category-icon">${item.icon}</span>
                  <div>
                    <h3>${item.title}</h3>
                    <p>${item.subtitle}</p>
                  </div>
                </button>
              `).join("")}
            </div>
          </div>
          <div class="electrolyte-workspace">
            <div class="electrolyte-tabs">
              <button class="electrolyte-tab${state.electrolyteTab === "base" ? " active" : ""}" type="button" data-ely-tab="base">基础检索</button>
              <button class="electrolyte-tab${state.electrolyteTab === "property" ? " active" : ""}" type="button" data-ely-tab="property">性质数据检索</button>
              <button class="electrolyte-tab${state.electrolyteTab === "update" ? " active" : ""}" type="button" data-ely-tab="update">数据处理更新</button>
            </div>
            <div class="electrolyte-body">
              ${bodyContent}
            </div>
          </div>
        </div>
      `;
    }

    function readElectrolyteBaseFiltersFromDom() {
      const target = electrolyteUIState.baseFilters[state.electrolyteCategory];
      Object.keys(target).forEach((key) => {
        const input = document.getElementById(`elyBase_${key}`);
        if (input) target[key] = input.value.trim();
      });
    }

    function readElectrolytePropertyFiltersFromDom() {
      const target = electrolyteUIState.propertyFilters[state.electrolyteCategory];
      if (state.electrolyteCategory === "organicLiquid") {
        target.spectra = Array.from(document.querySelectorAll("[data-ely-prop-check]:checked")).map((item) => item.getAttribute("data-ely-prop-check"));
        ["homoMin", "homoMax", "lumoMin", "lumoMax", "dipoleMin", "dipoleMax", "heatMin", "heatMax", "gibbsMin", "gibbsMax", "solvationMin", "solvationMax", "ghs", "reference"].forEach((key) => {
          const input = document.getElementById(`elyProp_${key}`);
          if (input) target[key] = input.value.trim();
        });
        target.hazard = document.getElementById("elyProp_hazard")?.value || "不限";
        target.trend = document.getElementById("elyProp_trend")?.value || "";
      } else if (state.electrolyteCategory === "solidOrganic") {
        ["heatMin", "heatMax", "bindMin", "bindMax", "target"].forEach((key) => {
          const input = document.getElementById(`elyProp_${key}`);
          if (input) target[key] = input.value.trim();
        });
        target.solventPreference = document.getElementById("elyProp_solventPreference")?.value || "不限";
      } else {
        target.spectra = Array.from(document.querySelectorAll("[data-ely-prop-check]:checked")).map((item) => item.getAttribute("data-ely-prop-check"));
        ["formationMin", "formationMax", "fermiMin", "fermiMax", "bandGapMin", "bandGapMax", "elements", "reference"].forEach((key) => {
          const input = document.getElementById(`elyProp_${key}`);
          if (input) target[key] = input.value.trim();
        });
        target.onlyLinked = Boolean(document.getElementById("elyProp_onlyLinked")?.checked);
      }
    }

