    function getAlgorithmSpecificCoS2Result(material, algorithm) {
      const formula = getTwodFormulaDisplay(material);
      const base = {
        materialId: getTwodMaterialDisplayId(material),
        materialName: getTwodMaterialDisplayName(material),
        algorithmId: algorithm.id,
        algorithmTitle: algorithm.title,
        structureDescription: getCoS2StructureDescription(),
        visuals: [
          {
            title: `${formula} 能带结构图`,
            src: material.demoAssets?.band || "Demo/CoS2_mp-aaabwjmf/plots/CoS2_mp-aaabwjmf_bandstructure.png",
            alt: `${formula} 能带结构图`,
            caption: `图片2：${formula} 能带结构图。`
          },
          {
            title: `${formula} 态密度图 (DOS)`,
            src: material.demoAssets?.dos || "Demo/CoS2_mp-aaabwjmf/plots/CoS2_mp-aaabwjmf_dos.png",
            alt: `${formula} 态密度图 DOS`,
            caption: `图片3：${formula} 态密度图 (DOS)。`
          }
        ],
        metrics: getCoS2PredictionMetrics()
      };

      const resultMap = {
        "twod-prop-structural": {
          priority: "结构特征预测完成",
          summary: `${formula} 被识别为正交 Pbca 黄铁矿型结构，结构预测重点落在 CoS₆ 八面体与 SCo₃S 四面体的共角连接，以及 Co-S / S-S 键长分布。`,
          recommendation: "建议优先复核 CoS₆ 八面体倾斜角、S-S 配对长度和局域配位在结构弛豫后的保持情况。",
          score: 86
        },
        "twod-prop-electronic": {
          priority: "电子结构预测完成",
          summary: `${formula} 的预测带隙为 0.0 eV，结合能带结构图与 DOS 图谱，当前按金属体系展示并重点关注费米能级附近态密度贡献。`,
          recommendation: "建议继续查看自旋分辨能带、费米能级 7.9598 eV 附近的分波 DOS，以及 Co-d / S-p 轨道贡献。",
          score: 90
        },
        "twod-prop-magnetic": {
          priority: "磁学性质预测完成",
          summary: `${formula} 预测为 FM 铁磁体系，总磁化强度为 4.0122 μB/cell, 1.003 μB/f.u.，磁性主要由 Co 位点贡献。`,
          recommendation: "建议补充 FM/AFM/NM 多自旋初态对比，并复核 Co 局域磁矩与交换作用趋势。",
          score: 88
        },
        "twod-prop-thermal": {
          priority: "热力学稳定性预测完成",
          summary: `${formula} 的预测形成能为 -0.4529 eV/atom，能量距凸包仅 0.0019 eV/atom，属于近稳定候选但当前页面仍按非稳定结果展示。`,
          recommendation: "建议继续补充声子谱、AIMD 与高精度凸包复核，确认该近稳定金属铁磁相是否可保留。",
          score: 87
        }
      };

      const fallbackBySlug = algorithm.id.includes("relax")
        ? {
            priority: "结构弛豫建议生成",
            summary: `${formula} 建议优先采用自旋极化结构弛豫，重点检查 Pbca 对称性、CoS₆ 八面体和 S-S 配对是否在弛豫后保持稳定。`,
            recommendation: "弛豫后复核 Co-S 键长范围、S-S 键长和总磁矩是否仍与当前预测结果一致。",
            score: 85
          }
        : {
            priority: `${algorithm.title}预测完成`,
            summary: `${formula} 已按 ${algorithm.title} 生成候选预测结果，当前核心判断仍为黄铁矿型、金属、铁磁和近稳定候选。`,
            recommendation: "建议结合结构、电子和磁性结果做交叉复核，再决定是否进入验证队列。",
            score: 84
          };

      const specific = resultMap[algorithm.id] || fallbackBySlug;
      return {
        ...base,
        ...specific
      };
    }

