    function renderSelectableRecordList(records, selectedId, dataAttr) {
      if (!records.length) return `<div class="workflow-empty">当前筛选条件下暂无可提交记录。</div>`;
      return `
        <div class="record-select-list">
          ${records.map((record) => {
            const disabled = !canSubmitRecord(record);
            return `
              <label class="record-select-item ${disabled ? "disabled" : ""}">
                <input type="radio" name="${dataAttr}" data-record-select="${dataAttr}" value="${record.id}" ${selectedId === record.id ? "checked" : ""} ${disabled ? "disabled" : ""}>
                <div>
                  <strong>${record.fileName}</strong>
                  <span>${record.uploadedAt} · ${record.fileSizeText} · ${record.sourceFormat}</span>
                  <div class="record-meta-line">
                    <span class="record-meta-pill ${getFileCategoryPillClass(record.fileCategory)}">${record.fileCategory}</span>
                    ${record.reviewStatus ? `<span class="record-meta-pill ${getReviewStatusPillClass(record.reviewStatus)}">${record.reviewStatus}</span>` : ""}
                    <span class="record-meta-pill">${record.sourceType}</span>
                  </div>
                </div>
              </label>
            `;
          }).join("")}
        </div>
      `;
    }

