    function renderRecordDetailBody(record, moduleName) {
      const reviewSection = record.fileCategory === "数据处理更新" ? `
        <div class="detail-card" style="margin-top:16px;">
          <h4>审核状态</h4>
          <div class="status-badge ${record.reviewStatus === "审核通过" ? "status-approved" : record.reviewStatus === "审核不通过" ? "status-rejected" : "status-pending"}">${record.reviewStatus}</div>
          <div class="status-message ${record.reviewStatus === "审核通过" ? "status-message-success" : record.reviewStatus === "审核不通过" ? "status-message-error" : "status-message-warning"}">
            ${record.reviewStatus === "审核通过"
              ? "当前数据已审核通过，已进入公开数据库。"
              : record.reviewStatus === "审核不通过"
                ? "当前数据审核未通过，可补充信息后重新提交。"
                : "当前数据正在审核中，审核通过前仅当前用户可见。"}
          </div>
        </div>
      ` : `
        <div class="status-message status-message-neutral" style="margin-top:16px;">
          当前记录为草稿，仅展示基本信息；如需下载，请使用表格中的“下载”操作。
        </div>
      `;
      return `
        <div class="detail-card">
          <h4>${moduleName}记录基本信息</h4>
          <div class="detail-grid">
            <strong>上传时间</strong><div>${record.uploadedAt}</div>
            <strong>文件名称</strong><div>${record.fileName}</div>
            <strong>文件大小</strong><div>${record.fileSizeText}</div>
            <strong>文件类别</strong><div><span class="record-meta-pill ${getFileCategoryPillClass(record.fileCategory)}">${record.fileCategory}</span></div>
            <strong>来源类型</strong><div>${record.sourceType}</div>
            <strong>源文件格式</strong><div>${record.sourceFormat}</div>
            <strong>数据来源</strong><div>${record.dataSource || "未填写"}</div>
            <strong>材料名称</strong><div>${record.materialName || "未填写"}</div>
            <strong>材料类型</strong><div>${record.materialType || "未填写"}</div>
            <strong>数据描述</strong><div>${record.dataDescription || "未填写"}</div>
          </div>
        </div>
        ${reviewSection}
      `;
    }

