    function ensureMlffRuntimeState() {
      ensureMlffStyles();
      if (!state.mlffSearchMode) state.mlffSearchMode = "name";
      if (!state.mlffPage) state.mlffPage = 1;
      if (!state.mlffPageSize) state.mlffPageSize = 5;
      if (!state.mlffGlossaryTab) state.mlffGlossaryTab = "definition";
      if (!state.selectedMlffId) state.selectedMlffId = mlffMaterials[0]?.id || "";
      if (!state.mlffSearchDraft) {
        state.mlffSearchDraft = {
          name: "",
          formula: "",
          propertyField: "charge",
          propertyKeyword: ""
        };
      }
      if (!MLFF_PROPERTY_FIELDS.some((item) => item.key === state.mlffSearchDraft.propertyField)) {
        state.mlffSearchDraft.propertyField = MLFF_PROPERTY_FIELDS[0].key;
      }
      if (!state.mlffAppliedSearch) {
        state.mlffAppliedSearch = {
          mode: "",
          filters: null
        };
      }
      if (!state.mlffUploadDraft) {
        state.mlffUploadDraft = {
          fileRole: "",
          fileName: "",
          sourceFormat: "",
          sizeBytes: 0,
          fileSizeText: ""
        };
      }
      if (!state.mlffUploadForm) {
        state.mlffUploadForm = {
          materialName: "",
          dataSource: "自有数据集",
          description: ""
        };
      }
      if (!state.mlffConvertDraft) {
        state.mlffConvertDraft = {
          materialId: mlffMaterials[0]?.id || "",
          sourceFormat: "XYZ",
          targetFormat: "PDB",
          connected: false
        };
      }
    }

    function getMlffModeLabel(mode) {
      return MLFF_SEARCH_MODES.find((item) => item.key === mode)?.label || "化学名称检索";
    }

    function getMlffCurrentDraftValue(mode) {
      if (mode === "name") return state.mlffSearchDraft.name.trim();
      if (mode === "formula") return state.mlffSearchDraft.formula.trim();
      return state.mlffSearchDraft.propertyKeyword.trim();
    }

    function hasMlffActiveFilters(mode, filters) {
      if (!filters) return false;
      if (mode === "property") return Boolean((filters.field || "").trim() || (filters.keyword || "").trim());
      return Boolean(String(filters || "").trim());
    }

    function applyMlffSearch() {
      const mode = state.mlffSearchMode;
      let filters = "";
      if (mode === "name") {
        filters = state.mlffSearchDraft.name.trim();
      } else if (mode === "formula") {
        filters = state.mlffSearchDraft.formula.trim();
      } else {
        filters = {
          field: state.mlffSearchDraft.propertyField,
          keyword: state.mlffSearchDraft.propertyKeyword.trim()
        };
      }
      state.mlffAppliedSearch = { mode, filters };
      state.mlffPage = 1;
    }

    function clearCurrentMlffModeDraft() {
      const mode = state.mlffSearchMode;
      if (mode === "name") state.mlffSearchDraft.name = "";
      if (mode === "formula") state.mlffSearchDraft.formula = "";
      if (mode === "property") {
        state.mlffSearchDraft.propertyField = MLFF_PROPERTY_FIELDS[0].key;
        state.mlffSearchDraft.propertyKeyword = "";
      }
      state.mlffAppliedSearch = { mode: "", filters: null };
      state.mlffPage = 1;
    }

    function getMlffDefaultHint() {
      return `当前处于“${getMlffModeLabel(state.mlffSearchMode)}”，结果栏默认展示机器学习力场数据库已收录的全部数据，可按当前模式输入条件进一步筛选。`;
    }

    function filterMlffMaterials(mode, filters) {
      if (!hasMlffActiveFilters(mode, filters)) return mlffMaterials.slice();
      if (mode === "name") {
        const keyword = String(filters).toLowerCase();
        return mlffMaterials.filter((item) => `${item.name} ${item.english}`.toLowerCase().includes(keyword));
      }
      if (mode === "formula") {
        const keyword = String(filters).toLowerCase();
        return mlffMaterials.filter((item) => String(item.formula || "").toLowerCase().includes(keyword));
      }

      const field = filters.field || MLFF_PROPERTY_FIELDS[0].key;
      const keyword = String(filters.keyword || "").toLowerCase();
      return mlffMaterials.filter((item) => {
        if (!keyword) return true;
        const chargeText = [
          item.parameterName,
          item.parameterValue,
          item.chargeValues?.map((value) => Number(value).toFixed(3)).join(", "),
          item.chargeValues?.join(", ")
        ].filter(Boolean).join(" ");
        const multipoleText = [
          item.parameterName,
          item.parameterValue,
          item.dipole != null ? `${item.dipole} D` : "",
          item.energy != null ? `${item.energy}` : ""
        ].filter(Boolean).join(" ");
        const moleculeText = [
          item.name,
          item.english,
          item.formula,
          item.atoms,
          item.bond,
          item.structureType
        ].filter(Boolean).join(" ");
        const smallSystemText = [
          item.name,
          item.formula,
          item.atoms,
          item.bond,
          item.structureType,
          item.parameterName,
          item.parameterValue
        ].filter(Boolean).join(" ");
        const largeSystemText = [
          item.forceField,
          item.method,
          item.parameterName,
          item.parameterValue,
          item.citation,
          item.source
        ].filter(Boolean).join(" ");
        const searchSourceMap = {
          charge: chargeText,
          multipole: multipoleText,
          molecule: moleculeText,
          smallSystem: smallSystemText,
          largeSystem: largeSystemText
        };
        return String(searchSourceMap[field] || moleculeText).toLowerCase().includes(keyword);
      });
    }

    function getMlffResultList() {
      ensureMlffRuntimeState();
      const applied = state.mlffAppliedSearch;
      if (!applied.mode || !hasMlffActiveFilters(applied.mode, applied.filters)) {
        return mlffMaterials.slice();
      }
      return mlffMaterials.slice();
    }

    function getMlffResultHint(list) {
      const applied = state.mlffAppliedSearch;
      if (!applied.mode || !hasMlffActiveFilters(applied.mode, applied.filters)) return getMlffDefaultHint();
      return `当前已按“${getMlffModeLabel(applied.mode)}”筛选出 ${list.length} 条匹配数据。`;
    }

    function renderMlffModeWorkspace() {
      const mode = state.mlffSearchMode;
      if (mode === "property") {
        const currentField = state.mlffSearchDraft.propertyField || MLFF_PROPERTY_FIELDS[0].key;
        const canApply = Boolean(state.mlffSearchDraft.propertyKeyword.trim());
        return `
          <div class="twod-mode-panel active">
            <div class="twod-property-panel">
              <div class="twod-property-panel-head">
                <div>
                  <h3>性质数据检索</h3>
                </div>
              </div>
              <div class="search-grid two">
                <div class="field">
                  <label>性质数据</label>
                  <select id="mlffPropertyField">
                    ${MLFF_PROPERTY_FIELDS.map((item) => `<option value="${item.key}" ${currentField === item.key ? "selected" : ""}>${item.label}</option>`).join("")}
                  </select>
                </div>
                <div class="field">
                  <label>输入内容</label>
                  <input id="mlffPropertyKeyword" type="text" value="${state.mlffSearchDraft.propertyKeyword}" placeholder="${MLFF_PROPERTY_PLACEHOLDERS[currentField] || "请输入对应内容"}">
                </div>
              </div>
              <div class="twod-platform-actions">
                <div class="twod-detail-actions">
                  <button class="btn twod-search-reset" type="button" data-mlff-reset>清空条件</button>
                  <button class="btn-primary" type="button" data-mlff-apply ${canApply ? "" : "disabled"}>检索</button>
                </div>
              </div>
            </div>
          </div>
        `;
      }

      const config = MLFF_SEARCH_MODES.find((item) => item.key === mode);
      const value = mode === "name" ? state.mlffSearchDraft.name : state.mlffSearchDraft.formula;
      return `
        <div class="twod-mode-panel active">
          <div class="twod-search-row">
            <label class="twod-search-input">
              <span>检</span>
              <input type="text" data-mlff-mode-input="${mode}" value="${value}" placeholder="${config.placeholder}">
            </label>
            <button class="btn-primary twod-search-submit" type="button" data-mlff-apply>检索</button>
          </div>
          <div class="twod-platform-actions">
            <div class="twod-status-text">${config.helper}</div>
            <button class="btn twod-search-reset" type="button" data-mlff-reset>清空条件</button>
          </div>
        </div>
      `;
    }

    function renderMlffResultRows(list) {
      if (!list.length) {
        return `<tr><td colspan="4" class="opto-table-empty">未检索到符合条件的机器学习力场数据，请调整检索条件后重试。</td></tr>`;
      }
      return list.map((item) => `
        <tr>
          <td><button class="twod-material-link" type="button" data-open-material="mlff:${item.id}" data-material-view="basic">${formatLowDimValue(item.name)}</button></td>
          <td><em>${formatLowDimValue(item.formula)}</em></td>
          <td>${renderLowDimDatasetSource(item, "mlff")}</td>
          <td>
            <div class="twod-record-inline-actions">
              <button class="twod-action-view" type="button" data-open-material="mlff:${item.id}" data-material-view="basic" data-mlff-topic-structure="${resolveMlffTopicStructure(item)}" title="查看详情（${(MLFF_STRUCTURE_META[resolveMlffTopicStructure(item)] || MLFF_STRUCTURE_META.molecule).label}）">查看详情</button>
              <button class="twod-record-link" type="button" data-open-material="mlff:${item.id}" data-material-view="prediction">发起预测</button>
            </div>
          </td>
        </tr>
      `).join("");
    }

    function renderMlffPagination(totalPages) {
      const current = Math.min(state.mlffPage, totalPages);
      return renderSharedPaginationButtons(totalPages, current, "data-mlff-page");
    }

    function renderMlffGlossarySection() {
      const isDefinition = state.mlffGlossaryTab === "definition";
      const definitionBody = `
        <div class="table-wrap">
          <table class="summary-table">
            <thead>
              <tr>
                <th>首字母</th>
                <th>术语名称</th>
                <th>英文名称</th>
                <th>定义说明</th>
                <th>单位</th>
              </tr>
            </thead>
            <tbody>
              ${mlffGlossaryDefinitions.map((item) => `
                <tr>
                  <td><strong>${item.letter}</strong></td>
                  <td>${item.cn}</td>
                  <td>${item.en}</td>
                  <td>${item.desc}</td>
                  <td>${item.unit}</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      `;
      const methodBody = `
        <div class="mlff-method-list">
          ${mlffGlossaryMethods.map((item) => {
            const toneColors = { blue: { bg: '#e8f0fe', fg: '#1660ff' }, purple: { bg: '#f3e8ff', fg: '#8c46ff' }, green: { bg: '#e8f8f0', fg: '#21a65d' }, orange: { bg: '#fff3e0', fg: '#e87722' } };
            const tc = toneColors[item.tone] || toneColors.blue;
            const iconMap = { dft: '🔬', mlp: '🤖', expfit: '', fffit: '⚙️', lit: '' };
            const icon = iconMap[item.id] || '📋';
            return `
              <article class="mlff-method-card">
                <div class="mlff-method-card-header">
                  <div class="mlff-method-card-title-row">
                    <div class="mlff-method-icon" style="background:${tc.bg};font-size:20px;">${icon}</div>
                    <div class="mlff-method-card-title-info">
                      <h4>${item.title} <span class="mlff-method-type-badge" style="background:${tc.bg};color:${tc.fg};">${item.type}</span></h4>
                      <div class="mlff-method-card-subtitle">${item.shortTitle} · 使用频率：${item.frequency}</div>
                    </div>
                  </div>
                  <div class="mlff-method-card-actions">
                    <button class="mlff-detail-btn" type="button" data-mlff-method-detail>查看详情</button>
                    <button class="mlff-fav-btn" type="button" title="收藏">☆</button>
                  </div>
                </div>
                <div class="mlff-method-section mlff-method-desc-section">
                  <div class="mlff-method-section-title"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></svg> 方法说明</div>
                  <p>${item.desc}</p>
                </div>
                <div class="mlff-method-section mlff-method-analysis-section">
                  <div class="mlff-method-section-title"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 20V10M12 20V4M6 20v-6"/></svg> 方法分析</div>
                  <div class="mlff-method-analysis-content">
                    <span class="mlff-method-pros">✓ 优势：${(item.analysis || {}).pros || "数据可信度高"}</span>
                    <span class="mlff-method-cons">✗ 不足：${(item.analysis || {}).cons || "获取成本较高"}</span>
                    <span class="mlff-method-apply">适用于：${(item.analysis || {}).apply || item.scope || "力场参数获取"}</span>
                  </div>
                </div>
                <div class="mlff-method-footer">
                  <div class="mlff-method-params">
                    <span class="mlff-method-params-label">关联参数：</span>
                    ${(item.params || ["力场参数"]).map(p => '<span class="mlff-method-param-tag">' + p + '</span>').join('')}
                  </div>
                  <div class="mlff-method-updated"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg> 更新于 ${item.updatedAt}</div>
                </div>
              </article>
            `;
          }).join("")}
        </div>
      `;
      return `
        <section class="card table-card mlff-glossary-anchor" id="mlffGlossarySection">
          <div style="padding:24px;">
            <div class="mlff-glossary-nav">
              <button class="btn${isDefinition ? "-primary" : ""}" type="button" data-mlff-glossary-tab="definition">参数数据定义表</button>
              <button class="btn${!isDefinition ? "-primary" : ""}" type="button" data-mlff-glossary-tab="method">数据获取方法表</button>
            </div>
            ${isDefinition ? definitionBody : methodBody}
          </div>
        </section>
      `;
    }

    function renderMlffGlossaryModalContent() {
      const body = document.getElementById("mlffGlossaryModalBody");
      if (!body) return;
      body.innerHTML = renderMlffGlossarySection();
    }

    function openMlffGlossaryModal() {
      ensureMlffRuntimeState();
      renderMlffGlossaryModalContent();
      openModal("mlffGlossaryModal");
    }

    function renderMlffModule() {
      ensureMlffRuntimeState();
      const page = document.getElementById("page-mlff");
      if (!page) return;
      const resultList = getMlffResultList();
      const total = resultList.length;
      const totalPages = Math.max(1, Math.ceil(total / state.mlffPageSize));
      state.mlffPage = Math.min(state.mlffPage, totalPages);
      const start = (state.mlffPage - 1) * state.mlffPageSize;
      const pageRows = resultList.slice(start, start + state.mlffPageSize);

      page.innerHTML = `
        <div class="page-head">
          <div>
            <h2>机器学习力场应用</h2>
            <p>整体交互与二维材料数据应用、电解质材料数据应用模块保持一致，支持检索、详情查看、文件格式转换、数据上传和术语表查看。</p>
          </div>
        </div>
        <div class="twod-platform-shell">
          <section class="card twod-search-platform">
            <div class="twod-search-hero">
              <div class="twod-search-copy">
                <span class="twod-search-eyebrow">机器学习力场应用模块</span>
                <h3>机器学习力场检索平台</h3>
                <p>通过模式选择器切换不同检索方式，下方仅显示当前检索项对应的输入条件；检索结果栏默认展示数据库已收录的全部数据。</p>
              </div>
              <div class="twod-mode-selector" id="mlffModeSelector">
                ${MLFF_SEARCH_MODES.map((item) => `<button class="twod-mode-btn${state.mlffSearchMode === item.key ? " active" : ""}" type="button" data-mlff-mode="${item.key}">${item.label}</button>`).join("")}
              </div>
            </div>
            <div class="twod-mode-stage" id="mlffModeWorkspace">${renderMlffModeWorkspace()}</div>
          </section>
          <section class="card twod-search-results">
            <div class="twod-results-head">
              <div>
                <div class="twod-result-count">找到 <strong>${total}</strong> 条相关数据</div>
                <p class="twod-result-hint">${getMlffResultHint(resultList)}</p>
              </div>
              <div class="twod-result-actions">
                <button class="btn-primary" type="button" data-mlff-open-upload>数据上传</button>
                <button class="btn" type="button" data-mlff-glossary-jump>数据术语表</button>
              </div>
            </div>
            <div class="table-wrap twod-result-table-wrap">
              <table class="twod-result-table">
                <thead>
                  <tr>
                    <th>材料名称</th>
                    <th>分子式</th>
                    <th>计算方法</th>
                    <th>核心参数项</th>
                    <th>数据来源</th>
                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>${renderMlffResultRows(pageRows)}</tbody>
              </table>
            </div>
            <div class="result-footer twod-result-footer">
              ${renderSharedPaginationFooter({
                total,
                currentPage: state.mlffPage,
                totalPages,
                pageSize: state.mlffPageSize,
                pageSizeId: "mlffPageSizeFinal",
                pageAttr: "data-mlff-page",
                jumpModule: "mlff"
              })}
            </div>
          </section>
        </div>
      `;
    }

    function formatMlffFileSize(sizeBytes) {
      if (!sizeBytes) return "0 B";
      if (sizeBytes < 1024) return `${sizeBytes} B`;
      if (sizeBytes < 1024 * 1024) return `${(sizeBytes / 1024).toFixed(1)} KB`;
      return `${(sizeBytes / (1024 * 1024)).toFixed(1)} MB`;
    }

    function inferMlffFileFormat(fileName) {
      const ext = String(fileName || "").split(".").pop().toUpperCase();
      return ext || "未识别";
    }

    function getMlffNowText() {
      const now = new Date();
      const pad = (value) => String(value).padStart(2, "0");
      return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}`;
    }

    function getMlffUploadFileLabel(key) {
      return MLFF_UPLOAD_FILE_TYPES.find((item) => item.key === key)?.label || "未分类文件";
    }

    function resetMlffUploadState() {
      revokeUploadPreviewUrl(state.mlffUploadDraft?.previewUrl);
      state.mlffUploadDraft = {
        fileRole: "",
        fileName: "",
        sourceFormat: "",
        sizeBytes: 0,
        fileSizeText: "",
        previewUrl: ""
      };
      state.mlffUploadForm = {
        materialName: "",
        dataSource: "自有数据集",
        description: ""
      };
    }

    function canSubmitMlffUpload() {
      const draft = state.mlffUploadDraft;
      const form = state.mlffUploadForm;
      return Boolean(draft.fileRole && draft.fileName && form.materialName.trim() && form.description.trim());
    }

    function updateMlffUploadSubmitButton() {
      const submitButton = document.querySelector('#mlffUploadModal [data-mlff-upload-submit]');
      if (submitButton) submitButton.disabled = !canSubmitMlffUpload();
    }

    function renderMlffUploadModal() {
      ensureMlffRuntimeState();
      const modal = document.getElementById("mlffUploadModal");
      if (!modal) return;
      const title = modal.querySelector(".modal-header h3");
      const body = modal.querySelector(".modal-body");
      const footer = modal.querySelector(".modal-footer");
      if (!body || !footer) return;
      if (title) title.textContent = "数据上传";
      const draft = state.mlffUploadDraft;
      const form = state.mlffUploadForm;
      const fileSummary = draft.fileName
        ? renderUploadAssetList([{
            name: draft.fileName,
            format: draft.sourceFormat || "FILE",
            sizeText: draft.fileSizeText || "",
            previewUrl: draft.previewUrl || ""
          }], "未选择文件")
        : "";
      const extraForm = draft.fileName ? `
        <div class="mlff-upload-form">
          <div class="field">
            <label for="mlffUploadMaterialName">材料名称 <span style="color:#c2382b;">*</span></label>
            <input id="mlffUploadMaterialName" type="text" value="${form.materialName}" placeholder="请输入材料名称">
          </div>
          <div class="field">
            <label for="mlffUploadDataSource">数据来源</label>
            <select id="mlffUploadDataSource">
              ${["自有数据集", "公开数据集"].map((item) => `<option value="${item}" ${normalizeUploadDataSource(form.dataSource) === item ? "selected" : ""}>${item}</option>`).join("")}
            </select>
          </div>
          <div class="field">
            <label for="mlffUploadDescription">数据描述 <span style="color:#c2382b;">*</span></label>
            <textarea id="mlffUploadDescription" rows="5" placeholder="请输入数据描述、适用范围或补充说明">${form.description}</textarea>
          </div>
        </div>
      ` : "";

      body.innerHTML = `
        <div class="twod-upload-layout">
          <div class="twod-upload-card">
            <div class="twod-step-indicator">
              <span class="twod-step-item">01 选择文件类型</span>
              <span class="twod-step-item">02 上传文件</span>
              <span class="twod-step-item">03 补充信息并提交审核</span>
            </div>
            <div class="field">
              <label>上传文件类别</label>
              <div class="twod-upload-type-grid">
                ${MLFF_UPLOAD_FILE_TYPES.map((item) => `
                  <label class="twod-upload-type-item">
                    <input type="radio" name="mlffUploadFileRole" value="${item.key}" ${draft.fileRole === item.key ? "checked" : ""}>
                    <strong>${item.label}</strong>
                    <span>三类文件三选一，选中后上传对应文件。</span>
                  </label>
                `).join("")}
              </div>
            </div>
            <div class="mlff-upload-note">先选择一种文件类别，再上传对应文件。上传成功后，补充材料信息表单才会显示；其中“材料名称”和“数据描述”为必填项。</div>
            <div class="field" style="margin-top:16px;">
              <div class="upload-action-bar">
                <button class="btn-primary" type="button" data-mlff-upload-pick ${!draft.fileRole ? "disabled" : ""}>点击上传</button>
              </div>
              <input id="mlffUploadFileInput" type="file" hidden accept="${MLFF_UPLOAD_FILE_TYPES.find((item) => item.key === draft.fileRole)?.accept || "*"}">
              <div class="upload-asset-panel">${draft.fileName ? fileSummary : renderUploadAssetList([], "未选择文件")}</div>
            </div>
            ${extraForm}
          </div>
        </div>
      `;

      footer.innerHTML = `
        <button class="btn" type="button" data-close-modal="mlffUploadModal">取消</button>
        <button class="btn-primary" type="button" data-mlff-upload-submit ${canSubmitMlffUpload() ? "" : "disabled"}>提交审核</button>
      `;
    }

    function openMlffUploadModal() {
      resetMlffUploadState();
      renderMlffUploadModal();
      openModal("mlffUploadModal");
    }

    function inferMlffConvertFileType(fileName) {
      const ext = detectFileFormat(fileName).toLowerCase();
      if (["xyz", "pdb", "mol2", "sdf", "cif"].includes(ext)) return "结构文件";
      if (["xml", "json", "txt", "csv", "dat"].includes(ext)) return "力场参数";
      if (["npz", "npy", "h5", "pt"].includes(ext)) return "拓扑/模型文件";
      return "";
    }

    function getMlffConvertTargetFormats(fileType) {
      if (fileType === "结构文件") return ["XYZ", "PDB", "CIF"];
      if (fileType === "力场参数") return ["JSON", "XML", "TXT", "CSV"];
      if (fileType === "拓扑/模型文件") return ["NPZ", "NPY", "H5", "PT"];
      return [];
    }

    function populateMlffConvertTargetFormats(selectId, fileType, sourceFormat = "") {
      const select = document.getElementById(selectId);
      if (!select) return;
      const normalizedSource = String(sourceFormat || "").toUpperCase();
      const formats = getMlffConvertTargetFormats(fileType);
      const available = formats.filter((item) => item !== normalizedSource);
      const list = available.length ? available : formats;
      select.innerHTML = list.length
        ? list.map((item) => `<option value="${item}">${item}</option>`).join("")
        : '<option value="">请先选择文件</option>';
      select.disabled = !list.length;
    }

    function renderMlffConvertLocalDraft() {
      const draft = state.mlffConvertLocalDraft;
      const fileName = document.getElementById("mlffConvertLocalFileName");
      const detectedType = document.getElementById("mlffConvertLocalDetectedType");
      const sourceFormat = document.getElementById("mlffConvertLocalSourceFormat");
      const fileSize = document.getElementById("mlffConvertLocalFileSize");
      if (!fileName || !detectedType || !sourceFormat || !fileSize) return;
      fileName.textContent = draft?.fileName || "未选择文件";
      detectedType.textContent = draft?.fileType || "待识别";
      sourceFormat.textContent = draft?.sourceFormat || "-";
      fileSize.textContent = draft?.fileSizeText || "-";
      populateMlffConvertTargetFormats("mlffConvertLocalTargetFormat", draft?.fileType || "", draft?.sourceFormat || "");
    }

    function renderMlffConvertThirdPartyInfo() {
      const select = document.getElementById("mlffConvertSourceRecord");
      const info = document.getElementById("mlffConvertThirdPartyInfo");
      if (!select || !info) return;
      const record = findMlffRecord(select.value);
      if (!record) {
        info.innerHTML = buildTwodConvertSummary([
          { label: "文件类别", value: "-" },
          { label: "源格式", value: "-" },
          { label: "记录来源", value: "-" }
        ]);
        populateMlffConvertTargetFormats("mlffConvertTargetFormat", "", "");
        return;
      }
      info.innerHTML = buildTwodConvertSummary([
        { label: "文件类别", value: record.fileType || "-" },
        { label: "源格式", value: record.sourceFormat || "-" },
        { label: "记录来源", value: record.source || "系统记录" }
      ]);
      populateMlffConvertTargetFormats("mlffConvertTargetFormat", record.fileType || "", record.sourceFormat || "");
    }

    function refreshMlffConvertSourceOptions() {
      const select = document.getElementById("mlffConvertSourceRecord");
      if (!select) return;
      const currentValue = select.value;
      select.innerHTML = mlffUpdateRecords.length
        ? mlffUpdateRecords.map((record) => `<option value="${record.id}">${record.fileName} · ${record.fileType}</option>`).join("")
        : '<option value="">暂无可选文件</option>';
      if (currentValue && mlffUpdateRecords.some((record) => record.id === currentValue)) {
        select.value = currentValue;
      }
      renderMlffConvertThirdPartyInfo();
    }

    function setMlffConvertPath(path) {
      state.mlffConvertPath = path;
      const localStep = document.getElementById("mlffConvertStepLocal");
      const externalStep = document.getElementById("mlffConvertStepExternal");
      const returnStep = document.getElementById("mlffConvertStepReturn");
      const startBtn = document.getElementById("mlffStartConvertBtn");
      const finishBtn = document.getElementById("mlffFinishConvertBtn");
      if (localStep) localStep.hidden = false;
      if (externalStep) externalStep.hidden = true;
      if (returnStep) returnStep.hidden = true;
      if (startBtn) {
        startBtn.hidden = false;
        startBtn.textContent = "跳转至第三方工具";
      }
      if (finishBtn) finishBtn.hidden = true;
    }

    function resetMlffConvertModal() {
      state.mlffConvertDraft = null;
      state.mlffConvertLocalDraft = null;
      const localInput = document.getElementById("mlffConvertLocalFileInput");
      const returnInfo = document.getElementById("mlffConvertReturnInfo");
      const externalText = document.getElementById("mlffConvertExternalText");
      const externalMeta = document.getElementById("mlffConvertExternalMeta");
      if (localInput) localInput.value = "";
      if (returnInfo) returnInfo.innerHTML = "";
      if (externalText) externalText.textContent = "系统已将文件转换请求发送至第三方工具，完成后可将结果回传至当前系统。";
      if (externalMeta) {
        externalMeta.innerHTML = buildTwodConvertSummary([
          { label: "源文件", value: "-" },
          { label: "目标格式", value: "-" },
          { label: "执行状态", value: "待发起" }
        ]);
      }
      setMlffConvertPath("thirdParty");
    }

    function openMlffConvertModal() {
      resetMlffConvertModal();
      refreshMlffConvertSourceOptions();
      openModal("mlffConvertModal");
    }

    function getMlffNodeTextColor(color) {
      const normalized = String(color || "").toLowerCase();
      if (normalized === "#ffffff" || normalized === "#fff" || normalized === "white" || normalized === "#edf2fb") return "#1f2f45";
      return "#fff";
    }

    function buildMlffLegendEntries(material) {
      return Object.entries(material.atomColors || { C: "#2b2f36", H: "#edf2fb", O: "#F53F3F", N: "#2f80ed" }).map(([label, color]) => ({ label: `${label} 原子`, color }));
    }

    function cloneMlffScene(base, scale, offsetX, offsetY) {
      const nodeOffset = [];
      const nodes = base.nodes.map((node, index) => {
        nodeOffset[index] = index;
        return {
          label: node.label,
          x: node.x * scale + offsetX,
          y: node.y * scale + offsetY,
          color: node.color,
          text: node.text
        };
      });
      const bonds = base.bonds.map((bond) => ({
        from: bond.from,
        to: bond.to
      }));
      return { nodes, bonds };
    }

    function appendMlffScene(target, scene) {
      const offset = target.nodes.length;
      target.nodes.push(...scene.nodes);
      target.bonds.push(...scene.bonds.map((bond) => ({ from: bond.from + offset, to: bond.to + offset })));
    }

    function buildMlffScene(material, tabKey) {
      const base = buildMlffStructureData(material);
      const scene = { nodes: [], bonds: [], legend: buildMlffLegendEntries(material), size: "medium", caption: "" };
      if (tabKey === "smallSystem") {
        [
          { scale: 0.42, x: 8, y: 12 },
          { scale: 0.42, x: 42, y: 18 },
          { scale: 0.42, x: 24, y: 48 }
        ].forEach((item) => appendMlffScene(scene, cloneMlffScene(base, item.scale, item.x, item.y)));
        scene.size = "small";
        scene.caption = `${material.name} 的小体系结构用于展示局部团簇、相邻分子排布和短程相互作用。`;
        return scene;
      }
      if (tabKey === "largeSystem") {
        [
          { scale: 0.24, x: 4, y: 6 },
          { scale: 0.24, x: 34, y: 6 },
          { scale: 0.24, x: 64, y: 6 },
          { scale: 0.24, x: 4, y: 50 },
          { scale: 0.24, x: 34, y: 50 },
          { scale: 0.24, x: 64, y: 50 }
        ].forEach((item) => appendMlffScene(scene, cloneMlffScene(base, item.scale, item.x, item.y)));
        scene.size = "tiny";
        scene.caption = `${material.name} 的大体系结构用于查看周期复制、拓扑扩展和多分子体系构型。`;
        return scene;
      }
      appendMlffScene(scene, cloneMlffScene(base, 0.74, 12, 14));
      scene.size = "medium";
      scene.caption = `${material.name} 的分子结构预览用于查看基础构型、键连关系和原子组成。`;
      return scene;
    }

    function renderMlffSceneMarkup(scene) {
      return `
        ${scene.bonds.map((bond) => {
          const from = scene.nodes[bond.from];
          const to = scene.nodes[bond.to];
          const dx = to.x - from.x;
          const dy = to.y - from.y;
          const length = Math.sqrt(dx * dx + dy * dy);
          const angle = Math.atan2(dy, dx) * (180 / Math.PI);
          return `<span class="material-bond" style="left:${from.x}%; top:${from.y}%; width:${length}%; transform:rotate(${angle}deg);"></span>`;
        }).join("")}
        ${scene.nodes.map((node) => {
          const border = String(node.color).toLowerCase() === "#ffffff" || String(node.color).toLowerCase() === "#fff" || String(node.color).toLowerCase() === "#edf2fb"
            ? "border:1px solid #c7d5eb;"
            : "";
          return `<span class="material-node" style="left:${node.x}%; top:${node.y}%; background:${node.color}; color:${node.text || getMlffNodeTextColor(node.color)}; ${border}">${node.label}</span>`;
        }).join("")}
      `;
    }

/* ==========================================================================
   机器学习力场（MLFF）主题应用 —— 材料详情：三类结构「或」关系
   目标页面：page-mlff（低维材料主题应用 / 机器学习力场应用）
   详情载体：materialModal（由 openRichMaterialModal → canonical* 系列渲染）

   需求：分子结构 / 小体系结构 / 大体系结构 是「或」关系而非并存 ——
   任一材料只归属其中一类，详情只展示「基础信息 + 该材料所属的那一类结构」。
   数据来源：机器学习力场样例数据.xlsx（分子结构 / 小体系结构 / 大体系结构 三个 sheet）
   ========================================================================== */

/* 材料 → 结构类型的判定规则。按体系规模归纳到三类结构，保证三者互斥。
   规则按顺序匹配，命中即停；最后一条兜底必然命中。 */
const MLFF_TOPIC_STRUCTURE_RULES = [
  /* 大体系结构：多孔框架 / 层状材料 / 聚合物 / 核酸 —— 扩展或准周期性体系 */
  { structure: "large", test: (m) => /MOF|ZIF|沸石|石墨烯|聚合物|DNA|PEG|Polystyrene|Zeolite|Graphene/i.test(`${m.english || ""} ${m.name || ""} ${m.formula || ""} ${m.structureType || ""}`) },
  /* 小体系结构：离子晶体 / 离子液体 / 多肽 —— 多分子或离子聚集体系 */
  { structure: "small", test: (m) => /离子晶体|离子液体|Sodium|Lithium|EMIM|Dipeptide|Alanine/i.test(`${m.english || ""} ${m.name || ""} ${m.formula || ""} ${m.structureType || ""}`) },
  /* 分子结构：单分子体系（含真实案例：单分子构型 + 平衡原子电荷） */
  { structure: "molecule", test: () => true }
];

/* 主题页结构键（molecule/small/large）→ materialModal 标签页键（molecule/smallSystem/largeSystem） */
const MLFF_TOPIC_TAB_KEY = { molecule: "molecule", small: "smallSystem", large: "largeSystem" };

/* 材料所属结构类型（恒返回三者之一，绝不为 null） */
function resolveMlffTopicStructure(material) {
  if (!material) return "molecule";
  const rule = MLFF_TOPIC_STRUCTURE_RULES.find((item) => item.test(material));
  return rule ? rule.structure : "molecule";
}

/* 该材料所属结构类型对应的 materialModal 标签页键 */
function getMlffTopicTabKey(material) {
  return MLFF_TOPIC_TAB_KEY[resolveMlffTopicStructure(material)] || "molecule";
}

/* 该材料归属该结构类型的判定依据 */
function getMlffTopicStructureReason(structure) {
  if (structure === "small") return "该材料为离子 / 多分子聚集的小体系，力场参数以局域片段与短程相互作用为采集对象。";
  if (structure === "large") return "该材料为周期性或多孔扩展体系，力场参数以跨尺度结构样本与长程相互作用为采集对象。";
  return "该材料为单分子体系，力场参数以单个分子的构型与分子级性质为采集对象。";
}

/* 取该材料的结构样例数据（按材料 id 稳定分片，避免每次打开换数据） */
function getMlffTopicStructureData(material) {
  if (!material) return null;
  const structure = resolveMlffTopicStructure(material);
  const meta = MLFF_STRUCTURE_META[structure];
  const all = MLFF_STRUCTURE_SAMPLES[structure] || [];
  if (!all.length) return null;

  const seed = String(material.id || material.formula || "").split("")
    .reduce((acc, ch) => acc + ch.charCodeAt(0), 0);
  const count = Math.min(6, all.length);
  const offset = all.length > count ? seed % (all.length - count + 1) : 0;
  const records = all.slice(offset, offset + count);

  return {
    structure: structure,
    meta: meta,
    fields: MLFF_STRUCTURE_FIELDS[structure] || [],
    records: records,
    total: all.length,
    offset: offset,
    source: MLFF_STRUCTURE_SOURCE[structure] || "",
    reason: getMlffTopicStructureReason(structure)
  };
}

/* 数值文本格式化：null / "" / 非数字 → "—" */
function mlffTopicNumText(value, digits, unit) {
  if (value === null || value === undefined || value === "") return "—";
  const n = Number(value);
  if (!Number.isFinite(n)) return String(value);
  return `${n.toFixed(digits)}${unit || ""}`;
}

/* ── 「基础信息」面板字段（扩充版）─────────────────────────────────────────
   返回 { infoFields, dataFields }，由 canonicalRenderMaterialInfo 的 mlff 分支消费。 */
function renderMlffTopicBasicFields(material, data) {
  const infoFields = [
    { label: "化学名称", value: material.name || "—" },
    { label: "英文名称", value: material.english || "—" },
    { label: "分子式", value: material.formula || "—" },
    { label: "PUBCHEM", value: material.pubchem || "—" },
    { label: "能量", value: material.energy != null ? mlffTopicNumText(material.energy, 1, ` ${material.energyUnit || "kcal/mol"}`) : "—" },
    { label: "偶极矩", value: material.dipole != null ? mlffTopicNumText(material.dipole, 2, " D") : "—" },
    { label: "原子数", value: material.atomCount != null ? String(material.atomCount) : "—" },
    { label: "净电荷 (e)", value: material.netCharge != null ? String(material.netCharge) : "—" },
    { label: "结构类型", value: (data ? data.meta.label : "—") },
    { label: "采样帧数", value: material.retainedFrames != null ? String(material.retainedFrames) : "—" },
    { label: "原子电荷数", value: material.chargeCount != null ? String(material.chargeCount) : "—" },
    { label: "数据划分", value: material.split || "—" }
  ];
  const dataFields = [
    { label: "力场类型", value: material.forceField || material.traditionalForceField || "机器学习力场（MLFF）" },
    { label: "计算方法", value: material.method || "—" },
    { label: "核心参数项", value: material.parameterName || "—" },
    { label: "参数值", value: material.parameterValue || "—" },
    { label: "数据来源", value: material.source || "—" },
    { label: "更新时间", value: material.updatedAt || "—" },
    { label: "质检状态", value: material.quality || material.qcStatus || "—" },
    { label: "授权许可", value: material.sourceLicense || material.license || "—" }
  ];
  return { infoFields: infoFields, dataFields: dataFields };
}

/* ── 结构类型提示条（插在「基础信息」面板最上方，体现 or 关系）────────────── */
function renderMlffTopicStructNotice(material) {
  const esc = escapeLowDimHtml;
  const data = getMlffTopicStructureData(material);
  const structure = data ? data.structure : "molecule";
  const meta = data ? data.meta : MLFF_STRUCTURE_META.molecule;
  return `
    <div class="mlfftd-struct-notice" data-structure="${esc(structure)}">
      <div class="mlfftd-struct-notice-head">
        <span class="mlfftd-struct-chip" data-structure="${esc(structure)}">${esc(meta.label)} · ${esc(meta.enLabel)}</span>
        <strong>本材料归属结构类型：${esc(meta.label)}</strong>
      </div>
      <p>分子结构、小体系结构与大体系结构三者互斥（或关系），同一材料只归入其中一类。${esc(data ? data.reason : "")}下方「材料性质」页仅提供该类的结构与参数数据，不展示另外两类。</p>
    </div>`;
}

/* ── 结构样例记录表（含统计卡 + 图表），追加在「材料性质」标签页下方 ───────── */
function renderMlffTopicSampleTable(data) {
  const esc = escapeLowDimHtml;
  if (!data) return `<div class="ldidp-empty">该材料暂无结构样例数据。</div>`;
  const meta = data.meta;
  const records = data.records || [];
  const fields = data.fields || [];
  const tone = data.structure;

  const numericFields = fields.filter((f) => records.some((r) => mlffToNumber(r[f]) !== null));
  const STAT_SPEC = {
    molecule: [
      { label: "样例记录", field: null, unit: "条" },
      { label: "原子数范围", field: "原子数", unit: "个" },
      { label: "单分子能量范围", field: "单分子能量(eV)", unit: "eV" },
      { label: "偶极矩范围", field: "偶极矩(Debye)", unit: "Debye" }
    ],
    small: [
      { label: "样例记录", field: null, unit: "条" },
      { label: "原子数范围", field: "原子数", unit: "个" },
      { label: "能量范围", field: "能量(eV/atom)", unit: "eV/atom" },
      { label: "带隙范围", field: "带隙(eV)", unit: "eV" }
    ],
    large: [
      { label: "样例记录", field: null, unit: "条" },
      { label: "原子数范围", field: "原子数", unit: "个" },
      { label: "能量范围", field: "能量(eV/atom)", unit: "eV/atom" },
      { label: "带隙范围", field: "带隙(eV)", unit: "eV" }
    ]
  };
  const statSpec = (STAT_SPEC[data.structure] || STAT_SPEC.small)
    .filter((spec) => spec.field === null || numericFields.indexOf(spec.field) >= 0);
  const statValue = (spec) => {
    if (!spec.field) return esc(String(records.length));
    const vs = records.map((r) => mlffToNumber(r[spec.field])).filter((v) => v !== null);
    if (!vs.length) return "-";
    const lo = Math.min.apply(null, vs);
    const hi = Math.max.apply(null, vs);
    return lo === hi ? String(lo) : `${lo} ~ ${hi}`;
  };
  const stats = statSpec.map((spec) => `
    <article class="mlff-stat-card${spec.field ? "" : " is-primary"}">
      <span>${esc(spec.label)}</span>
      <strong>${esc(statValue(spec))}<em>${esc(spec.unit)}</em></strong>
    </article>`).join("");

  const chartMetrics = (MLFF_STRUCTURE_CHART_METRICS[data.structure] || [])
    .filter((m) => numericFields.indexOf(m.key) >= 0)
    .slice(0, 3);
  const chartBlocks = chartMetrics.map((m, i) => `
    <section class="mlff-chart-card">
      <header class="mlff-chart-head">
        <h4>${esc(m.label)}分布</h4>
        <span class="mlff-chart-unit">${esc(m.unit)}</span>
      </header>
      ${i === 0 ? renderMlffSparkChart(records, m, tone) : renderMlffDistributionChart(records, m, tone)}
    </section>`).join("");

  const shortField = (f) => String(f).replace("material_id", "材料ID").replace("formula", "分子式");
  const numericCols = ["原子数", "分子数", "电荷", "自旋多重度", "单分子能量(eV)", "偶极矩(Debye)", "极化率(Å³)", "色散系数", "能量(eV/atom)", "力(eV/Å)", "应力(kBar)", "磁矩(μB)", "带隙(eV)"];
  const rowsHtml = records.map((r) => `
    <tr>
      ${fields.map((f) => {
        const raw = r[f] == null ? "" : String(r[f]);
        const isNum = numericCols.indexOf(f) >= 0;
        const isMark = raw === "✓";
        const cls = isNum ? "mlff-cell-num" : (isMark ? "mlff-cell-mark" : "");
        const content = isMark ? `<span class="mlff-check" title="已记录">✓</span>` : esc(raw);
        return `<td class="${cls}" title="${esc(raw)}">${content}</td>`;
      }).join("")}
    </tr>`).join("");

  return `
    <section class="mlff-struct-banner">
      <div class="mlff-struct-banner-main">
        <span class="mlff-struct-tag">${esc(meta.enLabel)}</span>
        <h4>本材料所属结构类型：${esc(meta.label)}</h4>
        <p>分子结构、小体系结构与大体系结构三者互斥（或关系），同一材料只归入其中一类，因此本页不展示另外两类结构的样例数据。${esc(data.reason)}</p>
      </div>
      <dl class="mlff-struct-facts">
        <div><dt>数据来源</dt><dd>${esc(data.source || "-")}</dd></div>
        <div><dt>字段数量</dt><dd>${fields.length} 列</dd></div>
        <div><dt>本材料样例</dt><dd>第 ${data.offset + 1} - ${data.offset + records.length} 条 / 共 ${data.total} 条</dd></div>
      </dl>
    </section>

    <div class="mlff-stat-grid">${stats}</div>

    ${chartBlocks ? `<div class="mlff-chart-grid">${chartBlocks}</div>` : ""}

    <div class="mlff-topic-panel-head">
      <h4>${esc(meta.label)}样例记录</h4>
      <span class="mlff-topic-panel-tag">共 ${records.length} 条</span>
    </div>
    <div class="mlff-table-wrap">
      <table class="mlff-table">
        <thead>
          <tr>${fields.map((f) => `<th>${esc(shortField(f))}</th>`).join("")}</tr>
        </thead>
        <tbody>
          ${rowsHtml || `<tr><td colspan="${fields.length}" class="ldidp-table-empty">暂无样例数据</td></tr>`}
        </tbody>
      </table>
    </div>
  `;
}

    function buildMlffMaterialProfile(material) {
      return {
        viewTitle: "分子结构预览",
        infoTitle: "基础信息",
        dataTitle: "数据来源",
        metricsTitle: "结构页面",
        chartTitle: "结构补充",
        structureView: buildMlffScene(material, getMlffTopicTabKey(material)),
        /* 三类结构为「或」关系：detailTabs 只保留该材料实际所属的那一类，
           不再并列 molecule / smallSystem / largeSystem 三个标签页。 */
        detailTabs: (function () {
          const owned = getMlffTopicTabKey(material);
          const tabs = {};
          tabs[owned] = [];
          return tabs;
        })(),
        visualTabs: [],
        visuals: {}
      };
    }

    function buildMlffDetailFacts(material, tabKey) {
      /* 三类结构为「或」关系：传入的 tabKey 若不是该材料实际所属结构，回落到实际所属结构 */
      const ownedTab = getMlffTopicTabKey(material);
      if (tabKey !== ownedTab) tabKey = ownedTab;
      if (tabKey === "smallSystem") {
        return [
          { label: "结构页面", value: "小体系结构" },
          { label: "展示内容", value: "局部团簇、短程相互作用、邻近构型" },
          { label: "推荐下载", value: "PDB结构文件 / XML力场文件" },
          { label: "适用场景", value: "局部构型校验、参数耦合分析" }
        ];
      }
      if (tabKey === "largeSystem") {
        return [
          { label: "结构页面", value: "大体系结构" },
          { label: "展示内容", value: "扩展体系、周期复制、拓扑排布" },
          { label: "推荐下载", value: "PDB结构文件 / XML力场文件 / 参数力场文件" },
          { label: "适用场景", value: "大规模分子动力学体系构建" }
        ];
      }
      return [
        { label: "结构页面", value: "分子结构" },
        { label: "化学名称", value: `${material.name} / ${material.english}` },
        { label: "力场与方法", value: `${material.forceField} / ${material.method}` },
        { label: "推荐下载", value: "参数力场文件 / PDB结构文件" }
      ];
    }

    function buildMlffFileProfile(material, key) {
      const prefix = String(material.english || material.name).toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
      if (key === "pdb") {
        return {
          title: "PDB结构文件",
          caption: `${material.name} 的 PDB 文件可用于结构查看、拓扑核对和建模软件导入。`,
          fileName: `${prefix || "material"}.pdb`,
          format: "PDB",
          content: "原子坐标、键信息、体系命名",
          target: "结构展示 / 小体系与大体系建模",
          items: ["支持导出当前结构页面对应的 PDB 文件。", "可用于第三方建模与可视化工具。", "适配结构预览与坐标核验流程。"]
        };
      }
      if (key === "xml") {
        return {
          title: "XML力场文件",
          caption: `${material.name} 的 XML 文件用于保存参数映射、相互作用规则与结构关联信息。`,
          fileName: `${prefix || "material"}_${String(material.forceField || "field").toLowerCase().replace(/[^a-z0-9]+/g, "-")}.xml`,
          format: "XML",
          content: "参数映射、拓扑规则、节点关联",
          target: "OpenMM / XML兼容工作流",
          items: ["支持导出筛选后的当前文件类型。", "适配 XML 力场解析和转换链路。", "可与第三方格式转换结果联动。"]
        };
      }
      return {
        title: "参数力场文件",
        caption: `${material.name} 的参数力场文件包含核心参数项、方法来源和推荐建模参数。`,
        fileName: `${prefix || "material"}_${String(material.forceField || "field").toLowerCase().replace(/[^a-z0-9]+/g, "-")}.prm`,
        format: "PRM",
        content: `${material.parameterName} / ${material.parameterValue}`,
        target: "参数建模 / 力场复用",
        items: ["支持按当前材料下载参数力场文件。", "可与 PDB、XML 文件配套下载。", "参数来源与数据来源信息同步保留。"]
      };
    }

    const mlffAwareFindMaterialBySource = findMaterialBySource;
    function findMaterialBySource(source, materialId) {
      if (source === "mlff") return findMlffMaterial(materialId) || mlffMaterials[0];
      return mlffAwareFindMaterialBySource(source, materialId);
    }

    const mlffAwareGetMaterialProfile = getMaterialProfile;
    function getMaterialProfile(material) {
      if (state.selectedMaterialSource === "mlff") {
        return buildMlffMaterialProfile(material);
      }
      return mlffAwareGetMaterialProfile(material);
    }

    const mlffAwareRenderMaterialInfo = renderMaterialInfo;
    function renderMaterialInfo(material) {
      if (state.selectedMaterialSource !== "mlff") {
        mlffAwareRenderMaterialInfo(material);
        return;
      }
      const infoWrap = document.getElementById("materialInfoGrid");
      const dataWrap = document.getElementById("materialDataGrid");
      document.getElementById("materialInfoPanelTitle").textContent = "基础信息";
      document.getElementById("materialDataPanelTitle").textContent = "数据来源";
      document.getElementById("materialMetricsTitle").textContent = "结构页面";
      document.getElementById("materialChartTitle").textContent = "文件下载";
      infoWrap.innerHTML = [
        { label: "化学名称", value: material.name },
        { label: "英文名称", value: material.english },
        { label: "分子式", value: material.formula },
        { label: "PUBCHEM", value: material.pubchem },
        { label: "能量", value: `${material.energy} kcal/mol` },
        { label: "偶极矩", value: `${material.dipole} D` }
      ].map((item) => `<div class="material-info-item"><span>${item.label}</span><strong>${item.value}</strong></div>`).join("");
      dataWrap.innerHTML = [
        { label: "力场类型", value: material.forceField },
        { label: "计算方法", value: material.method },
        { label: "核心参数项", value: material.parameterName },
        { label: "参数值", value: material.parameterValue },
        { label: "数据来源", value: material.source },
        { label: "更新时间", value: material.updatedAt }
      ].map((item) => `<div class="material-info-item"><span>${item.label}</span><strong>${item.value}</strong></div>`).join("");
    }

    const mlffAwareRenderMaterialStructure = renderMaterialStructure;
    function renderMaterialStructure(material) {
      if (state.selectedMaterialSource !== "mlff") {
        const canvas = document.getElementById("materialStructureCanvas");
        if (canvas) {
          canvas.className = "material-atom-cluster";
          delete canvas.dataset.mlffSceneSize;
        }
        mlffAwareRenderMaterialStructure(material);
        return;
      }
      const scene = buildMlffScene(material, "molecule");
      document.getElementById("materialViewTitle").textContent = "分子结构预览";
      document.getElementById("materialStructureCaption").textContent = scene.caption;
      document.getElementById("materialStructureCanvas").className = "material-atom-cluster mlff-scene";
      document.getElementById("materialStructureCanvas").dataset.mlffSceneSize = scene.size;
      document.getElementById("materialStructureCanvas").innerHTML = renderMlffSceneMarkup(scene);
      document.getElementById("materialLegend").innerHTML = scene.legend.map((item) => {
        const border = String(item.color).toLowerCase() === "#ffffff" || String(item.color).toLowerCase() === "#fff" || String(item.color).toLowerCase() === "#edf2fb"
          ? "border:1px solid #c7d5eb;"
          : "";
        return `<span><i class="legend-dot" style="background:${item.color}; ${border}"></i>${item.label}</span>`;
      }).join("");
    }

    const mlffAwareRenderMaterialMetrics = renderMaterialMetrics;
    function renderMaterialMetrics(material) {
      if (state.selectedMaterialSource !== "mlff") {
        mlffAwareRenderMaterialMetrics(material);
        return;
      }
      const activeTab = state.selectedMaterialTab || "molecule";
      const scene = buildMlffScene(material, activeTab);
      const facts = buildMlffDetailFacts(material, activeTab);
      const wrap = document.getElementById("materialMetricGrid");
      wrap.innerHTML = `
        <div class="mlff-detail-layout">
          <article class="mlff-detail-stage-card">
            <h4>${MATERIAL_TAB_LABELS[activeTab] || "结构页面"}</h4>
            <p>${scene.caption}</p>
            <div class="material-atom-cluster mlff-scene" data-mlff-scene-size="${scene.size}">${renderMlffSceneMarkup(scene)}</div>
            <div class="material-legend">${scene.legend.map((item) => {
              const border = String(item.color).toLowerCase() === "#ffffff" || String(item.color).toLowerCase() === "#fff" || String(item.color).toLowerCase() === "#edf2fb"
                ? "border:1px solid #c7d5eb;"
                : "";
              return `<span><i class="legend-dot" style="background:${item.color}; ${border}"></i>${item.label}</span>`;
            }).join("")}</div>
          </article>
          <div class="mlff-detail-facts">
            ${facts.map((item) => `
              <article class="mlff-fact-card">
                <span>${item.label}</span>
                <strong>${item.value}</strong>
              </article>
            `).join("")}
          </div>
        </div>
      `;
    }

    const mlffAwareRenderMaterialVisuals = renderMaterialVisuals;
    function renderMaterialVisuals(material) {
      if (state.selectedMaterialSource !== "mlff") {
        mlffAwareRenderMaterialVisuals(material);
        return;
      }
      const profile = getMaterialProfile(material);
      const firstVisual = profile.visualTabs[0]?.key || "forceField";
      const activeVisual = profile.visualTabs.some((item) => item.key === state.selectedMaterialVisual) ? state.selectedMaterialVisual : firstVisual;
      state.selectedMaterialVisual = activeVisual;
      const current = buildMlffFileProfile(material, activeVisual);
      document.getElementById("materialVisualChips").innerHTML = profile.visualTabs.map((item) => `
        <button class="material-visual-chip${item.key === activeVisual ? " active" : ""}" type="button" data-material-visual="${item.key}">${item.label}</button>
      `).join("");
      document.getElementById("materialLineChart").innerHTML = `
        <article class="mlff-file-panel">
          <h4>${current.title}</h4>
          <p>${current.caption}</p>
          <div class="mlff-file-meta">
            <article class="mlff-fact-card">
              <span>文件名称</span>
              <strong>${current.fileName}</strong>
            </article>
            <article class="mlff-fact-card">
              <span>文件格式</span>
              <strong>${current.format}</strong>
            </article>
            <article class="mlff-fact-card">
              <span>数据内容</span>
              <strong>${current.content}</strong>
            </article>
            <article class="mlff-fact-card">
              <span>适用场景</span>
              <strong>${current.target}</strong>
            </article>
          </div>
          <ul class="mlff-file-list">
            ${current.items.map((item) => `<li>${item}</li>`).join("")}
          </ul>
        </article>
      `;
      document.getElementById("materialChartCaption").textContent = `${current.title}支持按“全部”或“当前文件类型”下载。`;
    }

    const mlffAwareSyncMaterialModalChrome = syncMaterialModalChrome;
    function syncMaterialModalChrome(material) {
      if (state.selectedMaterialSource !== "mlff") {
        mlffAwareSyncMaterialModalChrome(material);
        return;
      }
      document.querySelectorAll("#materialSectionNav .twod-detail-nav-btn").forEach((button) => {
        const labels = {
          basic: "基础信息",
          properties: "结构页面",
          visualization: "文件下载"
        };
        button.textContent = labels[button.dataset.materialSection] || button.textContent;
      });
      const jumpWrap = document.querySelector("#materialModal .twod-detail-jump");
      if (jumpWrap) {
        jumpWrap.innerHTML = `
          <button class="btn" type="button" data-material-section="properties" data-material-tab="molecule">分子结构</button>
          <button class="btn" type="button" data-material-section="properties" data-material-tab="smallSystem">小体系结构</button>
          <button class="btn" type="button" data-material-section="properties" data-material-tab="largeSystem">大体系结构</button>
          <button class="btn" type="button" data-material-section="visualization" data-material-visual="forceField">文件下载</button>
        `;
      }
      const basicScope = document.getElementById("materialBasicDownloadScope");
      const propertyScope = document.getElementById("materialPropertyDownloadScope");
      const visualScope = document.getElementById("materialVisualDownloadScope");
      if (basicScope) {
        basicScope.options[0].textContent = "下载基础信息与结构概览";
        basicScope.options[1].textContent = "下载当前基础页";
      }
      if (propertyScope) {
        propertyScope.options[0].textContent = "下载全部结构页面";
        propertyScope.options[1].textContent = "下载当前结构页面";
      }
      if (visualScope) {
        visualScope.options[0].textContent = "下载全部文件包";
        visualScope.options[1].textContent = "下载当前文件类型";
      }
    }

    function openMlffMaterialModal(materialId) {
      const material = findMlffMaterial(materialId);
      if (!material) return;
      state.selectedMaterialSource = "mlff";
      state.selectedMaterialId = material.id;
      state.selectedMlffId = material.id;
      state.selectedMaterialSection = "basic";
      state.selectedMaterialTab = "molecule";
      state.selectedMaterialVisual = "forceField";
      document.getElementById("materialModalTitle").textContent = material.name;
      document.getElementById("materialModalSubtitle").textContent = `ID: ${material.id}`;
      renderMaterialInfo(material);
      renderMaterialStructure(material);
      renderMaterialDetailTabs(material);
      renderMaterialMetrics(material);
      renderMaterialVisuals(material);
      renderMaterialDetailSection(material);
      syncMaterialModalChrome(material);
      openModal("materialModal");
    }

    const mlffAwareRenderMaterialModal = renderMaterialModal;
    function renderMaterialModal(materialToken) {
      const parsed = parseMaterialToken(materialToken);
      if (parsed.source === "mlff") {
        openMlffMaterialModal(parsed.id);
        return;
      }
      mlffAwareRenderMaterialModal(materialToken);
    }

    function bindMlffModalDownloadOverrides() {
      if (document.body.dataset.mlffModalDownloadBound === "true") return;
      document.body.dataset.mlffModalDownloadBound = "true";

      document.getElementById("materialBasicDownloadBtn")?.addEventListener("click", (event) => {
        if (state.selectedMaterialSource !== "mlff") return;
        event.stopImmediatePropagation();
        const material = getCurrentMaterial();
        const scope = document.getElementById("materialBasicDownloadScope")?.value === "all" ? "基础信息与结构概览" : "当前基础页";
        if (material) showToast("下载数据", `${material.name} 的${scope}已准备。`);
      }, true);

      document.getElementById("materialPropertyDownloadBtn")?.addEventListener("click", (event) => {
        if (state.selectedMaterialSource !== "mlff") return;
        event.stopImmediatePropagation();
        const material = getCurrentMaterial();
        const scope = document.getElementById("materialPropertyDownloadScope")?.value === "all"
          ? "全部结构页面"
          : `${MATERIAL_TAB_LABELS[state.selectedMaterialTab] || "当前结构页面"}`;
        if (material) showToast("下载数据", `${material.name} 的${scope}已准备。`);
      }, true);

      document.getElementById("materialVisualDownloadBtn")?.addEventListener("click", (event) => {
        if (state.selectedMaterialSource !== "mlff") return;
        event.stopImmediatePropagation();
        const material = getCurrentMaterial();
        const currentLabel = buildMlffFileProfile(material, state.selectedMaterialVisual || "forceField").title;
        const scope = document.getElementById("materialVisualDownloadScope")?.value === "all" ? "全部文件包" : currentLabel;
        if (material) showToast("下载文件", `${material.name} 的${scope}已准备。`);
      }, true);
    }

    function bindMlffInteractions() {
      ensureMlffRuntimeState();
      bindMlffModalDownloadOverrides();
      const page = document.getElementById("page-mlff");
      if (page && page.dataset.mlffBound !== "true") {
        page.dataset.mlffBound = "true";

        page.addEventListener("input", (event) => {
          const modeInput = event.target.getAttribute("data-mlff-mode-input");
          if (modeInput) {
            state.mlffSearchDraft[modeInput] = event.target.value;
            return;
          }
          if (event.target.id === "mlffPropertyKeyword") {
            state.mlffSearchDraft.propertyKeyword = event.target.value;
            const applyAction = page.querySelector("[data-mlff-apply]");
            if (applyAction) applyAction.disabled = !state.mlffSearchDraft.propertyKeyword.trim();
          }
        });

        page.addEventListener("change", (event) => {
          if (event.target.id === "mlffPageSizeFinal") {
            state.mlffPageSize = Number(event.target.value);
            state.mlffPage = 1;
            renderMlffModule();
            return;
          }
          if (event.target.id === "mlffPropertyField") {
            state.mlffSearchDraft.propertyField = event.target.value;
            const propertyInput = document.getElementById("mlffPropertyKeyword");
            if (propertyInput) {
              propertyInput.placeholder = MLFF_PROPERTY_PLACEHOLDERS[event.target.value] || "请输入对应内容";
            }
          }
        });

        page.addEventListener("keydown", (event) => {
          if (event.key !== "Enter") return;
          if (!event.target.matches("[data-mlff-mode-input], #mlffPropertyKeyword")) return;
          event.preventDefault();
          if (event.target.id === "mlffPropertyKeyword") {
            state.mlffSearchDraft.propertyKeyword = event.target.value;
          }
          applyMlffSearch();
          renderMlffModule();
        });

        page.addEventListener("click", (event) => {
          const modeButton = event.target.closest("[data-mlff-mode]");
          const applyButton = event.target.closest("[data-mlff-apply]");
          const resetButton = event.target.closest("[data-mlff-reset]");
          const pageButton = event.target.closest("[data-mlff-page]");
          const glossaryButton = event.target.closest("[data-mlff-glossary-jump]");
          const glossaryTabButton = event.target.closest("[data-mlff-glossary-tab]");
          const uploadButton = event.target.closest("[data-mlff-open-upload]");
          const convertButton = event.target.closest("[data-mlff-open-convert]");

          if (modeButton) {
            state.mlffSearchMode = modeButton.dataset.mlffMode;
            state.mlffAppliedSearch = { mode: "", filters: null };
            state.mlffPage = 1;
            renderMlffModule();
            return;
          }

          if (applyButton) {
            if (document.getElementById("mlffPropertyKeyword")) {
              state.mlffSearchDraft.propertyKeyword = document.getElementById("mlffPropertyKeyword").value;
            }
            applyMlffSearch();
            renderMlffModule();
            return;
          }

          if (resetButton) {
            clearCurrentMlffModeDraft();
            renderMlffModule();
            return;
          }

          if (pageButton) {
            state.mlffPage = Number(pageButton.dataset.mlffPage);
            renderMlffModule();
            return;
          }

          if (glossaryTabButton) {
            state.mlffGlossaryTab = glossaryTabButton.dataset.mlffGlossaryTab;
            renderMlffModule();
            return;
          }

          if (glossaryButton) {
            openMlffGlossaryModal();
            return;
          }

          if (uploadButton) {
            openMlffUploadModal();
            return;
          }

          if (convertButton) {
            openMlffConvertModal();
          }
        });
      }

      if (document.body.dataset.mlffWorkflowBound === "true") return;
      document.body.dataset.mlffWorkflowBound = "true";

      document.body.addEventListener("input", (event) => {
        if (event.target.id === "mlffTermKeyword" && event.target.closest("#mlffGlossaryModal")) {
          state.mlffTermKeyword = event.target.value;
          renderMlffGlossaryModalContent();
          return;
        }
        if (event.target.id === "mlffUploadMaterialName") {
          state.mlffUploadForm.materialName = event.target.value;
          updateMlffUploadSubmitButton();
          return;
        }
        if (event.target.id === "mlffUploadDescription") {
          state.mlffUploadForm.description = event.target.value;
          updateMlffUploadSubmitButton();
          return;
        }
      });

      document.body.addEventListener("change", (event) => {
        if (event.target.id === "mlffMethodFilter" && event.target.closest("#mlffGlossaryModal")) {
          state.mlffMethodFilter = event.target.value;
          renderMlffGlossaryModalContent();
          return;
        }
        if (event.target.name === "mlffUploadFileRole") {
          revokeUploadPreviewUrl(state.mlffUploadDraft.previewUrl);
          state.mlffUploadDraft.fileRole = event.target.value;
          state.mlffUploadDraft.fileName = "";
          state.mlffUploadDraft.sourceFormat = "";
          state.mlffUploadDraft.sizeBytes = 0;
          state.mlffUploadDraft.fileSizeText = "";
          state.mlffUploadDraft.previewUrl = "";
          renderMlffUploadModal();
          return;
        }
        if (event.target.id === "mlffUploadDataSource") {
          state.mlffUploadForm.dataSource = event.target.value;
          return;
        }
        if (event.target.id === "mlffUploadFileInput") {
          const file = event.target.files?.[0];
          if (!file) return;
          state.mlffUploadDraft.fileName = file.name;
          state.mlffUploadDraft.sourceFormat = inferMlffFileFormat(file.name);
          state.mlffUploadDraft.sizeBytes = file.size || 0;
          state.mlffUploadDraft.fileSizeText = formatMlffFileSize(file.size || 0);
          setUploadPreviewForDraft(state.mlffUploadDraft, file, state.mlffUploadDraft.sourceFormat);
          renderMlffUploadModal();
          return;
        }
        if (event.target.id === "mlffConvertSourceRecord") {
          renderMlffConvertThirdPartyInfo();
        }
      });

      document.body.addEventListener("click", (event) => {
        const glossaryTabButton = event.target.closest("#mlffGlossaryModal [data-mlff-glossary-tab]");
        if (glossaryTabButton) {
          state.mlffGlossaryTab = glossaryTabButton.dataset.mlffGlossaryTab;
          renderMlffGlossaryModalContent();
          return;
        }

        if (event.target.closest("#mlffGlossaryModal [data-mlff-export-glossary]")) {
          showToast("导出成功", `已导出${state.mlffGlossaryTab === "definition" ? "参数定义表" : "数据获取方法表"}。`);
          return;
        }

        if (event.target.closest("[data-mlff-upload-pick]")) {
          if (!state.mlffUploadDraft.fileRole) {
            showToast("数据上传", "请先选择上传文件类别。");
            return;
          }
          document.getElementById("mlffUploadFileInput")?.click();
          return;
        }

        if (event.target.closest("[data-mlff-upload-submit]")) {
          if (!state.mlffUploadDraft.fileRole) {
            showToast("数据上传", "请先选择上传文件类别。");
            return;
          }
          if (!state.mlffUploadDraft.fileName) {
            showToast("数据上传", "请先上传目标文件。");
            return;
          }
          if (!canSubmitMlffUpload()) {
            showToast("数据上传", "请补充必填项：材料名称、数据描述。");
            return;
          }
          mlffUpdateRecords.unshift({
            id: `mlff-upload-${Date.now()}`,
            uploadedAt: getMlffNowText(),
            fileName: state.mlffUploadDraft.fileName,
            fileType: getMlffUploadFileLabel(state.mlffUploadDraft.fileRole),
            sourceFormat: state.mlffUploadDraft.sourceFormat,
            category: "数据上传",
            status: "pending",
            source: state.mlffUploadForm.dataSource,
            materialName: state.mlffUploadForm.materialName.trim(),
            description: state.mlffUploadForm.description.trim()
          });
          closeModal("mlffUploadModal");
          renderMlffModule();
          showToast("数据上传", "文件已提交审核，审核通过后将写入机器学习力场数据库。");
          return;
        }

        if (event.target.closest("#mlffStartConvertBtn")) {
          const record = findMlffRecord(document.getElementById("mlffConvertSourceRecord").value);
          const targetFormat = document.getElementById("mlffConvertTargetFormat").value;
          if (!record) {
            showToast("文件格式转换", "请先选择待转换文件。");
            return;
          }
          state.mlffConvertDraft = { recordId: record.id, targetFormat };
          document.getElementById("mlffConvertStepLocal").hidden = true;
          document.getElementById("mlffConvertStepExternal").hidden = false;
          document.getElementById("mlffFinishConvertBtn").hidden = false;
          document.getElementById("mlffStartConvertBtn").hidden = true;
          document.getElementById("mlffConvertExternalText").textContent = `第三方工具正在将 ${record.fileName} 转换为 ${targetFormat} 格式。转换成功后可回传到当前系统。`;
          document.getElementById("mlffConvertExternalMeta").innerHTML = buildTwodConvertSummary([
            { label: "源文件", value: record.fileName },
            { label: "目标格式", value: targetFormat },
            { label: "执行状态", value: "转换中" }
          ]);
          return;
        }

        if (event.target.closest("#mlffFinishConvertBtn")) {
          const draft = state.mlffConvertDraft;
          const record = findMlffRecord(draft?.recordId);
          if (!record) return;
          const convertedName = replaceFileExtension(record.fileName, draft.targetFormat);
          mlffUpdateRecords.unshift({
            id: `mlff-convert-${Date.now()}`,
            uploadedAt: getMlffNowText(),
            fileName: convertedName,
            fileType: record.fileType,
            sourceFormat: `${record.sourceFormat || "-"} → ${draft.targetFormat}`,
            category: "文件格式转换",
            status: "approved",
            source: "第三方工具回传"
          });
          document.getElementById("mlffConvertStepExternal").hidden = true;
          document.getElementById("mlffConvertStepReturn").hidden = false;
          document.getElementById("mlffFinishConvertBtn").hidden = true;
          document.getElementById("mlffConvertReturnInfo").innerHTML = `
            <div class="twod-record-detail-card">
              <h4>回传完成</h4>
              <div class="detail-grid">
                <strong>源文件</strong><div>${record.fileName}</div>
                <strong>目标格式</strong><div>${draft.targetFormat}</div>
                <strong>新文件名</strong><div>${convertedName}</div>
                <strong>记录来源</strong><div>第三方工具回传</div>
              </div>
            </div>
          `;
          showToast("文件格式转换", "第三方工具已返回转换结果，系统记录已更新。");
          return;
        }
      });
    }

    const CATALYST_SEARCH_MODES = [
      { key: "keyword", label: "关键词检索", placeholder: "请输入中间产物、催化材料种类、材料成分、表面参数或催化性能关键词", helper: "支持按中间产物、催化材料种类、材料成分、表面参数和催化性能等关键词进行特定范围搜索。" },
      { key: "combo", label: "条件组合检索", placeholder: "请输入组合条件，如 100、Pt、Fe-N4、(111)", helper: "支持多条件文本组合检索，例如输入 100 即可筛选包含 (100) 的所有表面。" },
      { key: "elements", label: "元素组成检索", placeholder: "请输入元素组成，如 Pt、Fe,N,C 或 Ni Fe O H", helper: "按元素组成检索催化剂体系，多个元素将按“同时包含”规则筛选。" },
      { key: "route", label: "反应路线检索", placeholder: "", helper: "通过反应物和生成物条件检索催化反应路线对应的材料记录。" },
      { key: "property", label: "性质详情检索", helper: "按材料性质详情项进行筛选，可检索元素组成、结构特征、体系特征、晶格参数、原子结构和电子性质等内容。" }
    ];

