    function buildCatalystCompareBarChartSvg(materials, metricKey) {
      const metric = getCatalystCompareMetricCatalog()[metricKey];
      if (!metric || !materials.length) {
        return `<div class="catalyst-compare-empty">当前暂无可展示的对比数据。</div>`;
      }
      const width = Math.max(880, materials.length * 136);
      const height = 420;
      const margin = { top: 52, right: 24, bottom: 112, left: 84 };
      const innerWidth = width - margin.left - margin.right;
      const innerHeight = height - margin.top - margin.bottom;
      const maxValue = Math.max(...materials.map((item) => Number(item[metric.key]) || 0), 1);
      const groupWidth = innerWidth / Math.max(materials.length, 1);
      const barWidth = Math.min(58, groupWidth * 0.52);
      const steps = 4;
      const selectedOrder = new Map(materials.map((item, index) => [item.id, index + 1]));
      const hoveredId = state.catalystCompareHoverId || "";
      const formatValue = (value) => {
        if (!Number.isFinite(value)) return "-";
        const text = metric.precision === 0 ? String(Math.round(value)) : value.toFixed(metric.precision);
        return metric.unit === "%" ? `${text}%` : `${text} ${metric.unit}`;
      };
      const gridLines = Array.from({ length: steps + 1 }).map((_, index) => {
        const y = margin.top + (innerHeight / steps) * index;
        return `<line class="chart-gridline" x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}"></line>`;
      }).join("");
      const yLabels = Array.from({ length: steps + 1 }).map((_, index) => {
        const value = maxValue * (1 - index / steps);
        const y = margin.top + (innerHeight / steps) * index + 4;
        const label = metric.precision === 0 ? String(Math.round(value)) : value.toFixed(metric.precision);
        return `<text class="chart-label" x="${margin.left - 12}" y="${y}" text-anchor="end">${label}</text>`;
      }).join("");
      const bars = materials.map((item, index) => {
        const rawValue = Number(item[metric.key]) || 0;
        const barHeight = Math.max(8, (rawValue / maxValue) * innerHeight);
        const x = margin.left + groupWidth * index + (groupWidth - barWidth) / 2;
        const y = height - margin.bottom - barHeight;
        const color = getCatalystThemeColor(item);
        const hovered = hoveredId === item.id;
        const displayName = `${item.name} / ${catalystCompareRouteText(item)} / ${item.site}`;
        return `
          <g class="catalyst-compare-bar-group${hovered ? " is-hovered" : ""}" data-catalyst-compare-hover="${escapeHtml(item.id)}" data-catalyst-compare-material="${escapeHtml(item.id)}">
            <title>${escapeHtml(displayName)}: ${escapeHtml(formatValue(rawValue))}</title>
            <rect class="chart-bar${hovered ? " is-hovered" : ""}" x="${x}" y="${y}" width="${barWidth}" height="${barHeight}" fill="${color}" rx="10" ry="10"></rect>
            <text class="chart-label chart-value-label" x="${x + barWidth / 2}" y="${Math.max(margin.top + 18, y - 8)}" text-anchor="middle">${formatValue(rawValue)}</text>
            <text class="chart-label chart-name-label" x="${x + barWidth / 2}" y="${height - 54}" text-anchor="middle" transform="rotate(-32 ${x + barWidth / 2} ${height - 54})">${item.name}</text>
            <text class="chart-label chart-sub-label" x="${x + barWidth / 2}" y="${height - 32}" text-anchor="middle" transform="rotate(-32 ${x + barWidth / 2} ${height - 32})">${catalystCompareRouteText(item)} · ${item.site}</text>
          </g>
        `;
      }).join("");
      return `
        <svg viewBox="0 0 ${width} ${height}" class="material-line-chart-svg catalyst-compare-bar-chart" style="width:${width}px;height:${height}px;max-width:none;display:block;">
          ${gridLines}
          <line class="chart-axis-line" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
          <line class="chart-axis-line" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
          <text class="chart-label" x="${margin.left + innerWidth / 2}" y="${height - 16}" text-anchor="middle">材料名称（反应 / 位点）</text>
          <text class="chart-label" x="22" y="${margin.top + innerHeight / 2}" text-anchor="middle" dominant-baseline="middle" transform="rotate(-90 22 ${margin.top + innerHeight / 2})">活化能（eV）</text>
          ${yLabels}
          ${bars}
        </svg>
      `;
    }

    function renderCatalystCompareVisualization() {
      const materials = getCatalystCompareMaterials();
      const activeMetric = state.catalystCompareMetrics.find((key) => getCatalystCompareMetricCatalog()[key]) || "ea";
      return `
        <section class="catalyst-main-card catalyst-compare-chart-card">
          <h4>活化能对比（已选${materials.length}个材料）</h4>
          <div class="line-chart">${buildCatalystCompareBarChartSvg(materials, activeMetric)}</div>
        </section>
      `;
    }

    function renderCatalystCompareWorkbench(list) {
      const comparePool = getCatalystComparePoolMaterials(list);
      state.catalystCompareAllowedIds = comparePool.map((item) => item.id);
      const compareMaterials = getCatalystCompareMaterials();
      const pickerMaterials = getCatalystComparePickerMaterials(comparePool);
      const pageSize = Math.max(1, Number(state.catalystComparePickerPageSize) || 7);
      const totalPages = Math.max(1, Math.ceil(pickerMaterials.length / pageSize));
      const currentPage = Math.min(Math.max(1, Number(state.catalystComparePickerPage) || 1), totalPages);
      state.catalystComparePickerPage = currentPage;
      const pickerPageMaterials = pickerMaterials.slice((currentPage - 1) * pageSize, currentPage * pageSize);
      const routeTagSeen = new Map();
      comparePool.forEach((item) => {
        const rc = String((item && item.reactionClass) || "").trim();
        if (!rc) return;
        const code = rc.split(/\s+/)[0];
        const value = code.toLowerCase();
        if (!routeTagSeen.has(value)) routeTagSeen.set(value, code);
      });
      const routeTags = [{ value: "all", label: "全部" }].concat(
        Array.from(routeTagSeen.entries()).map((entry) => ({ value: entry[0], label: entry[1] }))
      );
      if (!routeTags.some((tag) => tag.value === (state.catalystCompareRoute || "all"))) {
        state.catalystCompareRoute = "all";
      }
      const metricCatalog = getCatalystCompareMetricCatalog();
      const fixedMetrics = Object.keys(getCatalystCompareMetricCatalog());
      const pickerPagerHtml = totalPages > 1 ? `
        <div class="catalyst-compare-picker-pager">
          <div class="pager">
            <button type="button" data-catalyst-compare-picker-page="${Math.max(1, currentPage - 1)}" ${currentPage === 1 ? "disabled" : ""}>‹</button>
            ${Array.from({ length: totalPages }, (_, index) => index + 1).map((page) => `
              <button type="button" class="${page === currentPage ? "active" : ""}" data-catalyst-compare-picker-page="${page}">${page}</button>
            `).join("")}
            <button type="button" data-catalyst-compare-picker-page="${Math.min(totalPages, currentPage + 1)}" ${currentPage === totalPages ? "disabled" : ""}>›</button>
          </div>
        </div>
      ` : "";
      return `
        <section class="card table-card catalyst-platform-workbench" id="catalystWorkbenchSection">
          <div style="padding:24px;">
            <div class="catalyst-compare-tip">温馨提示：本对比功能仅支持平台限定的催化材料集合，非列表内材料暂不支持对比分析</div>
            <section class="catalyst-compare-filter-panel">
              <div class="catalyst-compare-filter-row catalyst-compare-filter-row--compact">
                <div class="field catalyst-compare-search-field">
                  <label for="catalystCompareSearch">搜索材料</label>
                  <div class="catalyst-compare-searchbox">
                    <span class="catalyst-compare-search-icon" aria-hidden="true">
                      <svg viewBox="0 0 24 24" width="16" height="16" focusable="false" aria-hidden="true">
                        <circle cx="10.5" cy="10.5" r="6.5" fill="none" stroke="currentColor" stroke-width="2"></circle>
                        <path d="M15.2 15.2L20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
                      </svg>
                    </span>
                    <input id="catalystCompareSearch" type="text" placeholder="仅可选择下方列表内的对比材料" value="${escapeHtml(state.catalystCompareSearch || "")}">
                    ${state.catalystCompareSearch ? `<button class="catalyst-compare-search-clear" type="button" data-catalyst-compare-search-clear title="清空筛选">×</button>` : ""}
                  </div>
                </div>
                <div class="catalyst-compare-route-tags">
                  ${routeTags.map((item) => `
                    <button class="catalyst-compare-tag${state.catalystCompareRoute === item.value ? " is-active" : ""}" type="button" data-catalyst-compare-route="${item.value}">${item.label}</button>
                  `).join("")}
                </div>
              </div>
              <div class="catalyst-compare-capsule-row">
                <div class="catalyst-compare-capsule-head">
                  <span>已选材料</span>
                </div>
                <button class="btn" type="button" data-catalyst-compare-clear-all ${compareMaterials.length ? "" : "disabled"}>一键清除</button>
              </div>
              <div class="catalyst-compare-capsule-list">
                ${compareMaterials.length ? compareMaterials.map((item) => `
                  <span class="catalyst-compare-capsule" style="--catalyst-pill-bg:${getCatalystThemeColor(item)}1A;--catalyst-pill-border:${getCatalystThemeColor(item)}55;">
                    <strong>${escapeHtml(item.name)} · ${escapeHtml(catalystCompareRouteText(item))}</strong>
                    <button type="button" data-catalyst-compare-remove="${escapeHtml(item.id)}" aria-label="移除 ${escapeHtml(item.name)}">×</button>
                  </span>
                `).join("") : `<div class="catalyst-compare-empty catalyst-compare-capsule-empty">当前未选择材料，请从下方列表中勾选支持对比的材料。</div>`}
              </div>
              <div class="catalyst-compare-picker-wrap">
                <div class="catalyst-compare-picker-grid">
                  ${pickerMaterials.length ? pickerPageMaterials.map((item) => `
                    <label class="catalyst-compare-picker-item${state.catalystCompareSelected.includes(item.id) ? " is-active" : ""}${item.compareSupported ? "" : " is-disabled"}${state.catalystCompareHoverId === item.id ? " is-hovered" : ""}" title="${item.compareSupported ? `${escapeHtml(item.name)} 可加入对比` : "暂无对比数据"}" data-catalyst-compare-card="${escapeHtml(item.id)}">
                      <input type="checkbox" data-catalyst-compare-pick="${item.id}" ${state.catalystCompareSelected.includes(item.id) ? "checked" : ""} ${item.compareSupported ? "" : "disabled"}>
                      <div class="catalyst-compare-picker-body">
                        <div class="catalyst-compare-picker-top">
                          <strong>${escapeHtml(item.name)}</strong>
                          <span class="catalyst-compare-picker-chip">${state.catalystCompareSelected.includes(item.id) ? "已选" : (item.compareSupported ? (catalystCompareRouteText(item)) : "暂无对比数据")}</span>
                        </div>
                        <span>${escapeHtml(catalystCompareRouteText(item))} / ${escapeHtml(catalystCompareSiteText(item))} / ${escapeHtml(item.formula)}</span>
                      </div>
                    </label>
                  `).join("") : `<div class="catalyst-compare-empty">当前筛选条件下暂无可选材料。</div>`}
                </div>
                ${pickerPagerHtml}
              </div>
            </section>
            <section class="catalyst-compare-parameter-panel">
              <div class="catalyst-compare-parameter-title">对比参数</div>
              <div class="catalyst-compare-metric-row">
                ${fixedMetrics.map((metricKey) => `
                  <label class="algorithm-radio"><input type="radio" name="catalystCompareMetric" data-catalyst-metric="${metricKey}" ${state.catalystCompareMetrics.includes(metricKey) ? "checked" : ""}>${metricCatalog[metricKey].title}</label>
                `).join("")}
              </div>
            </section>
            <div style="margin-top:14px;">${renderCatalystCompareVisualization()}</div>
          </div>
        </section>
      `;
    }

    function buildCatalystCompareBarChartSvg(materials, metricKey) {
      const metric = getCatalystCompareMetricCatalog()[metricKey];
      const points = (materials || []).map((item) => ({ item, value: getCatalystCompareMetricRaw(metric, item) })).filter((point) => Number.isFinite(point.value));
      if (!metric || !points.length) {
        return `<div class="catalyst-compare-empty">当前所选材料在「${metric ? escapeHtml(metric.title) : "该性质"}」上暂无可对比的数值。</div>`;
      }
      const width = Math.max(860, points.length * 148);
      const height = 436;
      const margin = { top: 52, right: 24, bottom: 150, left: 104 };
      const innerWidth = width - margin.left - margin.right;
      const innerHeight = height - margin.top - margin.bottom;
      const values = points.map((point) => point.value);
      let domainMin = Math.min(0, ...values);
      let domainMax = Math.max(0, ...values);
      if (domainMin === domainMax) { domainMax += 1; domainMin -= 1; }
      const span = (domainMax - domainMin) || 1;
      const yOf = (value) => margin.top + ((domainMax - value) / span) * innerHeight;
      const y0 = yOf(0);
      const groupWidth = innerWidth / Math.max(points.length, 1);
      const barWidth = Math.min(56, groupWidth * 0.5);
      const steps = 4;
      const hoveredId = state.catalystCompareHoverId || "";
      const unitSuffix = metric.unit ? ` ${metric.unit}` : "";
      const formatValue = (value) => {
        if (!Number.isFinite(value)) return "-";
        const text = metric.precision === 0 ? String(Math.round(value)) : value.toFixed(metric.precision);
        return metric.unit === "%" ? `${text}%` : `${text}${unitSuffix}`;
      };
      const gridLines = Array.from({ length: steps + 1 }).map((_, index) => {
        const y = margin.top + (innerHeight / steps) * index;
        return `<line class="chart-gridline" x1="${margin.left}" y1="${y}" x2="${width - margin.right}" y2="${y}"></line>`;
      }).join("");
      const yLabels = Array.from({ length: steps + 1 }).map((_, index) => {
        const value = domainMax - (span / steps) * index;
        const y = margin.top + (innerHeight / steps) * index + 4;
        const label = metric.precision === 0 ? String(Math.round(value)) : value.toFixed(metric.precision);
        return `<text class="chart-label" x="${margin.left - 12}" y="${y}" text-anchor="end">${label}</text>`;
      }).join("");
      const bars = points.map((point, index) => {
        const value = point.value;
        const item = point.item;
        const yValue = yOf(value);
        const barTop = Math.min(y0, yValue);
        const barHeight = Math.max(2, Math.abs(yValue - y0));
        const x = margin.left + groupWidth * index + (groupWidth - barWidth) / 2;
        const color = getCatalystThemeColor(item);
        const hovered = hoveredId === item.id;
        const routeText = catalystCompareRouteText(item);
        const siteText = catalystCompareSiteText(item);
        const labelLine = `${item.name} · ${routeText} · ${siteText}`;
        const labelY = value >= 0 ? Math.max(margin.top + 14, barTop - 8) : (barTop + barHeight + 16);
        return `
          <g class="catalyst-compare-bar-group${hovered ? " is-hovered" : ""}" data-catalyst-compare-hover="${escapeHtml(item.id)}" data-catalyst-compare-material="${escapeHtml(item.id)}">
            <title>${escapeHtml(`${item.name} / ${routeText} / ${siteText}: ${formatValue(value)}`)}</title>
            <rect class="chart-bar${hovered ? " is-hovered" : ""}" x="${x}" y="${barTop}" width="${barWidth}" height="${barHeight}" fill="${color}" rx="8" ry="8"></rect>
            <text class="chart-label chart-value-label" x="${x + barWidth / 2}" y="${labelY}" text-anchor="middle">${formatValue(value)}</text>
            <text class="chart-label chart-name-label" x="${x + barWidth / 2}" y="${height - 42}" text-anchor="end" transform="rotate(-45 ${x + barWidth / 2} ${height - 42})">${escapeHtml(labelLine)}</text>
          </g>
        `;
      }).join("");
      const zeroBaseline = (domainMin < 0 && domainMax > 0) ? `<line class="chart-axis-line" x1="${margin.left}" y1="${y0}" x2="${width - margin.right}" y2="${y0}" stroke-dasharray="4 4"></line>` : "";
      return `
        <svg viewBox="0 0 ${width} ${height}" class="material-line-chart-svg catalyst-compare-bar-chart" style="width:${width}px;height:${height}px;max-width:none;display:block;">
          ${gridLines}
          <line class="chart-axis-line" x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${height - margin.bottom}"></line>
          <line class="chart-axis-line" x1="${margin.left}" y1="${height - margin.bottom}" x2="${width - margin.right}" y2="${height - margin.bottom}"></line>
          ${zeroBaseline}
          <text class="chart-label" x="${margin.left + innerWidth / 2}" y="${height - 14}" text-anchor="middle">材料名称（反应 / 位点）</text>
          <text class="chart-label" x="24" y="${margin.top + innerHeight / 2}" text-anchor="middle" dominant-baseline="middle" transform="rotate(-90 24 ${margin.top + innerHeight / 2})">${escapeHtml(metric.title)}${metric.unit ? `（${metric.unit}）` : ""}</text>
          ${yLabels}
          ${bars}
        </svg>
      `;
    }

    function renderCatalystCompareVisualization() {
      const materials = getCatalystCompareMaterials();
      const metricCatalog = getCatalystCompareMetricCatalog();
      const activeMetric = state.catalystCompareMetrics.find((key) => metricCatalog[key]) || "ea";
      if (!materials.length) {
        return `
          <section class="catalyst-main-card catalyst-compare-chart-card">
            <h4>对比结果</h4>
            <div class="catalyst-compare-empty">当前未选择材料，请先从上方材料列表中勾选需要对比的对象（每点选一个分子，下方对比表与图表就增加一列）。</div>
          </section>
        `;
      }
      const legend = `
        <div class="catalyst-compare-chart-legend">
          ${materials.map((item) => `
            <span class="catalyst-compare-legend-item${state.catalystCompareHoverId === item.id ? " is-hovered" : ""}" data-catalyst-compare-hover="${escapeHtml(item.id)}" data-catalyst-compare-material="${escapeHtml(item.id)}">
              <span class="catalyst-compare-legend-swatch" style="background:${getCatalystThemeColor(item)};"></span>
              <span>${escapeHtml(item.name)} · ${escapeHtml(catalystCompareRouteText(item))}</span>
            </span>
          `).join("")}
        </div>
      `;
      const cellBase = "border:1px solid #e7edf7;padding:8px 10px;";
      const descRows = [
        { label: "化学式", get: (m) => m.formula },
        { label: "组成元素", get: (m) => (m.elements || []).join(" / ") },
        { label: "表面 / 晶面", get: (m) => m.surface },
        { label: "Miller 指数", get: (m) => (m.millerH != null ? `(${m.millerH} ${m.millerK} ${m.millerL})` : null) },
        { label: "吸附中间体", get: (m) => m.intermediate },
        { label: "反应类别", get: (m) => (m.reactionClass ? String(m.reactionClass).toUpperCase() : null) },
        { label: "配位结合原子", get: (m) => m.coordinationBinder },
        { label: "催化剂类型", get: (m) => m.catalystType },
        { label: "数据来源", get: (m) => m.source || m.dataSource },
        { label: "计算精度", get: (m) => m.method || m.sourceMethod }
      ];
      const numericKeys = Object.keys(metricCatalog);
      const headCols = materials.map((item) => {
        const color = getCatalystThemeColor(item);
        return `
          <th style="${cellBase}text-align:center;min-width:150px;background:${color}14;border-bottom:2px solid ${color};">
            <span style="display:inline-flex;align-items:center;gap:6px;font-weight:700;color:#1f2d3d;">
              <span style="width:10px;height:10px;border-radius:50%;background:${color};display:inline-block;"></span>${escapeHtml(item.name)}
            </span>
            <div style="font-weight:400;color:#7c8aa3;font-size:12px;margin-top:2px;">${escapeHtml(catalystCompareRouteText(item))} · ${escapeHtml(catalystCompareSiteText(item))}</div>
          </th>
        `;
      }).join("");
      const sectionRow = (title, bg, color) => `<tr><td colspan="${materials.length + 1}" style="${cellBase}background:${bg};color:${color};font-weight:700;">${title}</td></tr>`;
      const descRowsHtml = descRows.map((row) => {
        const cells = materials.map((m) => {
          const value = row.get(m);
          const text = (value == null || value === "") ? `<span style="color:#b3bccb;">N/A</span>` : escapeHtml(String(value));
          return `<td style="${cellBase}text-align:center;color:#2a3b57;">${text}</td>`;
        }).join("");
        return `<tr><th scope="row" style="${cellBase}text-align:left;background:#f7f9fd;font-weight:600;color:#33507d;">${escapeHtml(row.label)}</th>${cells}</tr>`;
      }).join("");
      const numericRowsHtml = numericKeys.map((key) => {
        const metric = metricCatalog[key];
        const rawList = materials.map((m) => getCatalystCompareMetricRaw(metric, m));
        const finite = rawList.filter((n) => Number.isFinite(n));
        let bestVal = null;
        if (finite.length > 1 && metric.better === "low") bestVal = Math.min(...finite);
        if (finite.length > 1 && metric.better === "high") bestVal = Math.max(...finite);
        const isActive = key === activeMetric;
        const cells = materials.map((m, idx) => {
          const raw = rawList[idx];
          if (!Number.isFinite(raw)) return `<td style="${cellBase}text-align:center;"><span style="color:#b3bccb;">N/A</span></td>`;
          const best = bestVal != null && raw === bestVal;
          const cellStyle = best ? "font-weight:700;color:#1a7f4b;background:#eafaf1;" : "color:#2a3b57;";
          return `<td style="${cellBase}text-align:center;${cellStyle}">${escapeHtml(formatCatalystCompareMetricValue(key, m))}${best ? ' <span style="font-size:11px;">▲最优</span>' : ""}</td>`;
        }).join("");
        const labelStyle = isActive ? "background:#eef3ff;color:#165DFF;border-left:3px solid #165DFF;" : "background:#f7f9fd;color:#33507d;";
        const unitText = metric.unit ? `<span style="color:#93a0b5;font-weight:400;">（${metric.unit}）</span>` : "";
        return `<tr><th scope="row" style="${cellBase}text-align:left;font-weight:600;${labelStyle}">${escapeHtml(metric.title)}${unitText}</th>${cells}</tr>`;
      }).join("");
      const tableHtml = `
        <div style="overflow-x:auto;">
          <table class="catalyst-compare-matrix" style="width:100%;border-collapse:collapse;font-size:13px;">
            <thead>
              <tr>
                <th style="${cellBase}text-align:left;background:#eef2fa;min-width:140px;color:#33507d;">对比性质</th>
                ${headCols}
              </tr>
            </thead>
            <tbody>
              ${sectionRow("材料标识与结构", "#f2f6fd", "#3f5c86")}
              ${descRowsHtml}
              ${sectionRow("可比数值性质（真实计算 / 结构解析）", "#f2f6fd", "#3f5c86")}
              ${numericRowsHtml}
            </tbody>
          </table>
        </div>
      `;
      return `
        <div class="catalyst-compare-chart-stack">
          ${legend}
          <section class="catalyst-main-card catalyst-compare-chart-card">
            <h4>多性质对比表（已选 ${materials.length} 个材料 · ${descRows.length + numericKeys.length} 项可比性质）</h4>
            ${tableHtml}
          </section>
          <section class="catalyst-main-card catalyst-compare-chart-card">
            <h4>${escapeHtml(metricCatalog[activeMetric].title)}对比图（在上方「对比参数」切换展示的性质）</h4>
            <div class="line-chart">${buildCatalystCompareBarChartSvg(materials, activeMetric)}</div>
          </section>
        </div>
      `;
    }

    function renderCatalystBuildWorkbench(material) {
      const currentTool = catalystToolConfigs[state.selectedCatalystTool] || catalystToolConfigs.bulk;
      return `
        <section class="card table-card catalyst-platform-workbench" id="catalystWorkbenchSection">
          <div class="table-head">
            <div class="catalyst-workbench-head">
              <div>
                <h3>催化构建</h3>
                <p>围绕当前材料执行体相晶格生成、Slab 构建、吸附物添加等催化建模任务。</p>
              </div>
              <span class="catalyst-batch-note">当前构建对象：${material.name}</span>
            </div>
          </div>
          <div style="padding:24px;">
            <div class="catalyst-builder-tool-row">
              ${Object.entries(catalystToolConfigs).map(([key, config]) => `
                <button class="btn${state.selectedCatalystTool === key ? "-primary" : ""}" type="button" data-catalyst-tool-select="${key}">${config.title}</button>
              `).join("")}
            </div>
            <div class="catalyst-workbench-grid">
              <article class="catalyst-workbench-card">
                <h4>${currentTool.title}</h4>
                <p>${currentTool.subtitle}</p>
                <div class="catalyst-form-grid" style="margin-top:18px;">
                  ${renderCatalystToolFields(currentTool)}
                </div>
                <div class="catalyst-workbench-subgrid">
                  <div class="catalyst-workbench-subcard">
                    <h5>电子结构分析</h5>
                    ${currentTool.checksA.map((item, index) => `<label class="algorithm-radio"><input type="checkbox" ${index < 2 ? "checked" : ""}>${item}</label>`).join("")}
                  </div>
                  <div class="catalyst-workbench-subcard">
                    <h5>几何结构分析</h5>
                    ${currentTool.checksB.map((item, index) => `<label class="algorithm-radio"><input type="checkbox" ${index < 2 ? "checked" : ""}>${item}</label>`).join("")}
                  </div>
                </div>
                <div class="twod-detail-actions" style="margin-top:18px;">
                  <button class="btn" type="button" data-catalyst-tool-preview>预览</button>
                  <button class="btn-primary" type="button" data-catalyst-tool-generate>生成催化构建任务</button>
                </div>
              </article>
              <article class="catalyst-workbench-card">
                <h4>当前材料信息</h4>
                <p>${material.name} / ${material.reactionType} / ${material.surface}</p>
                <div class="catalyst-workbench-preview" id="catalystWorkbenchBuildCanvas"></div>
                <div class="catalyst-selection-pills">
                  <span>元素组成：${material.elements.join(", ")}</span>
                  <span>晶格参数：a=${material.latticeA.toFixed(2)} Å</span>
                  <span>POSCAR：支持导出</span>
                </div>
              </article>
            </div>
          </div>
        </section>
      `;
    }

    function renderCatalystWorkbenchSection(list) {
      const material = getCatalystWorkbenchMaterial(list);
      if (state.catalystWorkbenchMode === "compare") return renderCatalystCompareWorkbench(list);
      if (state.catalystWorkbenchMode === "build") return renderCatalystBuildWorkbench(material);
      return renderCatalystSiteWorkbench(material);
    }

    function syncCatalystWorkbenchCanvases(list) {
      const material = getCatalystWorkbenchMaterial(list);
      if (state.catalystWorkbenchMode === "site") {
        renderCatalystSurfaceCanvas("catalystWorkbenchSiteCanvas", material);
        return;
      }
      if (state.catalystWorkbenchMode === "build") {
        renderCatalystCrystalCanvas("catalystWorkbenchBuildCanvas", material);
      }
    }

