    function renderToolReferenceDoc(tool, row, category) {
      const requestRows = [
        { name: "tool_id", type: "string", required: true, desc: "工具唯一标识" },
        { name: "input_file", type: "file", required: true, desc: "待处理的结构或数据文件" },
        { name: "output_format", type: "string", required: false, desc: "输出文件格式，默认 standard" },
        { name: "config", type: "object", required: false, desc: "工具运行配置与参数" }
      ];
      const responseRows = [
        { name: "status", type: "string", desc: "任务执行状态" },
        { name: "task_id", type: "string", desc: "本次工具调用任务编号" },
        { name: "output_files", type: "array", desc: "处理完成后的结果文件列表" },
        { name: "report", type: "object", desc: "工具运行摘要与质量检查报告" }
      ];
      const code = buildToolApiCode(tool, row, category);
      const operation = tool.operation || [];
      const notice = tool.notice || [];
      const effect = tool.effect || [];
      return `
        <div class="algorithm-reference-doc tool-reference-doc">
          <section class="algorithm-reference-hero">
            <h3>${escapeHtml(tool.name)}</h3>
            <p>${escapeHtml(effect[0] || category.desc || "该工具面向低维材料数据处理与科研分析场景，支持通过标准接口完成工具调用和结果输出。")} </p>
            <div class="algorithm-reference-tags">
              <div class="algorithm-reference-tag"><span>功能特点</span>${escapeHtml(effect.slice(0, 3).join("、") || category.desc)}</div>
              <div class="algorithm-reference-tag"><span>适用场景</span>${escapeHtml(category.scenario)}</div>
            </div>
          </section>

          <section class="algorithm-reference-section">
            <div class="algorithm-reference-section-head">
              <h4>API 调用示例</h4>
              <button class="algorithm-reference-copy" type="button" data-tool-copy-code aria-label="复制 API 调用示例">复制代码</button>
            </div>
            <pre class="algorithm-reference-code" id="toolReferenceCode">${escapeHtml(code)}</pre>
          </section>

          <section class="algorithm-reference-section">
            <div class="algorithm-reference-section-head"><h4>请求参数</h4></div>
            <div class="algorithm-reference-table-wrap">
              <table class="algorithm-reference-table">
                <thead><tr><th style="width:24%;">参数名</th><th style="width:16%;">类型</th><th style="width:12%;">必填</th><th>说明</th></tr></thead>
                <tbody>${requestRows.map((item) => `<tr><td><code>${escapeHtml(item.name)}</code></td><td>${escapeHtml(item.type)}</td><td>${item.required ? '<span class="algorithm-reference-required">必填</span>' : "否"}</td><td>${escapeHtml(item.desc)}</td></tr>`).join("")}</tbody>
              </table>
            </div>
          </section>

          <section class="algorithm-reference-section">
            <div class="algorithm-reference-section-head"><h4>返回结果</h4></div>
            <div class="algorithm-reference-table-wrap">
              <table class="algorithm-reference-table">
                <thead><tr><th style="width:24%;">字段名</th><th style="width:20%;">类型</th><th>说明</th></tr></thead>
                <tbody>${responseRows.map((item) => `<tr><td><code>${escapeHtml(item.name)}</code></td><td>${escapeHtml(item.type)}</td><td>${escapeHtml(item.desc)}</td></tr>`).join("")}</tbody>
              </table>
            </div>
          </section>

          <section class="algorithm-reference-section tool-reference-info-section">
            <div class="algorithm-reference-section-head"><h4>使用说明</h4></div>
            <div class="tool-reference-columns">
              <div><h5>操作流程</h5><ol>${operation.map((item) => `<li>${escapeHtml(item)}</li>`).join("") || `<li>${escapeHtml(category.scenario)}</li>`}</ol></div>
              <div><h5>注意事项</h5><ul>${notice.map((item) => `<li>${escapeHtml(item)}</li>`).join("") || "<li>请按照使用手册准备输入数据并校验本地运行环境。</li>"}</ul></div>
            </div>
          </section>

          <section class="algorithm-reference-section">
            <div class="algorithm-reference-section-head"><h4>资源信息</h4></div>
            <div class="algorithm-reference-grid">
              <div class="algorithm-reference-info"><span>工具分类</span><strong>${escapeHtml(row.category)}</strong></div>
              <div class="algorithm-reference-info"><span>调用方式</span><strong>POST</strong></div>
              <div class="algorithm-reference-info"><span>资源类型</span><strong>ZIP 代码包 / 使用手册</strong></div>
            </div>
          </section>
        </div>
      `;
    }

    function renderToolDetailPage() {
      const mount = document.getElementById("toolPageMount");
      const category = toolCategoryConfigs[state.selectedToolCategory];
      const currentRow = getSelectedToolRow();
      const currentTool = currentRow ? (toolSubmoduleData[currentRow.id] || toolDetailData[currentRow.id]) : null;
      if (!mount || !category || !currentRow || !currentTool) return;
      mount.innerHTML = `
        <div class="algorithm-reference-toolbar tool-reference-toolbar">
          <button class="btn" type="button" data-tool-back>← 返回数据工具开发</button>
        </div>
        <div class="algorithm-reference-page">
          ${renderToolReferenceDoc(currentTool, currentRow, category)}
        </div>
      `;
    }

    function renderToolsPage() {
      ensureToolSelection();
      if (state.toolPageView === "detail") {
        renderToolDetailPage();
        updateBreadcrumb("tools");
        return;
      }
      renderToolOverviewPage();
      updateBreadcrumb("tools");
    }

    function bindToolListInteractions() {
      if (document.body.dataset.toolListBound === "true") return;
      document.body.dataset.toolListBound = "true";
      document.getElementById("toolPageBackBtn")?.addEventListener("click", () => {
        state.toolPageView = "overview";
        renderToolsPage();
      });
      document.body.addEventListener("click", (event) => {
        const copyTrigger = event.target.closest("[data-tool-copy-code]");
        if (copyTrigger) {
          const code = document.getElementById("toolReferenceCode")?.textContent || "";
          const done = () => {
            copyTrigger.textContent = "已复制";
            window.setTimeout(() => { copyTrigger.textContent = "复制代码"; }, 1600);
            if (typeof showToast === "function") showToast("工具详情", "API 调用示例已复制。");
          };
          if (navigator.clipboard?.writeText) navigator.clipboard.writeText(code).then(done).catch(done);
          else done();
          return;
        }
        const tabTrigger = event.target.closest("[data-tool-tab]");
        if (tabTrigger) {
          state.toolPageView = "overview";
          state.selectedToolCategory = tabTrigger.dataset.toolTab;
          state.toolListPage = 1;
          state.selectedToolItem = getToolRowsByCategory(state.selectedToolCategory)[0]?.id || "";
          renderToolsPage();
          return;
        }

        const enterCategory = event.target.closest("[data-tool-enter-category]");
        if (enterCategory) {
          state.toolPageView = "detail";
          state.selectedToolCategory = enterCategory.dataset.toolEnterCategory;
          state.selectedToolItem = getToolRowsByCategory(state.selectedToolCategory)[0]?.id || "";
          renderToolsPage();
          return;
        }
        const backTrigger = event.target.closest("[data-tool-back]");
        if (backTrigger) {
          state.toolPageView = "overview";
          renderToolsPage();
          return;
        }
        const itemTrigger = event.target.closest("[data-tool-item]");
        if (itemTrigger) {
          state.selectedToolItem = itemTrigger.dataset.toolItem;
          renderToolsPage();
          return;
        }
        const trigger = event.target.closest("[data-tool-action]");
        if (!trigger) return;
        const toolId = trigger.dataset.toolId;
        const action = trigger.dataset.toolAction;
        if (action === "guide") tdOpenGuide(toolId);
        if (action === "code") tdDownloadCode(toolId);
        if (action === "detail") {
          const row = toolListRows.find((item) => item.id === toolId);
          if (!row) return;
          state.toolPageView = "detail";
          state.selectedToolCategory = row.category;
          state.selectedToolItem = row.id;
          renderToolsPage();
        }
      });
    }

    function bindToolDownloadInteractions() {
      const nextBtn = document.getElementById('toolDownloadNextBtn');
      if (!nextBtn || nextBtn.dataset.toolDownloadBound === 'true') return;
      nextBtn.dataset.toolDownloadBound = 'true';
      nextBtn.addEventListener('click', () => {
        const info = toolSubmoduleData[toolDownloadState.toolId] || toolDetailData[toolDownloadState.toolId];
        closeModal('toolDownloadModal');
        showToast('下载代码包', `${info ? info.name : '当前工具'} 的代码包下载已触发。`);
      });
    }

    function bindToolGuideInteractions() {
      const nav = document.getElementById('toolGuideNav');
      if (!nav || nav.dataset.toolGuideBound === 'true') return;
      nav.dataset.toolGuideBound = 'true';
      nav.addEventListener('click', (e) => {
        const btn = e.target.closest('button[data-guide-section]');
        if (!btn) return;
        const section = btn.dataset.guideSection;
        nav.querySelectorAll('button').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        document.querySelectorAll('.tool-guide-section').forEach(s => {
          s.classList.toggle('active', s.dataset.guidePage === section);
        });
      });
    }

