/* 采集任务 → 所属结构类型（或关系）：一个任务只挂一类结构。
   三类结构轮转分配，使「查看详情」时能直观看到三者互斥的效果。
   注意：列表页只有「已完成」状态的任务才带「查看详情」按钮，
   因此 CLT-2026-0804-01（分子结构）与 CLT-2026-0803-06（大体系结构）
   是可点击进入详情页的两条；其余任务用于状态/操作列演示。 */
const MLFF_TASK_STRUCTURE_MAP = {
  "CLT-2026-0804-01": { structure: "molecule", offset: 0,  count: 6 },
  "CLT-2026-0803-06": { structure: "large",    offset: 0,  count: 6 },
  "CLT-2026-0804-02": { structure: "small",    offset: 0,  count: 6 },
  "CLT-2026-0804-03": { structure: "large",    offset: 6,  count: 5 },
  "CLT-2026-0803-05": { structure: "molecule", offset: 6,  count: 5 },
  "CLT-2026-0803-07": { structure: "small",    offset: 6,  count: 5 },
  "CLT-2026-0802-03": { structure: "molecule", offset: 11, count: 5 },
  "CLT-2026-0802-04": { structure: "small",    offset: 11, count: 5 }
};

/* 结构类型 → 该类型的主体数据库（用于采集范围文案） */
const MLFF_STRUCTURE_SOURCE = {
  molecule: "Q-Chem / Molpro 单分子性质计算数据集",
  small: "界面/团簇小体系采样数据集（OpenMM / I-PI / Gromacs）",
  large: "大体系采样与拟合数据集（DP-Gen / DeepMDKit / REANN）"
};

    const LOWDIM_INGEST_DETAIL_TABS = [
      { key: "overview", label: "采集结果概览", hint: "关键指标与通过率" },
      { key: "scope", label: "采集范围", hint: "来源 / 材料 / 性质范围" },
      { key: "quality", label: "质检结论", hint: "质检项与异常标记" },
      { key: "samples", label: "样例数据", hint: "采集样例与后续状态" },
      { key: "files", label: "输出文件", hint: "归档文件清单" },
      { key: "timeline", label: "执行记录", hint: "任务执行全过程" }
    ];

    /* 机器学习力场：三类结构为「或」关系，任一采集任务只归属其中一类。
       标签页因此按任务动态生成 —— 第 4 个标签页由「样例数据」变成该任务实际所属的那一类结构。 */
    function getMlffTaskStructure(task) {
      const taskId = typeof task === "string" ? task : task?.id;
      const direct = MLFF_TASK_STRUCTURE_MAP[taskId];
      if (direct) return direct;
      /* 未显式配置的任务：按任务在列表中的序号轮转分配，保证「或关系」始终成立 */
      const pageId = "lowdim-ingest-mlff";
      const list = getTwodIngestCollectionTasks(pageId);
      const index = list.findIndex((item) => item.id === taskId);
      if (index < 0) return null;
      const keys = ["molecule", "small", "large"];
      const structure = keys[index % keys.length];
      return { structure: structure, offset: 0, count: 6 };
    }

    function getLowdimIngestDetailTabs(task, pageId) {
      const isMlff = getLowdimMaterialKey(pageId) === "mlff";
      const mapping = isMlff ? getMlffTaskStructure(task) : null;
      if (!mapping || !MLFF_STRUCTURE_META[mapping.structure]) {
        return LOWDIM_INGEST_DETAIL_TABS;
      }
      const meta = MLFF_STRUCTURE_META[mapping.structure];
      return LOWDIM_INGEST_DETAIL_TABS.map((tab) => tab.key === "samples"
        ? { key: "samples", label: meta.label, hint: meta.hint, structure: mapping.structure }
        : tab);
    }

    /* 取该任务应展示的结构样例记录（按分片），并附带所属类型元信息 */
    function getMlffTaskStructureData(task, pageId) {
      if (getLowdimMaterialKey(pageId) !== "mlff") return null;
      const mapping = getMlffTaskStructure(task);
      if (!mapping) return null;
      const meta = MLFF_STRUCTURE_META[mapping.structure];
      const all = MLFF_STRUCTURE_SAMPLES[mapping.structure] || [];
      const offset = Math.max(0, Number(mapping.offset) || 0);
      const count = Math.max(1, Number(mapping.count) || all.length);
      const records = all.slice(offset, offset + count);
      return {
        structure: mapping.structure,
        meta: meta,
        fields: MLFF_STRUCTURE_FIELDS[mapping.structure] || [],
        records: records,
        total: all.length,
        offset: offset,
        source: MLFF_STRUCTURE_SOURCE[mapping.structure] || ""
      };
    }

    function getLowdimIngestDetailState() {
      if (!state.lowdimIngestDetail) {
        state.lowdimIngestDetail = { taskId: "", pageId: "lowdim-ingest-twod", tab: "overview" };
      }
      return state.lowdimIngestDetail;
    }

    function openLowdimIngestDetailPage(taskId, pageId = "lowdim-ingest-twod") {
      const detail = getLowdimIngestDetailState();
      detail.taskId = taskId || "";
      detail.pageId = pageId || "lowdim-ingest-twod";
      detail.tab = "overview";
      state.page = "lowdim-ingest-detail";
      renderLowdimIngestDetailPage();
      if (typeof switchPage === "function") switchPage("lowdim-ingest-detail");
      /* switchPage 之后再次断言：确保页面与导航高亮落到详情页，
         避免被其它 setTimeout 里的 switchPage 覆盖 */
      const page = document.getElementById("page-lowdim-ingest-detail");
      if (page) page.classList.add("active");
      document.querySelectorAll(".page").forEach((node) => {
        if (node !== page) node.classList.remove("active");
      });
      document.querySelectorAll(".nav-btn").forEach((node) => {
        if (node.dataset.page === pageId) node.classList.add("active");
      });
      try { window.scrollTo(0, 0); } catch (error) {}
    }

    function renderLowdimIngestDetailSummary(task, detail, material) {
      const level = getTwodIngestTaskSecurityLevel(task);
      const levelMeta = TWOD_INGEST_SECURITY_LEVELS[level] || TWOD_INGEST_SECURITY_LEVELS["第1级"];
      const esc = escapeLowDimHtml;
      const items = [
        { label: "任务ID", value: task.id, mono: true },
        { label: "数据采集方式", value: task.method || "-" },
        { label: "采集方式", value: task.collectionMode || "全量采集" },
        { label: "任务优先级", value: task.priority || "中" },
        { label: "创建人", value: task.creator || "-" },
        { label: "创建时间", value: task.createdAt || "-" },
        { label: "数据安全等级", value: levelMeta.fullLabel, tone: "level" },
        { label: "执行时间", value: detail.timeRange || "-", wide: true }
      ];
      return `
        <div class="ldidp-summary-left">
          <div class="ldidp-summary-title">
            <h3>${esc(task.name || `${material.short}数据采集任务`)}</h3>
            <span class="ldidp-status ${esc(getTwodIngestTaskStatusClass(task.status))}">${esc(task.status || "-")}</span>
            <span class="ldidp-level" title="${esc(levelMeta.description)}">${esc(levelMeta.label)}</span>
          </div>
          <p class="ldidp-summary-desc">${esc(task.description || `采集${material.short}的${material.object}`)}</p>
        </div>
        <dl class="ldidp-summary-grid">
          ${items.map((item) => `
            <div class="ldidp-summary-item${item.wide ? " is-wide" : ""}">
              <dt>${esc(item.label)}</dt>
              <dd class="${item.mono ? "is-mono" : ""}${item.tone === "level" ? " is-level" : ""}">${esc(item.value || "-")}</dd>
            </div>
          `).join("")}
        </dl>
      `;
    }

    function renderLowdimIngestDetailTabs(activeTab, tabs) {
      const tabList = Array.isArray(tabs) && tabs.length ? tabs : LOWDIM_INGEST_DETAIL_TABS;
      return tabList.map((tab, index) => `
        <button class="ldidp-tab${tab.key === activeTab ? " active" : ""}" type="button" role="tab"
          aria-selected="${tab.key === activeTab ? "true" : "false"}"
          data-ldidp-tab="${escapeLowDimHtml(tab.key)}">
          <span class="ldidp-tab-index">${index + 1}</span>
          <span class="ldidp-tab-text">
            <strong>${escapeLowDimHtml(tab.label)}</strong>
            <small>${escapeLowDimHtml(tab.hint)}</small>
          </span>
        </button>
      `).join('<span class="ldidp-tab-sep" aria-hidden="true"></span>');
    }

    function renderLowdimIngestDetailTabContent(tabKey, task, detail, material, pageId) {
      const esc = escapeLowDimHtml;
      const level = getTwodIngestTaskSecurityLevel(task);
      const levelMeta = TWOD_INGEST_SECURITY_LEVELS[level] || TWOD_INGEST_SECURITY_LEVELS["第1级"];

      if (tabKey === "overview") {
        const stats = [
          { label: "采集总量", value: Number(detail.fetchedCount || 0).toLocaleString(), unit: "条" },
          { label: "有效数据", value: Number(detail.validCount || 0).toLocaleString(), unit: "条" },
          { label: "重复合并", value: Number(detail.duplicateCount || 0).toLocaleString(), unit: "条" },
          { label: "异常标记", value: Number(detail.abnormalCount || 0).toLocaleString(), unit: "条", tone: "warn" }
        ];
        const validRate = Number(detail.fetchedCount)
          ? Math.round((Number(detail.validCount || 0) / Number(detail.fetchedCount)) * 1000) / 10
          : 0;
        return `
          <div class="ldidp-tab-intro">
            <h3>采集结果概览</h3>
            <p>本任务已完成${esc(material.short)}来源数据抽取、字段映射、单位统一、重复数据合并和异常记录标记，结果可进入后续数据资源录入与标准化流程。</p>
          </div>
          <div class="ldidp-stat-grid">
            ${stats.map((item) => `
              <article class="ldidp-stat-card${item.tone === "warn" ? " is-warn" : ""}">
                <span>${esc(item.label)}</span>
                <strong>${esc(item.value)}<em>${esc(item.unit)}</em></strong>
              </article>
            `).join("")}
          </div>
          <section class="ldidp-card">
            <header class="ldidp-card-head"><h4>数据质量与归档</h4></header>
            <div class="ldidp-metric-list">
              <div class="ldidp-metric">
                <div class="ldidp-metric-top"><span>有效数据占比</span><strong>${esc(String(validRate))}%</strong></div>
                <div class="ldidp-metric-bar"><i style="width:${Math.max(0, Math.min(100, validRate))}%"></i></div>
              </div>
              <div class="ldidp-kv-compact">
                <div><span>质检通过率</span><strong>${esc(detail.passRate || "-")}</strong></div>
                <div><span>数据安全等级</span><strong class="is-level" title="${esc(levelMeta.description)}">${esc(levelMeta.fullLabel)}</strong></div>
                <div><span>输出文件</span><strong>${(detail.outputFiles || []).length} 个</strong></div>
                <div><span>质检项</span><strong>${(detail.qualityChecks || []).length} 项</strong></div>
              </div>
            </div>
          </section>
          <section class="ldidp-card">
            <header class="ldidp-card-head"><h4>执行摘要</h4></header>
            <ol class="ldidp-timeline">
              ${(detail.timeline || []).map((item) => {
                const [head, ...rest] = String(item).split("：");
                return `<li><span class="ldidp-timeline-dot" aria-hidden="true"></span><div><strong>${esc(head)}</strong>${rest.length ? `<p>${esc(rest.join("："))}</p>` : ""}</div></li>`;
              }).join("") || `<li class="is-empty">暂无执行记录</li>`}
            </ol>
          </section>
        `;
      }

      if (tabKey === "scope") {
        const rows = [
          ["来源范围", detail.sourceScope],
          ["材料范围", detail.materialScope],
          ["性质范围", detail.propertyScope]
        ];
        return `
          <div class="ldidp-tab-intro">
            <h3>采集范围</h3>
            <p>本次任务限定的数据来源、材料体系与性质范围。</p>
          </div>
          <section class="ldidp-card">
            <header class="ldidp-card-head"><h4>范围定义</h4></header>
            <dl class="ldidp-kv-list">
              ${rows.map(([label, value]) => `
                <div class="ldidp-kv-row">
                  <dt>${esc(label)}</dt>
                  <dd>${esc(value || "-")}</dd>
                </div>
              `).join("")}
            </dl>
          </section>
          <section class="ldidp-card">
            <header class="ldidp-card-head"><h4>范围口径说明</h4></header>
            <ul class="ldidp-note-list">
              <li><span>来源</span>仅从已在平台登记授权状态的公开数据库与文献源采集，来源标识随记录一并入库。</li>
              <li><span>材料</span>按材料体系分类过滤候选记录，未匹配到标准分类的结构进入待复核队列。</li>
              <li><span>性质</span>仅采集已定义资源对象下的标准字段，非标准字段统一进入异常标记。</li>
            </ul>
          </section>
        `;
      }

      if (tabKey === "quality") {
        return `
          <div class="ldidp-tab-intro">
            <h3>质检结论</h3>
            <p>系统对采集结果执行字段完整性、单位映射、结构可解析性与重复合并检查。</p>
          </div>
          <section class="ldidp-card">
            <header class="ldidp-card-head">
              <h4>质检项</h4>
              <span class="ldidp-card-tag">共 ${(detail.qualityChecks || []).length} 项</span>
            </header>
            <div class="ldidp-chip-list">
              ${(detail.qualityChecks || []).map((item) => `<span class="ldidp-chip">${esc(item)}</span>`).join("") || `<span class="ldidp-chip is-empty">暂无质检项</span>`}
            </div>
          </section>
          <section class="ldidp-card">
            <header class="ldidp-card-head"><h4>异常处理建议</h4></header>
            <div class="ldidp-kv-compact">
              <div><span>异常标记总数</span><strong>${Number(detail.abnormalCount || 0).toLocaleString()} 条</strong></div>
              <div><span>质检通过率</span><strong>${esc(detail.passRate || "-")}</strong></div>
            </div>
            <p class="ldidp-hint">异常记录不会阻塞任务归档，但需在数据资源录入前完成人工复核或补录。</p>
          </section>
        `;
      }

      if (tabKey === "samples") {
        /* 机器学习力场：按任务实际所属结构类型展示真实样例数据表 */
        const mlffData = getMlffTaskStructureData(task, pageId);
        if (mlffData) return renderMlffStructureTab(mlffData, task, detail);
        return `
          <div class="ldidp-tab-intro">
            <h3>样例数据</h3>
            <p>展示本任务采集到的部分样例记录及其后续入库状态。</p>
          </div>
          <section class="ldidp-card">
            <header class="ldidp-card-head">
              <h4>样例记录</h4>
              <span class="ldidp-card-tag">共 ${(detail.samples || []).length} 条展示</span>
            </header>
            <div class="ldidp-table-wrap">
              <table class="ldidp-table">
                <thead>
                  <tr><th>材料名称</th><th>化学式</th><th>来源</th><th>采集性质</th><th>后续状态</th></tr>
                </thead>
                <tbody>
                  ${(detail.samples || []).map((row) => `
                    <tr>
                      <td><span class="ldidp-strong">${esc(row.material)}</span></td>
                      <td>${esc(row.formula)}</td>
                      <td>${esc(row.source)}</td>
                      <td>${esc(row.properties)}</td>
                      <td><span class="ldidp-tag ${String(row.status || "").includes("复核") ? "review" : "ready"}">${esc(row.status)}</span></td>
                    </tr>
                  `).join("") || `<tr><td colspan="5" class="ldidp-table-empty">暂无样例数据</td></tr>`}
                </tbody>
              </table>
            </div>
          </section>
        `;
      }

      if (tabKey === "files") {
        const files = detail.outputFiles || [];
        const fileMeta = (name) => {
          const ext = String(name).split(".").pop().toLowerCase();
          const map = { json: ["JSON", "结构化原始数据"], csv: ["CSV", "清洗后表格数据"], parquet: ["PARQUET", "列式压缩数据"], pdf: ["PDF", "质检报告"], zip: ["ZIP", "结构文件打包"] };
          return map[ext] || [ext.toUpperCase(), "归档文件"];
        };
        return `
          <div class="ldidp-tab-intro">
            <h3>输出文件</h3>
            <p>任务执行完成后归档的结果文件，可用于后续录入与标准化流程。</p>
          </div>
          <section class="ldidp-card">
            <header class="ldidp-card-head">
              <h4>归档文件清单</h4>
              <span class="ldidp-card-tag">共 ${files.length} 个</span>
            </header>
            <div class="ldidp-table-wrap">
              <table class="ldidp-table">
                <thead><tr><th>文件名称</th><th>类型</th><th>说明</th></tr></thead>
                <tbody>
                  ${files.map((name) => {
                    const [type, desc] = fileMeta(name);
                    return `<tr><td><span class="ldidp-file"><i>▧</i>${esc(name)}</span></td><td><span class="ldidp-tag flat">${esc(type)}</span></td><td>${esc(desc)}</td></tr>`;
                  }).join("") || `<tr><td colspan="3" class="ldidp-table-empty">暂无输出文件</td></tr>`}
                </tbody>
              </table>
            </div>
          </section>
        `;
      }

      // timeline
      return `
        <div class="ldidp-tab-intro">
          <h3>执行记录</h3>
          <p>任务从创建到结果归档的完整执行过程。</p>
        </div>
        <section class="ldidp-card">
          <header class="ldidp-card-head"><h4>执行过程</h4></header>
          <ol class="ldidp-timeline">
            ${(detail.timeline || []).map((item, index) => {
              const [head, ...rest] = String(item).split("：");
              return `<li><span class="ldidp-timeline-dot" aria-hidden="true">${index + 1}</span><div><strong>${esc(head)}</strong>${rest.length ? `<p>${esc(rest.join("："))}</p>` : ""}</div></li>`;
            }).join("") || `<li class="is-empty">暂无执行记录</li>`}
          </ol>
        </section>
      `;
    }

    /* ── 机器学习力场：结构样例数据标签页 ─────────────────────────────────────
       三类结构（分子结构 / 小体系结构 / 大体系结构）为「或」关系，
       本函数只渲染该任务实际所属的那一类，字段与 Excel 表头一一对应。 */
    const MLFF_STRUCTURE_CHART_METRICS = {
      molecule: [
        { key: "原子数", label: "原子数", unit: "个" },
        { key: "单分子能量(eV)", label: "单分子能量", unit: "eV" },
        { key: "偶极矩(Debye)", label: "偶极矩", unit: "Debye" },
        { key: "极化率(Å³)", label: "极化率", unit: "Å³" },
        { key: "色散系数", label: "色散系数", unit: "a.u." }
      ],
      small: [
        { key: "原子数", label: "原子数", unit: "个" },
        { key: "能量(eV/atom)", label: "能量", unit: "eV/atom" },
        { key: "力(eV/Å)", label: "力", unit: "eV/Å" },
        { key: "应力(kBar)", label: "应力", unit: "kBar" },
        { key: "带隙(eV)", label: "带隙", unit: "eV" }
      ],
      large: [
        { key: "原子数", label: "原子数", unit: "个" },
        { key: "能量(eV/atom)", label: "能量", unit: "eV/atom" },
        { key: "力(eV/Å)", label: "力", unit: "eV/Å" },
        { key: "应力(kBar)", label: "应力", unit: "kBar" },
        { key: "带隙(eV)", label: "带隙", unit: "eV" }
      ]
    };

    /* 数值型字段识别：能 parseFloat 的才算，用于统计卡与图表 */
    function mlffToNumber(value) {
      const n = parseFloat(String(value == null ? "" : value).replace(/[^0-9eE+\-.]/g, ""));
      return Number.isFinite(n) ? n : null;
    }

    /* 迷你折线/柱状 SVG 图（不引外部图表库，纯内联 SVG） */
    function renderMlffSparkChart(records, metric, tone) {
      const values = records.map((r) => mlffToNumber(r[metric.key])).filter((v) => v !== null);
      if (!values.length) {
        return `<div class="mlff-chart-empty">该指标暂无可用数值</div>`;
      }
      const w = 260, h = 76, padY = 8;
      const min = Math.min.apply(null, values);
      const max = Math.max.apply(null, values);
      const span = max - min || 1;
      const stepX = values.length > 1 ? (w - 16) / (values.length - 1) : 0;
      const pts = values.map((v, i) => {
        const x = 8 + i * stepX;
        const y = h - padY - ((v - min) / span) * (h - padY * 2);
        return [x, y];
      });
      const line = pts.map((p) => `${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
      const area = `8,${h - padY} ${line} ${(8 + (values.length - 1) * stepX).toFixed(1)},${h - padY}`;
      const dots = pts.map((p) => `<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="2.6" fill="var(--mlff-chart-${tone}, #0070F0)"/>`).join("");
      return `
        <div class="mlff-chart">
          <svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img"
            aria-label="${escapeLowDimHtml(metric.label)}趋势图">
            <polygon points="${area}" fill="var(--mlff-chart-${tone}-fill, rgba(0,112,240,.10))"/>
            <polyline points="${line}" fill="none" stroke="var(--mlff-chart-${tone}, #0070F0)"
              stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>
            ${dots}
          </svg>
          <div class="mlff-chart-foot">
            <span>最小 <strong>${escapeLowDimHtml(String(min))}</strong> ${escapeLowDimHtml(metric.unit)}</span>
            <span>最大 <strong>${escapeLowDimHtml(String(max))}</strong> ${escapeLowDimHtml(metric.unit)}</span>
          </div>
        </div>`;
    }

    /* 分布柱状图（按数值分 5 个区间） */
    function renderMlffDistributionChart(records, metric, tone) {
      const values = records.map((r) => mlffToNumber(r[metric.key])).filter((v) => v !== null);
      if (values.length < 2) return `<div class="mlff-chart-empty">样本量不足，暂不绘制分布</div>`;
      const min = Math.min.apply(null, values);
      const max = Math.max.apply(null, values);
      const bins = 5;
      const span = max - min || 1;
      const buckets = new Array(bins).fill(0);
      values.forEach((v) => {
        let idx = Math.floor(((v - min) / span) * bins);
        if (idx >= bins) idx = bins - 1;
        if (idx < 0) idx = 0;
        buckets[idx] += 1;
      });
      const peak = Math.max.apply(null, buckets) || 1;
      const bars = buckets.map((count, i) => {
        const pct = Math.round((count / peak) * 100);
        const lo = min + (span / bins) * i;
        const hi = min + (span / bins) * (i + 1);
        return `
          <div class="mlff-dist-bar">
            <div class="mlff-dist-track"><i style="height:${Math.max(4, pct)}%"></i></div>
            <div class="mlff-dist-meta">
              <strong>${count}</strong>
              <span>${escapeLowDimHtml(lo.toFixed(2))} ~ ${escapeLowDimHtml(hi.toFixed(2))}</span>
            </div>
          </div>`;
      }).join("");
      return `<div class="mlff-dist" data-tone="${escapeLowDimHtml(tone)}">${bars}</div>`;
    }

    /* 主渲染：结构样例数据标签页完整内容 */
    function renderMlffStructureTab(data, task, detail) {
      const esc = escapeLowDimHtml;
      const meta = data.meta;
      const records = data.records || [];
      const fields = data.fields || [];
      const tone = data.structure === "molecule" ? "molecule" : (data.structure === "small" ? "small" : "large");

      /* 关键指标统计：按结构类型挑字段，缺列则不显示（避免张冠李戴） */
      const numericFields = fields.filter((f) => records.some((r) => mlffToNumber(r[f]) !== null));
      const STAT_SPEC = {
        molecule: [
          { label: "样例记录", field: null, unit: "条" },
          { label: "原子数范围", field: "原子数", unit: "个" },
          { label: "单分子能量范围", field: "单分子能量(eV)", unit: "eV" },
          { label: "偶极矩范围", field: "偶极矩(Debye)", unit: "Debye" }
        ],
        small: [
          { label: "样例记录", field: null, unit: "条" },
          { label: "原子数范围", field: "原子数", unit: "个" },
          { label: "能量范围", field: "能量(eV/atom)", unit: "eV/atom" },
          { label: "带隙范围", field: "带隙(eV)", unit: "eV" }
        ],
        large: [
          { label: "样例记录", field: null, unit: "条" },
          { label: "原子数范围", field: "原子数", unit: "个" },
          { label: "能量范围", field: "能量(eV/atom)", unit: "eV/atom" },
          { label: "带隙范围", field: "带隙(eV)", unit: "eV" }
        ]
      };
      const statSpec = (STAT_SPEC[data.structure] || STAT_SPEC.small)
        .filter((spec) => spec.field === null || numericFields.indexOf(spec.field) >= 0);
      const statValue = (spec) => {
        if (!spec.field) return esc(String(records.length));
        const vs = records.map((r) => mlffToNumber(r[spec.field])).filter((v) => v !== null);
        if (!vs.length) return "-";
        const lo = Math.min.apply(null, vs);
        const hi = Math.max.apply(null, vs);
        return lo === hi ? String(lo) : `${lo} ~ ${hi}`;
      };
      const stats = statSpec.map((spec) => `
        <article class="ldidp-stat-card mlff-stat-card${spec.field ? "" : " is-primary"}">
          <span>${esc(spec.label)}</span>
          <strong>${esc(statValue(spec))}<em>${esc(spec.unit)}</em></strong>
        </article>`).join("");

      /* 图表度量：最多取 3 个数值指标 */
      const chartMetrics = (MLFF_STRUCTURE_CHART_METRICS[data.structure] || [])
        .filter((m) => numericFields.indexOf(m.key) >= 0)
        .slice(0, 3);
      const chartBlocks = chartMetrics.map((m, i) => `
        <section class="mlff-chart-card">
          <header class="mlff-chart-head">
            <h4>${esc(m.label)}分布</h4>
            <span class="mlff-chart-unit">${esc(m.unit)}</span>
          </header>
          ${i === 0
            ? renderMlffSparkChart(records, m, tone)
            : renderMlffDistributionChart(records, m, tone)}
        </section>`).join("");

      /* 数据表：列名完全按 Excel 表头 */
      const shortField = (f) => String(f)
        .replace("material_id", "材料ID")
        .replace("formula", "分子式")
        .replace("体系名称", "体系名称");
      const numericCols = ["原子数", "分子数", "电荷", "自旋多重度", "单分子能量(eV)", "偶极矩(Debye)", "极化率(Å³)", "色散系数", "能量(eV/atom)", "力(eV/Å)", "应力(kBar)", "磁矩(μB)", "带隙(eV)"];
      const rowsHtml = records.map((r, index) => `
        <tr>
          ${fields.map((f) => {
            const raw = r[f] == null ? "" : String(r[f]);
            const isNum = numericCols.indexOf(f) >= 0;
            const isMark = raw === "✓";
            const cls = isNum ? "mlff-cell-num" : (isMark ? "mlff-cell-mark" : "");
            const content = isMark
              ? `<span class="mlff-check" title="已记录">✓</span>`
              : esc(raw);
            return `<td class="${cls}" title="${esc(raw)}">${content}</td>`;
          }).join("")}
        </tr>`).join("");

      return `
        <div class="ldidp-tab-intro">
          <h3>${esc(meta.label)}</h3>
          <p>${esc(meta.desc)}</p>
        </div>

        <section class="ldidp-card mlff-struct-banner">
          <div class="mlff-struct-banner-main">
            <span class="mlff-struct-tag">${esc(meta.enLabel)}</span>
            <h4>本任务所属结构类型：${esc(meta.label)}</h4>
            <p>分子结构、小体系结构与大体系结构三者互斥（或关系），同一采集任务只归入其中一类，因此本页不展示另外两类结构的样例数据。</p>
          </div>
          <dl class="mlff-struct-facts">
            <div><dt>数据来源</dt><dd>${esc(data.source || "-")}</dd></div>
            <div><dt>字段数量</dt><dd>${fields.length} 列</dd></div>
            <div><dt>本任务样例</dt><dd>第 ${data.offset + 1} - ${data.offset + records.length} 条 / 共 ${data.total} 条</dd></div>
          </dl>
        </section>

        <div class="ldidp-stat-grid mlff-stat-grid">${stats}</div>

        ${chartBlocks ? `<div class="mlff-chart-grid">${chartBlocks}</div>` : ""}

        <section class="ldidp-card">
          <header class="ldidp-card-head">
            <h4>${esc(meta.label)}样例记录</h4>
            <span class="ldidp-card-tag">共 ${records.length} 条</span>
          </header>
          <div class="ldidp-table-wrap mlff-table-wrap">
            <table class="ldidp-table mlff-table">
              <thead>
                <tr>${fields.map((f) => `<th>${esc(shortField(f))}</th>`).join("")}</tr>
              </thead>
              <tbody>
                ${rowsHtml || `<tr><td colspan="${fields.length}" class="ldidp-table-empty">暂无样例数据</td></tr>`}
              </tbody>
            </table>
          </div>
        </section>`;
    }

    function renderLowdimIngestDetailPage() {
      const page = document.getElementById("page-lowdim-ingest-detail");
      if (!page) return;
      const detailState = getLowdimIngestDetailState();
      const pageId = detailState.pageId || "lowdim-ingest-twod";
      const material = getLowdimMaterialConfig(pageId);
      const task = getTwodIngestCollectionTasks(pageId).find((item) => item.id === detailState.taskId);

      if (!task) {
        page.innerHTML = `
          <div class="ldidp-shell">
            <header class="ldidp-head">
              <div class="ldidp-head-main">
                <h2>采集任务详情</h2>
                <p>未找到对应的采集任务记录</p>
              </div>
              <div class="ldidp-head-actions">
                <button class="btn" type="button" data-ldidp-back>返回</button>
              </div>
            </header>
            <div class="ldidp-empty">该任务记录不存在或已被移除，请返回列表页重新选择。</div>
          </div>`;
        return;
      }

      const taskDetail = getTwodIngestTaskDetail(task);
      const detailTabs = getLowdimIngestDetailTabs(task, pageId);
      const tab = detailTabs.some((item) => item.key === detailState.tab) ? detailState.tab : "overview";
      detailState.tab = tab;

      const titleEl = document.getElementById("ldidpTitle");
      const subtitleEl = document.getElementById("ldidpSubtitle");
      const crumbPageEl = document.getElementById("ldidpCrumbPage");
      const crumbCurrentEl = document.getElementById("ldidpCrumbCurrent");
      if (titleEl) titleEl.textContent = `${task.id} 采集任务详情`;
      if (subtitleEl) subtitleEl.textContent = `${task.method} · ${task.status} · 创建人：${task.creator}`;
      if (crumbPageEl) crumbPageEl.textContent = material.ingestTitle;
      if (crumbCurrentEl) crumbCurrentEl.textContent = `${task.id} 采集任务详情`;

      const summaryEl = document.getElementById("ldidpSummary");
      if (summaryEl) summaryEl.innerHTML = renderLowdimIngestDetailSummary(task, taskDetail, material);
      const tabsEl = document.getElementById("ldidpTabs");
      if (tabsEl) tabsEl.innerHTML = renderLowdimIngestDetailTabs(tab, detailTabs);
      const bodyEl = document.getElementById("ldidpBody");
      if (bodyEl) bodyEl.innerHTML = renderLowdimIngestDetailTabContent(tab, task, taskDetail, material, pageId);
    }

    function switchLowdimIngestDetailTab(tabKey) {
      const detailState = getLowdimIngestDetailState();
      if (!LOWDIM_INGEST_DETAIL_TABS.some((item) => item.key === tabKey)) return;
      detailState.tab = tabKey;
      renderLowdimIngestDetailPage();
      const nav = document.querySelector('[data-ldidp-tab="' + tabKey + '"]');
      if (nav && typeof nav.scrollIntoView === "function") {
        nav.scrollIntoView({ block: "nearest", inline: "nearest" });
      }
    }

    function backFromLowdimIngestDetail() {
      const detailState = getLowdimIngestDetailState();
      const target = detailState.pageId || "lowdim-ingest-twod";
      state.page = target;
      if (typeof switchPage === "function") switchPage(target);
      if (typeof renderPageLayout === "function") renderPageLayout();
      if (typeof renderLowdimIngestPage === "function") renderLowdimIngestPage(target);
      const page = document.getElementById(`page-${target}`);
      if (page) page.classList.add("active");
      document.querySelectorAll(".page").forEach((node) => {
        if (node !== page) node.classList.remove("active");
      });
      const nav = document.querySelector(`.sidebar .nav-btn[data-page="${target}"]`);
      if (nav) {
        document.querySelectorAll(".nav-btn").forEach((node) => node.classList.remove("active"));
        nav.classList.add("active");
      }
      try { window.scrollTo(0, 0); } catch (error) {}
    }
    /* ===== 向导草稿暂存 =====
       点「保存内容」后需要返回列表页，但向导已填内容不能丢。
       做法：把向导对象从 state.lowdimIngestWizards 挪到 state.twodWizardDrafts 暂存，
       列表页因此看不到向导；再点「创建任务」时优先恢复暂存的草稿。 */
    function stashTwodWizardDraft(pageId, wizard) {
      if (!state.twodWizardDrafts) state.twodWizardDrafts = {};
      if (wizard) wizard.__pageId = pageId;
      state.twodWizardDrafts[pageId] = wizard || state.lowdimIngestWizards?.[pageId] || null;
      if (state.lowdimIngestWizards) delete state.lowdimIngestWizards[pageId];
    }

    function getTwodWizardDraft(pageId) {
      return state.twodWizardDrafts?.[pageId] || null;
    }

    function clearTwodWizardDraft(pageId) {
      if (state.twodWizardDrafts) delete state.twodWizardDrafts[pageId];
    }

    /* 获取向导状态；若存在暂存草稿则恢复，实现「保存后返回列表、再进入可继续」 */
    function getTwodTaskWizardState(pageId = "lowdim-ingest-twod") {
       const config = getLowdimWizardConfig(pageId);
       if (!state.lowdimIngestWizards) state.lowdimIngestWizards = {};
       if (!state.lowdimIngestWizards[pageId]) {
         const draft = getTwodWizardDraft(pageId);
         if (draft) {
           /* 恢复草稿：继续沿用已填的任务信息、采集参数、录入数据 */
           state.lowdimIngestWizards[pageId] = draft;
           clearTwodWizardDraft(pageId);
           return state.lowdimIngestWizards[pageId];
         }
         state.lowdimIngestWizards[pageId] = {
           __pageId: pageId,
           step: 1,
           step2View: "intro",
           step2IntroOpen: false,
           task: { name: "", id: "", sourceType: "公开数据库采集", description: "", priority: "中", collectionMode: "全量采集" },
           collectParams: { materialType: TWOD_MATERIAL_TYPES[0].name, quantity: "500", naming: "keep" },
           collectState: "idle",
           collectProgress: 0,
           archived: {},
           resources: [],
           entryRows: config.defaultRows.map((row) => Object.assign({}, row)),
           literature: { verified: false, papers: [], rows: [
             { material: config.sampleLabel, object: config.resourceObjects[0]?.name || "资源对象", property: config.properties[0], value: "", unit: "-", conditions: "默认测试条件", source: "文献1" },
             { material: config.sampleLabel, object: config.resourceObjects[1]?.name || "资源对象", property: config.properties[1] || config.properties[0], value: "", unit: "-", conditions: "默认测试条件", source: "文献2" }
           ] }
         };
       }
       return state.lowdimIngestWizards[pageId];
    }

    function getTwodWizardPageId(node) {
      return node?.closest("[data-twod-wizard-page]")?.dataset.twodWizardPage
        || node?.closest(".twod-main-page")?.dataset.twodWizardPage
        || state.page
        || "lowdim-ingest-twod";
    }

