    function renderLowdimProcessingPrototype(pageId) {
      const proc = getLowdimProcessingState(pageId);
      const content = proc.activeTab === "detail" ? renderLowdimProcessingDetail(pageId)
        : proc.activeTab === "versions" ? renderLowdimProcessingVersions(pageId)
        : proc.activeTab === "products" ? renderLowdimProcessingProducts(pageId)
        : renderLowdimProcessingTaskList(pageId);
      return `<div class="lowdim-processing-prototype">${renderLowdimProcessingFlow(pageId)}${renderLowdimStdRuleCallInline(pageId)}${renderLowdimProcessingTabs(proc, pageId)}${content}</div>`;
    }

    function openLowdimProcessingModal(title, bodyHtml, footerHtml = "") {
      const titleEl = document.getElementById("twodIngestGenericRowModalTitle");
      const body = document.getElementById("twodIngestGenericRowModalBody");
      if (titleEl) titleEl.textContent = title;
      if (body) body.innerHTML = bodyHtml;
      setTwodIngestGenericModalFooter(footerHtml || `<button class="btn" type="button" data-close-modal="twodIngestGenericRowModal">关闭</button>`);
      openModal("twodIngestGenericRowModal");
    }

