    function buildTwodIngestResourceFileFromInput(file) {
      if (!file) return null;
      const ext = String(file.name || "").includes(".") ? file.name.split(".").pop().toUpperCase() : "";
      return {
        name: file.name || "未命名文件",
        sizeText: typeof formatFileSize === "function" ? formatFileSize(file.size || 0) : `${file.size || 0} B`,
        type: file.type || ext || "未知类型",
        uploadedAt: new Date().toLocaleString("zh-CN", { hour12: false })
      };
    }

    function renderTwodIngestResourceFileSummary(fileMeta) {
      if (!fileMeta?.name) {
        return `<strong>未选择文件</strong><small>支持结构文件、表格、图谱、文档、压缩包等资源附件。</small>`;
      }
      return `<strong>${escapeLowDimHtml(fileMeta.name)}</strong><small>${escapeLowDimHtml(fileMeta.sizeText || "大小未知")} · ${escapeLowDimHtml(fileMeta.type || "文件")} ${fileMeta.uploadedAt ? `· ${escapeLowDimHtml(fileMeta.uploadedAt)}` : ""}</small>`;
    }

    function renderTwodIngestResourceFileCell(fileMeta) {
      if (!fileMeta?.name) return `<span class="twod-ingest-file-empty">未上传</span>`;
      return `<span class="twod-ingest-file-pill" title="${escapeLowDimHtml(fileMeta.name)}">${escapeLowDimHtml(fileMeta.name)}</span>`;
    }

