    function getLowdimIngestActiveTab(page) {
      if (!state.lowdimIngestTabs) state.lowdimIngestTabs = {};
      const key = state.lowdimIngestTabs[page] || (getLowdimMaterialKey(page) === "twod" ? "collection" : "objects");
      return LOWDIM_INGEST_TABS.some((item) => item.key === key) ? key : "objects";
    }

    function sanitizeTwodIngestRichText(html) {
      const template = document.createElement("template");
      template.innerHTML = html || "";
      const allowedTags = new Set(["B", "STRONG", "I", "EM", "U", "UL", "OL", "LI", "BR", "P", "DIV"]);
      const clean = (node) => {
        Array.from(node.childNodes).forEach((child) => {
          if (child.nodeType === Node.TEXT_NODE) return;
          if (child.nodeType !== Node.ELEMENT_NODE) {
            child.remove();
            return;
          }
          clean(child);
          if (!allowedTags.has(child.tagName)) {
            child.replaceWith(...Array.from(child.childNodes));
            return;
          }
          Array.from(child.attributes).forEach((attr) => child.removeAttribute(attr.name));
        });
      };
      clean(template.content);
      return template.innerHTML.trim();
    }

    function getTwodIngestRichTextLength(html) {
      const box = document.createElement("div");
      box.innerHTML = html || "";
      return (box.textContent || "").trim().length;
    }

    function updateTwodIngestRichCount() {
      const editor = document.querySelector("[data-twod-ingest-resource-description]");
      const counter = document.getElementById("twodIngestResourceDescCount");
      if (!editor || !counter) return;
      const length = (editor.textContent || "").trim().length;
      counter.textContent = `${length} / 500`;
      counter.style.color = length > 500 ? "#ef4444" : "#64748b";
    }

    function openTwodIngestResourceObjectModal(mode, recordId = "") {
      const rows = getTwodIngestResourceObjects();
      const record = mode === "edit" ? rows.find((item) => item.id === recordId) : null;
      state.twodIngestResourceEditing = { mode, recordId };
      const title = document.getElementById("twodIngestResourceObjectModalTitle");
      const body = document.getElementById("twodIngestResourceObjectModalBody");
      if (title) title.textContent = mode === "edit" ? "编辑资源对象" : "新增资源对象";
      if (body) {
        body.innerHTML = `
          <div class="twod-resource-form-grid">
            <label class="field">
              <span>数据资源 <small>30字以内</small></span>
              <input id="twodIngestResourceName" type="text" maxlength="30" value="${escapeLowDimHtml(record?.resource || "")}" placeholder="请输入数据资源">
            </label>
            <label class="field">
              <span>基本字段</span>
              <input id="twodIngestResourceBasicFields" type="text" value="${escapeLowDimHtml(record?.basicFields || "")}" placeholder="请输入基本字段">
            </label>
            <label class="field">
              <span>存储展示方式</span>
              <textarea id="twodIngestResourceStorage" rows="3" placeholder="请输入存储展示方式">${escapeLowDimHtml(record?.storageDisplay || "")}</textarea>
            </label>
            <div class="field">
              <span>说明 <small id="twodIngestResourceDescCount" class="twod-ingest-rich-count">0 / 500</small></span>
              <div class="twod-ingest-rich-toolbar" aria-label="说明富文本工具">
                <button type="button" data-twod-ingest-rich-command="bold">B</button>
                <button type="button" data-twod-ingest-rich-command="italic">I</button>
                <button type="button" data-twod-ingest-rich-command="underline">U</button>
                <button type="button" data-twod-ingest-rich-command="insertUnorderedList">列表</button>
              </div>
              <div class="twod-ingest-rich-editor" contenteditable="true" role="textbox" aria-multiline="true" data-twod-ingest-resource-description>${sanitizeTwodIngestRichText(record?.descriptionHtml || "")}</div>
            </div>
            <div class="field">
              <span>上传文件</span>
              <div class="twod-ingest-upload-row">
                <label class="twod-ingest-upload-control">
                  <input type="file" data-twod-ingest-resource-file-input>
                  <span>选择文件</span>
                </label>
                <div class="twod-ingest-upload-summary" data-twod-ingest-resource-file-summary>
                  ${renderTwodIngestResourceFileSummary(record?.fileMeta || null)}
                </div>
              </div>
            </div>
          </div>
        `;
      }
      openModal("twodIngestResourceObjectModal");
      updateTwodIngestRichCount();
    }

    function saveTwodIngestResourceObject() {
      const editing = state.twodIngestResourceEditing || { mode: "add" };
      const resource = (document.getElementById("twodIngestResourceName")?.value || "").trim();
      const basicFields = (document.getElementById("twodIngestResourceBasicFields")?.value || "").trim();
      const storageDisplay = (document.getElementById("twodIngestResourceStorage")?.value || "").trim();
      const editor = document.querySelector("[data-twod-ingest-resource-description]");
      const descriptionHtml = sanitizeTwodIngestRichText(editor?.innerHTML || "");
      const descriptionLength = getTwodIngestRichTextLength(descriptionHtml);
      if (!resource || !basicFields || !storageDisplay) {
        showToast("资源对象校验", "请填写数据资源、基本字段和存储展示方式。");
        return;
      }
      if (resource.length > 30) {
        showToast("资源对象校验", "数据资源需控制在 30 字以内。");
        return;
      }
      if (descriptionLength > 500) {
        showToast("资源对象校验", "说明需控制在 500 字以内。");
        return;
      }
      const rows = getTwodIngestResourceObjects();
      const existing = editing.mode === "edit" ? rows.find((item) => item.id === editing.recordId) : null;
      const fileInput = document.querySelector("[data-twod-ingest-resource-file-input]");
      const fileMeta = fileInput?.files?.[0] ? buildTwodIngestResourceFileFromInput(fileInput.files[0]) : (existing?.fileMeta || null);
      const draft = { resource, basicFields, storageDisplay, descriptionHtml, fileMeta };
      if (editing.mode === "edit") {
        const index = rows.findIndex((item) => item.id === editing.recordId);
        if (index >= 0) rows[index] = Object.assign({}, rows[index], draft);
      } else {
        rows.push(Object.assign({ id: `twod-resource-${Date.now()}` }, draft));
      }
      closeModal("twodIngestResourceObjectModal");
      renderLowdimIngestPage("lowdim-ingest-twod");
      showToast("资源对象", editing.mode === "edit" ? "资源对象已更新。" : "资源对象已新增。");
    }

    function deleteTwodIngestResourceObject(recordId) {
      const rows = getTwodIngestResourceObjects();
      const record = rows.find((item) => item.id === recordId);
      if (!record) return;
      if (!window.confirm(`确认删除「${record.resource}」吗？`)) return;
      state.twodIngestResourceObjects = rows.filter((item) => item.id !== recordId);
      renderLowdimIngestPage("lowdim-ingest-twod");
      showToast("资源对象", "资源对象已删除。");
    }

    function openTwodIngestGenericRowModal(pageId, tabKey) {
      const material = getLowdimMaterialConfig(pageId);
      const table = getLowdimIngestRows(tabKey, material);
      const tabMeta = LOWDIM_INGEST_TABS.find((item) => item.key === tabKey) || LOWDIM_INGEST_TABS[0];
      state.twodIngestGenericEditing = { pageId, tabKey };
      const title = document.getElementById("twodIngestGenericRowModalTitle");
      const body = document.getElementById("twodIngestGenericRowModalBody");
      if (title) title.textContent = `${getTwodIngestGenericAddLabel(tabKey)} - ${tabMeta.label}`;
      setTwodIngestGenericModalFooter(`
        <button class="btn" type="button" data-close-modal="twodIngestGenericRowModal">取消</button>
        <button class="btn-primary" type="button" data-twod-ingest-generic-save>保存</button>
      `);
      if (body) {
        body.innerHTML = `
          <div class="twod-resource-form-grid">
            ${table.columns.map((column, index) => `
              <label class="field">
                <span>${escapeLowDimHtml(column)}</span>
                ${index >= 2
                  ? `<textarea rows="3" data-twod-ingest-generic-field="${index}" placeholder="请输入${escapeLowDimHtml(column)}"></textarea>`
                  : `<input type="text" data-twod-ingest-generic-field="${index}" placeholder="请输入${escapeLowDimHtml(column)}">`}
              </label>
            `).join("")}
          </div>
        `;
      }
      openModal("twodIngestGenericRowModal");
    }

    function saveTwodIngestGenericRow() {
      const editing = state.twodIngestGenericEditing || {};
      const pageId = editing.pageId || "lowdim-ingest-twod";
      const tabKey = editing.tabKey || getLowdimIngestActiveTab(pageId);
      const material = getLowdimMaterialConfig(pageId);
      const table = getLowdimIngestRows(tabKey, material);
      const row = table.columns.map((_, index) => (document.querySelector(`[data-twod-ingest-generic-field="${index}"]`)?.value || "").trim());
      const missingIndex = row.findIndex((value) => !value);
      if (missingIndex >= 0) {
        showToast("新增配置校验", `请填写${table.columns[missingIndex]}。`);
        return;
      }
      getTwodIngestGenericRowsStore(pageId, tabKey).push(row);
      closeModal("twodIngestGenericRowModal");
      renderLowdimIngestPage(pageId);
      showToast("新增配置", `${getTwodIngestGenericAddLabel(tabKey)}已保存。`);
    }

