    const TWOD_SECURITY_CHANGE_LOG_DEFAULTS_V2 = [
      { id: "chg-001", materialId: "2D-MAT-00047", oldLevel: "SEC-02", newLevel: "SEC-01", operator: "数据管理员", time: "2026-08-02 15:20", reason: "完成敏感性评估，调整为完全公开。" },
      { id: "chg-002", materialId: "2D-MAT-00021", oldLevel: "未定级", newLevel: "SEC-02", operator: "系统自动", time: "2026-08-01 08:30", reason: "source_type=calculation，入库未满6个月。" }
    ];

    function getTwodSecurityState() {
      if (!state.twodSecurity) state.twodSecurity = {};
      const security = state.twodSecurity;
      if (!security.v2Ready) {
        security.activeTab = security.activeTab || "classification";
        security.reviewStatusFilter = security.reviewStatusFilter || "全部";
        security.authReviewStatusFilter = security.authReviewStatusFilter || "全部";
        security.expiryFilter = security.expiryFilter || "全部";
        security.levelDefinitions = security.levelDefinitions || TWOD_SECURITY_LEVEL_DEFINITIONS_V2.map((item) => Object.assign({}, item));
        security.classificationTasks = security.classificationTasks || TWOD_SECURITY_CLASSIFICATION_DEFAULTS_V2.map((item) => Object.assign({}, item));
        security.evaluationRules = security.evaluationRules || TWOD_SECURITY_EVALUATION_RULE_DEFAULTS_V2.map((item) => Object.assign({}, item));
        security.authApplicationsV2 = security.authApplicationsV2 || TWOD_SECURITY_AUTH_APPLICATION_DEFAULTS_V2.map((item) => Object.assign({}, item));
        security.authorizedUsersV2 = security.authorizedUsersV2 || TWOD_SECURITY_AUTHORIZED_USER_DEFAULTS_V2.map((item) => Object.assign({}, item));
        security.renewalApplications = security.renewalApplications || TWOD_SECURITY_RENEWAL_APPLICATION_DEFAULTS_V2.map((item) => Object.assign({}, item));
        security.changeLogsV2 = security.changeLogsV2 || TWOD_SECURITY_CHANGE_LOG_DEFAULTS_V2.map((item) => Object.assign({}, item));
        security.v2Ready = true;
      }
      security.authorizedUsersV2.forEach((user) => {
        const days = twodSecurityDaysUntil(user.authorizedTo);
        if (days < 0) user.status = "已过期";
        else if (days <= 7) user.status = "即将到期";
        else if (user.status !== "已撤销" && user.status !== "已降级") user.status = "有效";
      });
      return security;
    }

    function twodSecurityDaysUntil(dateString) {
      return twodSecurityDaysBetween(TWOD_SECURITY_TODAY, dateString);
    }

    function twodSecurityLevelDefinition(code) {
      const security = getTwodSecurityState();
      return security.levelDefinitions.find((item) => item.code === code) || TWOD_SECURITY_LEVEL_DEFINITIONS_V2[0];
    }

    function renderTwodSecurityLevelBadge(levelCode) {
      const definition = twodSecurityLevelDefinition(levelCode);
      const className = levelCode === "SEC-02" ? "level-2" : "level-1";
      return `<span class="twod-security-level-badge ${className}">${escapeLowDimHtml(definition.levelText || definition.title)}</span>`;
    }

    function renderTwodSecurityStatusBadge(status) {
      const value = escapeLowDimHtml(status || "-");
      const cls = status === "待审核" || status === "未发送" ? "pending" : status === "已驳回" || status === "已过期" || status === "已撤销" || status === "已降级" ? "danger" : status === "即将到期" || status === "已调整" ? "warn" : "normal";
      return `<span class="twod-security-status ${cls}">${value}</span>`;
    }

    function renderTwodSecurityStyle() {
      return `
        <style>
          #page-lowdim-ingest-twod .twod-security-page-v2{display:grid;gap:16px;}
          #page-lowdim-ingest-twod .twod-security-titlebar{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:18px;border:1px solid #dbe3ef;background:linear-gradient(180deg,#fff,#f8fbff);}
          #page-lowdim-ingest-twod .twod-security-titlebar h2{margin:0;color:#0f172a;font-size:22px;line-height:1.2;}
          #page-lowdim-ingest-twod .twod-security-titlebar p{margin:7px 0 0;color:#64748b;font-size:13px;line-height:20px;}
          #page-lowdim-ingest-twod .twod-security-stat-row{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;}
          #page-lowdim-ingest-twod .twod-security-stat-pill{display:inline-flex;align-items:center;gap:8px;min-height:36px;padding:0 12px;border:1px solid #d8e4f0;background:#fff;color:#334155;font-size:13px;font-weight:800;}
          #page-lowdim-ingest-twod .twod-security-stat-pill.level-1{border-color:#bbf7d0;background:#f0fdf4;color:#166534;}
          #page-lowdim-ingest-twod .twod-security-stat-pill.level-2{border-color:#fed7aa;background:#fff7ed;color:#9a3412;}
          #page-lowdim-ingest-twod .twod-security-shell{display:grid;grid-template-columns:190px minmax(0,1fr);gap:16px;align-items:start;}
          #page-lowdim-ingest-twod .twod-security-tabs-v2{display:grid;gap:8px;position:sticky;top:12px;}
          #page-lowdim-ingest-twod .twod-security-tab-v2{min-height:44px;border:1px solid #dbe3ef;background:#fff;color:#334155;text-align:left;padding:0 13px;font-size:14px;font-weight:800;cursor:pointer;}
          #page-lowdim-ingest-twod .twod-security-tab-v2.active{border-color:#1f63ff;background:#eaf2ff;color:#1f63ff;box-shadow:inset 3px 0 0 #1f63ff;}
          #page-lowdim-ingest-twod .twod-security-content{display:grid;gap:16px;min-width:0;}
          #page-lowdim-ingest-twod .twod-security-panel{border:1px solid #dbe3ef;background:#fff;}
          #page-lowdim-ingest-twod .twod-security-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:14px 16px;border-bottom:1px solid #E5E6EB;background:#fbfdff;}
          #page-lowdim-ingest-twod .twod-security-panel-head h3{margin:0;color:#0f172a;font-size:16px;}
          #page-lowdim-ingest-twod .twod-security-panel-body{padding:14px 16px;}
          #page-lowdim-ingest-twod .twod-security-toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
          #page-lowdim-ingest-twod .twod-security-toolbar select,#page-lowdim-ingest-twod .twod-security-toolbar input{min-height:36px;border:1px solid #cfd8e6;background:#fff;color:#172033;padding:6px 10px;}
          #page-lowdim-ingest-twod .twod-security-table-wrap{overflow:auto;}
          #page-lowdim-ingest-twod .twod-security-table{width:100%;min-width:980px;border-collapse:collapse;table-layout:fixed;}
          #page-lowdim-ingest-twod .twod-security-table th,#page-lowdim-ingest-twod .twod-security-table td{padding:10px 12px;border-bottom:1px solid #edf2f7;color:#111827;font-size:13px;line-height:20px;text-align:left;vertical-align:top;overflow-wrap:anywhere;}
          #page-lowdim-ingest-twod .twod-security-table th{background:#eef3fb;color:#0f2377;font-weight:800;}
          #page-lowdim-ingest-twod .twod-security-cell{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
          #page-lowdim-ingest-twod .twod-security-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
          #page-lowdim-ingest-twod .twod-security-level-badge,#page-lowdim-ingest-twod .twod-security-status{display:inline-flex;align-items:center;min-height:24px;padding:2px 8px;border-radius:999px;font-size:12px;font-weight:800;white-space:nowrap;}
          #page-lowdim-ingest-twod .twod-security-level-badge.level-1{background:#dcfce7;color:#166534;}
          #page-lowdim-ingest-twod .twod-security-level-badge.level-2{background:#ffedd5;color:#9a3412;}
          #page-lowdim-ingest-twod .twod-security-status.normal{background:#dcfce7;color:#166534;}
          #page-lowdim-ingest-twod .twod-security-status.pending{background:#fef3c7;color:#92400e;}
          #page-lowdim-ingest-twod .twod-security-status.warn{background:#ffedd5;color:#9a3412;}
          #page-lowdim-ingest-twod .twod-security-status.danger{background:#fee2e2;color:#b91c1c;}
          #page-lowdim-ingest-twod .twod-security-muted{color:#64748b;font-size:13px;line-height:20px;}
          #page-lowdim-ingest-twod .twod-security-flow-grid{display:grid;grid-template-columns:minmax(270px,340px) minmax(0,1fr);gap:16px;}
          #page-lowdim-ingest-twod .twod-security-vertical-flow{position:relative;display:grid;gap:12px;padding-left:18px;}
          #page-lowdim-ingest-twod .twod-security-vertical-flow::before{content:"";position:absolute;left:34px;top:26px;bottom:26px;width:2px;background:linear-gradient(#22c55e,#f59e0b);}
          #page-lowdim-ingest-twod .twod-security-flow-node{position:relative;display:grid;grid-template-columns:32px 1fr;gap:10px;padding:12px;border:1px solid #dbe3ef;background:#fff;z-index:1;}
          #page-lowdim-ingest-twod .twod-security-flow-index{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#eaf2ff;color:#1f63ff;font-weight:900;}
          #page-lowdim-ingest-twod .twod-security-flow-node.current{border-color:#f59e0b;box-shadow:0 0 0 3px rgba(245,158,11,.12);}
          #page-lowdim-ingest-twod .twod-security-flow-node.current .twod-security-flow-index{background:#fff7ed;color:#9a3412;animation:twodSecPulse 1.5s ease-out infinite;}
          #page-lowdim-ingest-twod .twod-security-flow-node strong{display:block;color:#0f172a;font-size:13px;}
          #page-lowdim-ingest-twod .twod-security-flow-node span{display:block;margin-top:3px;color:#64748b;font-size:12px;line-height:18px;}
          #page-lowdim-ingest-twod .twod-security-level-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
          #page-lowdim-ingest-twod .twod-security-definition-card{display:grid;gap:12px;padding:16px;border:1px solid #dbe3ef;background:#fff;}
          #page-lowdim-ingest-twod .twod-security-definition-card.green{border-color:#bbf7d0;background:#f7fef9;}
          #page-lowdim-ingest-twod .twod-security-definition-card.orange{border-color:#fed7aa;background:#fffaf4;}
          #page-lowdim-ingest-twod .twod-security-definition-top{display:flex;align-items:center;justify-content:space-between;gap:10px;}
          #page-lowdim-ingest-twod .twod-security-definition-card h3{margin:0;color:#0f172a;font-size:17px;}
          #page-lowdim-ingest-twod .twod-security-definition-list{display:grid;gap:10px;margin:0;padding:0;list-style:none;}
          #page-lowdim-ingest-twod .twod-security-definition-list li{display:grid;grid-template-columns:108px 1fr;gap:10px;color:#334155;font-size:13px;line-height:20px;}
          #page-lowdim-ingest-twod .twod-security-definition-list b{color:#0f2377;}
          #page-lowdim-ingest-twod .twod-security-rule-list{display:grid;gap:10px;}
          #page-lowdim-ingest-twod .twod-security-rule-item{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;padding:12px;border:1px solid #e2e8f0;background:var(--color-bg-table-head, #f5f5f5);}
          #page-lowdim-ingest-twod .twod-security-expired-row{background:#fff1f2;}
          #page-lowdim-ingest-twod .twod-security-countdown{font-variant-numeric:tabular-nums;animation:twodSecGlow 1.4s ease-in-out infinite;}
          #page-lowdim-ingest-twod .twod-security-renew-flow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
          #page-lowdim-ingest-twod .twod-security-renew-flow span{display:inline-flex;align-items:center;min-height:34px;padding:0 11px;border:1px solid #dbe3ef;background:#fff;color:#334155;font-size:13px;font-weight:800;}
          #page-lowdim-ingest-twod .twod-security-renew-flow i{width:34px;height:2px;background:linear-gradient(90deg,#2563eb,#f59e0b);animation:twodSecLine 1.2s linear infinite;}
          .twod-ingest-security-modal .twod-security-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;}
          .twod-ingest-security-modal .twod-security-form-grid .wide{grid-column:1/-1;}
          .twod-ingest-security-modal .field>span{display:block;margin-bottom:6px;color:#334155;font-size:13px;font-weight:800;}
          .twod-ingest-security-modal .field input,.twod-ingest-security-modal .field select,.twod-ingest-security-modal .field textarea{width:100%;min-height:40px;border:1px solid #cfd8e6;background:#fff;color:#142033;padding:8px 10px;}
          .twod-ingest-security-modal .twod-security-readonly{padding:10px 12px;border:1px solid #e2e8f0;background:var(--color-bg-table-head, #f5f5f5);color:#334155;font-size:13px;line-height:20px;}
          @keyframes twodSecPulse{0%{box-shadow:0 0 0 0 rgba(245,158,11,.38)}70%{box-shadow:0 0 0 8px rgba(245,158,11,0)}100%{box-shadow:0 0 0 0 rgba(245,158,11,0)}}
          @keyframes twodSecGlow{0%,100%{filter:none}50%{filter:brightness(1.08)}}
          @keyframes twodSecLine{0%{background-position:0 0}100%{background-position:34px 0}}
          @media (prefers-reduced-motion:reduce){#page-lowdim-ingest-twod .twod-security-flow-node.current .twod-security-flow-index,#page-lowdim-ingest-twod .twod-security-countdown,#page-lowdim-ingest-twod .twod-security-renew-flow i{animation:none;}}
          @media (max-width:1100px){#page-lowdim-ingest-twod .twod-security-shell,#page-lowdim-ingest-twod .twod-security-flow-grid{grid-template-columns:1fr;}#page-lowdim-ingest-twod .twod-security-tabs-v2{position:static;display:flex;overflow:auto;}#page-lowdim-ingest-twod .twod-security-tab-v2{flex:0 0 auto;min-width:150px;}}
          @media (max-width:760px){#page-lowdim-ingest-twod .twod-security-titlebar,#page-lowdim-ingest-twod .twod-security-panel-head{align-items:stretch;}#page-lowdim-ingest-twod .twod-security-level-cards,.twod-ingest-security-modal .twod-security-form-grid{grid-template-columns:1fr;}#page-lowdim-ingest-twod .twod-security-definition-list li{grid-template-columns:1fr;gap:2px;}}
        </style>
      `;
    }

    function renderTwodSecuritySubTabs(security) {
      return `
        <nav class="twod-security-tabs-v2" role="tablist" aria-label="数据安全等级管理">
          ${TWOD_SECURITY_TABS_V2.map((tab) => `<button class="twod-security-tab-v2 ${security.activeTab === tab.key ? "active" : ""}" type="button" role="tab" aria-selected="${security.activeTab === tab.key ? "true" : "false"}" data-twod-security-tab="${tab.key}">${tab.label}</button>`).join("")}
        </nav>
      `;
    }

    function renderTwodSecurityClassificationFlow(security) {
      const filteredTasks = security.classificationTasks.filter((item) => security.reviewStatusFilter === "全部" || item.reviewStatus === security.reviewStatusFilter);
      const flow = [
        ["系统", "识别数据来源类型", "读取元数据字段 source_type，区分外源/计算数据。"],
        ["系统", "分配初始安全等级", "外源性→第1级完全公开；计算数据→暂定第2级半公开。"],
        ["数据管理员", "审核并确认/调整安全等级", "结合数据时效性与敏感性判断最终等级。"],
        ["系统", "配置访问控制规则", "按安全等级映射下载、预览和授权权限。"]
      ];
      return `
        <div class="twod-security-flow-grid">
          <section class="twod-security-panel">
            <div class="twod-security-panel-head"><h3>定级流程可视化</h3><span class="twod-security-muted">当前步骤：管理员审核</span></div>
            <div class="twod-security-panel-body">
              <div class="twod-security-vertical-flow">
                ${flow.map((item, index) => `
                  <div class="twod-security-flow-node ${index === 2 ? "current" : ""}">
                    <div class="twod-security-flow-index">${index + 1}</div>
                    <div><strong>步骤${index + 1} ${item[0]}：${item[1]}</strong><span>${item[2]}</span></div>
                  </div>
                `).join("")}
              </div>
            </div>
          </section>
          <section class="twod-security-panel">
            <div class="twod-security-panel-head">
              <h3>定级任务列表</h3>
              <div class="twod-security-toolbar">
                <span class="twod-security-muted">审核状态</span>
                <select data-twod-security-review-filter>
                  ${["全部", "待审核", "已确认", "已调整"].map((item) => `<option value="${item}" ${security.reviewStatusFilter === item ? "selected" : ""}>${item}</option>`).join("")}
                </select>
              </div>
            </div>
            <div class="twod-security-table-wrap">
              <table class="twod-security-table">
                <thead><tr><th style="width:130px;">材料ID</th><th style="width:90px;">化学式</th><th style="width:90px;">来源类型</th><th style="width:110px;">入库时间</th><th style="width:130px;">初始安全等级</th><th style="width:100px;">审核状态</th><th style="width:130px;">最终安全等级</th><th style="width:100px;">操作</th></tr></thead>
                <tbody>
                  ${filteredTasks.map((item) => `
                    <tr>
                      <td>${renderTwodSecurityCell(item.materialId)}</td>
                      <td>${renderTwodSecurityCell(item.formula)}</td>
                      <td>${renderTwodSecurityCell(item.sourceType)}</td>
                      <td>${renderTwodSecurityCell(item.storageTime)}</td>
                      <td>${renderTwodSecurityLevelBadge(item.initialLevel)}</td>
                      <td>${renderTwodSecurityStatusBadge(item.reviewStatus)}</td>
                      <td>${renderTwodSecurityLevelBadge(item.finalLevel)}</td>
                      <td><button class="btn btn-sm" type="button" data-twod-security-class-review="${item.id}">${item.reviewStatus === "待审核" ? "审核" : "查看"}</button></td>
                    </tr>
                  `).join("") || `<tr><td colspan="8"><div class="sys-empty">暂无匹配的定级任务</div></td></tr>`}
                </tbody>
              </table>
            </div>
          </section>
        </div>
        <section class="twod-security-panel">
          <div class="twod-security-panel-head"><h3>等级变更日志</h3><span class="twod-security-muted">${security.changeLogsV2.length} 条记录</span></div>
          <div class="twod-security-table-wrap">
            <table class="twod-security-table" style="min-width:820px;">
              <thead><tr><th style="width:140px;">材料ID</th><th style="width:120px;">原等级</th><th style="width:130px;">新等级</th><th style="width:110px;">变更人</th><th style="width:150px;">变更时间</th><th>变更原因</th></tr></thead>
              <tbody>${security.changeLogsV2.map((item) => `<tr><td>${renderTwodSecurityCell(item.materialId)}</td><td>${item.oldLevel === "未定级" ? renderTwodSecurityCell(item.oldLevel) : renderTwodSecurityLevelBadge(item.oldLevel)}</td><td>${renderTwodSecurityLevelBadge(item.newLevel)}</td><td>${renderTwodSecurityCell(item.operator)}</td><td>${renderTwodSecurityCell(item.time)}</td><td>${renderTwodSecurityCell(item.reason)}</td></tr>`).join("")}</tbody>
            </table>
          </div>
        </section>
      `;
    }

    function renderTwodSecurityLevelDefinitions(security) {
      return `
        <section class="twod-security-level-cards">
          ${security.levelDefinitions.map((level) => `
            <article class="twod-security-definition-card ${level.tone}">
              <div class="twod-security-definition-top">
                <h3>${escapeLowDimHtml(level.title)}</h3>
                ${renderTwodSecurityLevelBadge(level.code)}
              </div>
              <ul class="twod-security-definition-list">
                <li><b>数据范围</b><span>${escapeLowDimHtml(level.dataRange)}</span></li>
                <li><b>访问条件</b><span>${escapeLowDimHtml(level.accessCondition)}</span></li>
                <li><b>访问控制规则</b><span>${escapeLowDimHtml(level.accessControl)}</span></li>
              </ul>
              <div><button class="btn btn-sm" type="button" data-twod-security-level-edit="${level.code}">编辑规则</button></div>
            </article>
          `).join("")}
        </section>
        <section class="twod-security-panel">
          <div class="twod-security-panel-head">
            <h3>数据范围评估规则</h3>
            <button class="btn-primary" type="button" data-twod-security-eval-add>新增规则</button>
          </div>
          <div class="twod-security-panel-body">
            <div class="twod-security-rule-list">
              ${security.evaluationRules.map((rule) => `
                <div class="twod-security-rule-item">
                  <div>
                    <strong>${escapeLowDimHtml(rule.title)}</strong>
                    <div class="twod-security-muted">条件：${escapeLowDimHtml(rule.condition)}；动作：${escapeLowDimHtml(rule.action)}</div>
                  </div>
                  <div class="twod-security-actions">
                    ${renderTwodSecurityStatusBadge(rule.enabled ? "已启用" : "已停用")}
                    <button class="btn btn-sm" type="button" data-twod-security-eval-edit="${rule.id}">编辑</button>
                    <button class="btn btn-sm btn-danger-outline" type="button" data-twod-security-eval-delete="${rule.id}">删除</button>
                  </div>
                </div>
              `).join("")}
            </div>
          </div>
        </section>
      `;
    }

    function renderTwodSecurityAuthorizationManagement(security) {
      const applications = security.authApplicationsV2.filter((item) => security.authReviewStatusFilter === "全部" || item.status === security.authReviewStatusFilter);
      return `
        <section class="twod-security-panel">
          <div class="twod-security-panel-head">
            <h3>授权申请列表</h3>
            <div class="twod-security-toolbar">
              <span class="twod-security-muted">审核状态</span>
              <select data-twod-security-auth-filter>${["全部", "待审核", "已批准", "已驳回"].map((item) => `<option value="${item}" ${security.authReviewStatusFilter === item ? "selected" : ""}>${item}</option>`).join("")}</select>
            </div>
          </div>
          <div class="twod-security-table-wrap">
            <table class="twod-security-table" style="min-width:1180px;">
              <thead><tr><th style="width:140px;">申请ID</th><th style="width:90px;">用户ID</th><th style="width:90px;">姓名</th><th style="width:150px;">所在机构</th><th>申请理由</th><th style="width:140px;">申请数据范围</th><th style="width:120px;">预计使用期限</th><th style="width:110px;">申请时间</th><th style="width:100px;">审核状态</th><th style="width:100px;">操作</th></tr></thead>
              <tbody>
                ${applications.map((item) => `
                  <tr>
                    <td>${renderTwodSecurityCell(item.id)}</td><td>${renderTwodSecurityCell(item.userId)}</td><td>${renderTwodSecurityCell(item.name)}</td><td>${renderTwodSecurityCell(item.org)}</td><td>${renderTwodSecurityCell(item.reason)}</td><td>${renderTwodSecurityCell(item.dataRange)}</td><td>${renderTwodSecurityCell(`${item.durationMonths}月`)}</td><td>${renderTwodSecurityCell(item.appliedAt)}</td><td>${renderTwodSecurityStatusBadge(item.status)}</td><td><button class="btn btn-sm" type="button" data-twod-security-auth-review="${item.id}">${item.status === "待审核" ? "审核" : "查看"}</button></td>
                  </tr>
                `).join("") || `<tr><td colspan="10"><div class="sys-empty">暂无匹配申请</div></td></tr>`}
              </tbody>
            </table>
          </div>
        </section>
        <section class="twod-security-panel">
          <div class="twod-security-panel-head"><h3>已授权用户列表</h3><span class="twod-security-muted">${security.authorizedUsersV2.length} 人</span></div>
          <div class="twod-security-table-wrap">
            <table class="twod-security-table" style="min-width:940px;">
              <thead><tr><th style="width:90px;">用户ID</th><th style="width:90px;">姓名</th><th style="width:160px;">机构</th><th>授权数据范围</th><th style="width:120px;">授权到期日</th><th style="width:100px;">状态</th><th style="width:160px;">操作</th></tr></thead>
              <tbody>
                ${security.authorizedUsersV2.map((user) => `
                  <tr class="${user.status === "已过期" ? "twod-security-expired-row" : ""}">
                    <td>${renderTwodSecurityCell(user.userId)}</td><td>${renderTwodSecurityCell(user.name)}</td><td>${renderTwodSecurityCell(user.org)}</td><td>${renderTwodSecurityCell(user.dataRange)}</td><td>${renderTwodSecurityCell(user.authorizedTo)}</td><td>${renderTwodSecurityStatusBadge(user.status)}</td>
                    <td><div class="twod-security-actions"><button class="btn btn-sm btn-danger-outline" type="button" data-twod-security-auth-revoke="${user.userId}">撤销授权</button><button class="btn btn-sm" type="button" data-twod-security-auth-extend="${user.userId}">延期</button></div></td>
                  </tr>
                `).join("")}
              </tbody>
            </table>
          </div>
        </section>
      `;
    }

    function renderTwodSecurityRenewalManagement(security) {
      const reminderRows = security.authorizedUsersV2.filter((user) => {
        const days = twodSecurityDaysUntil(user.authorizedTo);
        if (security.expiryFilter === "已过期") return days < 0;
        if (security.expiryFilter === "7天内到期") return days >= 0 && days <= 7;
        if (security.expiryFilter === "30天内到期") return days >= 0 && days <= 30;
        return days <= 30;
      });
      return `
        <section class="twod-security-panel">
          <div class="twod-security-panel-head">
            <h3>即将到期提醒列表</h3>
            <div class="twod-security-toolbar">
              <span class="twod-security-muted">到期时间</span>
              <select data-twod-security-expiry-filter>${["全部", "7天内到期", "30天内到期", "已过期"].map((item) => `<option value="${item}" ${security.expiryFilter === item ? "selected" : ""}>${item}</option>`).join("")}</select>
            </div>
          </div>
          <div class="twod-security-table-wrap">
            <table class="twod-security-table" style="min-width:960px;">
              <thead><tr><th style="width:90px;">用户ID</th><th style="width:90px;">姓名</th><th style="width:190px;">邮箱</th><th style="width:120px;">授权到期日</th><th style="width:100px;">剩余天数</th><th style="width:130px;">提醒状态</th><th style="width:130px;">操作</th></tr></thead>
              <tbody>
                ${reminderRows.map((user) => {
                  const days = twodSecurityDaysUntil(user.authorizedTo);
                  return `
                    <tr class="${days < 0 ? "twod-security-expired-row" : ""}">
                      <td>${renderTwodSecurityCell(user.userId)}</td><td>${renderTwodSecurityCell(user.name)}</td><td>${renderTwodSecurityCell(user.email)}</td><td>${renderTwodSecurityCell(user.authorizedTo)}</td>
                      <td><span class="twod-security-countdown">${days < 0 ? `已过期${Math.abs(days)}天` : `${days}天`}</span></td>
                      <td>${renderTwodSecurityStatusBadge(user.reminderStatus || "未发送")}</td>
                      <td><button class="btn btn-sm" type="button" data-twod-security-send-reminder="${user.userId}" ${user.reminderStatus === "已发送邮件" ? "disabled" : ""}>发送提醒</button></td>
                    </tr>
                  `;
                }).join("") || `<tr><td colspan="7"><div class="sys-empty">暂无到期提醒</div></td></tr>`}
              </tbody>
            </table>
          </div>
        </section>
        <section class="twod-security-panel">
          <div class="twod-security-panel-head"><h3>续期审核列表</h3><span class="twod-security-muted">批准后更新到期日，驳回后降级为普通用户</span></div>
          <div class="twod-security-table-wrap">
            <table class="twod-security-table" style="min-width:900px;">
              <thead><tr><th style="width:90px;">用户ID</th><th style="width:90px;">姓名</th><th style="width:120px;">原到期日</th><th style="width:130px;">申请延期至</th><th style="width:110px;">申请时间</th><th style="width:100px;">审核状态</th><th style="width:100px;">操作</th></tr></thead>
              <tbody>${security.renewalApplications.map((item) => `<tr><td>${renderTwodSecurityCell(item.userId)}</td><td>${renderTwodSecurityCell(item.name)}</td><td>${renderTwodSecurityCell(item.originalExpiry)}</td><td>${renderTwodSecurityCell(item.requestUntil)}</td><td>${renderTwodSecurityCell(item.appliedAt)}</td><td>${renderTwodSecurityStatusBadge(item.status)}</td><td><button class="btn btn-sm" type="button" data-twod-security-renew-review="${item.id}">${item.status === "待审核" ? "审核" : "查看"}</button></td></tr>`).join("")}</tbody>
            </table>
          </div>
        </section>
        <section class="twod-security-panel">
          <div class="twod-security-panel-head"><h3>续期流程可视化</h3></div>
          <div class="twod-security-panel-body">
            <div class="twod-security-renew-flow"><span>到期前7天自动发送提醒</span><i></i><span>用户登录提交续期申请</span><i></i><span>数据管理员审核</span><i></i><span>批准延期 / 驳回降级</span></div>
          </div>
        </section>
      `;
    }

    function renderTwodSecurityActiveTab(security) {
      if (security.activeTab === "definition") return renderTwodSecurityLevelDefinitions(security);
      if (security.activeTab === "authorization") return renderTwodSecurityAuthorizationManagement(security);
      if (security.activeTab === "renewal") return renderTwodSecurityRenewalManagement(security);
      return renderTwodSecurityClassificationFlow(security);
    }

    function renderTwodSecurityPage(pageId) {
      const page = document.getElementById(`page-${pageId}`);
      if (!page) return;
      const material = getLowdimMaterialConfig(pageId);
      const security = getTwodSecurityState();
      const levelOneCount = security.classificationTasks.filter((item) => item.finalLevel === "SEC-01").length;
      const levelTwoCount = security.classificationTasks.filter((item) => item.finalLevel === "SEC-02").length;
      page.innerHTML = `
        ${getLowdimWorkflowStyle()}
        ${renderTwodSecurityStyle()}
        <div class="lowdim-workflow-page">
          <div class="lowdim-workflow-head">
            <div>
              <h2>${material.ingestTitle}</h2>
              <p>围绕二维材料数据采集加工处理，统一管理定级、授权、续期与访问控制。</p>
            </div>
          </div>
          <div class="lowdim-workflow-tabs" role="tablist" aria-label="${material.ingestTitle}">
            ${LOWDIM_INGEST_TABS.map((tab) => `<button class="lowdim-workflow-tab${tab.key === "security" ? " active" : ""}" type="button" role="tab" aria-selected="${tab.key === "security" ? "true" : "false"}" data-lowdim-ingest-page="${pageId}" data-lowdim-ingest-tab="${tab.key}">${tab.label}</button>`).join("")}
          </div>
          <div class="twod-security-page-v2">
            <div class="twod-security-titlebar">
              <div>
                <h2>数据安全等级管理</h2>
                <p>按来源类型、时效性和授权状态建立两级安全管理闭环，支持审核、规则维护、到期提醒和续期处理。</p>
              </div>
              <div class="twod-security-stat-row">
                <span class="twod-security-stat-pill level-1">1级公开数据 ${levelOneCount} 条</span>
                <span class="twod-security-stat-pill level-2">2级半公开数据 ${levelTwoCount} 条</span>
              </div>
            </div>
            <div class="twod-security-shell">
              ${renderTwodSecuritySubTabs(security)}
              <main class="twod-security-content">
                ${renderTwodSecurityActiveTab(security)}
              </main>
            </div>
          </div>
        </div>
      `;
    }

    function setTwodSecurityModalFooter(text) {
      const footerButton = document.querySelector("#twodIngestSecurityModal [data-twod-ingest-security-modal-save]");
      if (footerButton) footerButton.textContent = text || "保存";
    }

    function openTwodSecurityModal(mode, recordId = "") {
      const security = getTwodSecurityState();
      const title = document.getElementById("twodIngestSecurityModalTitle");
      const body = document.getElementById("twodIngestSecurityModalBody");
      state.twodSecurityEditing = { mode, recordId };
      setTwodSecurityModalFooter(mode.includes("review") || mode === "class-review" ? "确认审核" : "保存");
      if (mode === "class-review") {
        const task = security.classificationTasks.find((item) => item.id === recordId);
        if (title) title.textContent = "定级审核";
        if (body) body.innerHTML = `
          <div class="twod-security-form-grid">
            <div class="twod-security-readonly"><strong>材料基本信息</strong><br>${escapeLowDimHtml(task?.materialId || "-")} / ${escapeLowDimHtml(task?.formula || "-")} / 入库时间 ${escapeLowDimHtml(task?.storageTime || "-")}</div>
            <div class="twod-security-readonly"><strong>来源详情</strong><br>${escapeLowDimHtml(task?.sourceDetail || "-")}</div>
            <div class="twod-security-readonly wide"><strong>初始等级判定依据</strong><br>${escapeLowDimHtml(task?.reason || "-")}</div>
            <label class="field"><span>安全等级调整</span><select id="twodSecurityClassLevel"><option value="SEC-01" ${task?.finalLevel === "SEC-01" ? "selected" : ""}>第1级-完全公开</option><option value="SEC-02" ${task?.finalLevel === "SEC-02" ? "selected" : ""}>第2级-半公开</option></select></label>
            <label class="field wide"><span>调整原因</span><textarea id="twodSecurityClassReason" rows="3" placeholder="请填写确认或调整原因">${escapeLowDimHtml(task?.reason || "")}</textarea></label>
          </div>`;
      } else if (mode === "level-edit") {
        const level = security.levelDefinitions.find((item) => item.code === recordId);
        if (title) title.textContent = "编辑安全等级规则";
        if (body) body.innerHTML = `
          <div class="twod-security-form-grid">
            <div class="twod-security-readonly wide"><strong>${escapeLowDimHtml(level?.title || "-")}</strong><br>${escapeLowDimHtml(level?.levelText || "-")}</div>
            <label class="field wide"><span>数据范围描述</span><textarea id="twodSecurityLevelRange" rows="3">${escapeLowDimHtml(level?.dataRange || "")}</textarea></label>
            <label class="field wide"><span>访问条件</span><textarea id="twodSecurityLevelCondition" rows="3">${escapeLowDimHtml(level?.accessCondition || "")}</textarea></label>
            <label class="field wide"><span>访问控制规则</span><textarea id="twodSecurityLevelControl" rows="3">${escapeLowDimHtml(level?.accessControl || "")}</textarea></label>
          </div>`;
      } else if (mode === "eval-add" || mode === "eval-edit") {
        const rule = mode === "eval-edit" ? security.evaluationRules.find((item) => item.id === recordId) : null;
        if (title) title.textContent = mode === "eval-edit" ? "编辑评估规则" : "新增评估规则";
        if (body) body.innerHTML = `
          <div class="twod-security-form-grid">
            <label class="field wide"><span>规则名称</span><input id="twodSecurityEvalTitle" value="${escapeLowDimHtml(rule?.title || "")}" placeholder="如：计算数据入库6个月后自动降为1级"></label>
            <label class="field wide"><span>自动判定条件</span><textarea id="twodSecurityEvalCondition" rows="3">${escapeLowDimHtml(rule?.condition || "")}</textarea></label>
            <label class="field wide"><span>执行动作</span><textarea id="twodSecurityEvalAction" rows="3">${escapeLowDimHtml(rule?.action || "")}</textarea></label>
            <label class="field"><span>状态</span><select id="twodSecurityEvalEnabled"><option value="true" ${rule?.enabled === false ? "" : "selected"}>已启用</option><option value="false" ${rule?.enabled === false ? "selected" : ""}>已停用</option></select></label>
          </div>`;
      } else if (mode === "auth-review") {
        const app = security.authApplicationsV2.find((item) => item.id === recordId);
        if (title) title.textContent = "授权申请审核";
        if (body) body.innerHTML = `
          <div class="twod-security-form-grid">
            <div class="twod-security-readonly"><strong>用户ID（自动获取）</strong><br>${escapeLowDimHtml(app?.userId || "-")}</div>
            <div class="twod-security-readonly"><strong>姓名 / 机构</strong><br>${escapeLowDimHtml(app?.name || "-")} / ${escapeLowDimHtml(app?.org || "-")}</div>
            <div class="twod-security-readonly wide"><strong>申请理由</strong><br>${escapeLowDimHtml(app?.reason || "-")}</div>
            <div class="twod-security-readonly wide"><strong>申请数据范围与期限</strong><br>${escapeLowDimHtml(app?.dataRange || "-")} / ${escapeLowDimHtml(`${app?.durationMonths || "-"}月`)}</div>
            <label class="field"><span>审核操作</span><select id="twodSecurityAuthDecision"><option value="approve">批准</option><option value="reject">驳回</option></select></label>
            <label class="field"><span>授权到期日</span><input id="twodSecurityAuthExpiry" type="date" value="${escapeLowDimHtml(app?.expiryDate || "2027-02-06")}"></label>
            <label class="field wide"><span>驳回原因 / 审核意见</span><textarea id="twodSecurityAuthReason" rows="3">${escapeLowDimHtml(app?.rejectReason || "同意授权，按申请范围开通第2级半公开数据访问。")}</textarea></label>
            <div class="twod-security-readonly wide"><strong>用户历史申请记录</strong><br>${security.authApplicationsV2.filter((item) => item.userId === app?.userId).map((item) => `${item.appliedAt} ${item.id} ${item.status}`).join("；") || "暂无历史记录"}</div>
          </div>`;
      } else if (mode === "renew-review") {
        const renew = security.renewalApplications.find((item) => item.id === recordId);
        if (title) title.textContent = "续期审核";
        if (body) body.innerHTML = `
          <div class="twod-security-form-grid">
            <div class="twod-security-readonly"><strong>用户</strong><br>${escapeLowDimHtml(renew?.userId || "-")} / ${escapeLowDimHtml(renew?.name || "-")}</div>
            <div class="twod-security-readonly"><strong>延期申请</strong><br>${escapeLowDimHtml(renew?.originalExpiry || "-")} → ${escapeLowDimHtml(renew?.requestUntil || "-")}</div>
            <label class="field"><span>审核操作</span><select id="twodSecurityRenewDecision"><option value="approve">批准延期</option><option value="reject">驳回并降级为普通用户</option></select></label>
            <label class="field wide"><span>审核意见</span><textarea id="twodSecurityRenewReason" rows="3">续期申请资料完整，同意延长授权。</textarea></label>
          </div>`;
      }
      openModal("twodIngestSecurityModal");
    }

    function saveTwodSecurityModal() {
      const editing = state.twodSecurityEditing || {};
      const security = getTwodSecurityState();
      if (editing.mode === "class-review") {
        const task = security.classificationTasks.find((item) => item.id === editing.recordId);
        if (!task) return;
        const newLevel = document.getElementById("twodSecurityClassLevel")?.value || task.finalLevel;
        const reason = (document.getElementById("twodSecurityClassReason")?.value || "").trim();
        if (!reason) return showToast("定级审核", "请填写确认或调整原因。");
        if (!window.confirm("请再次确认提交安全定级审核结果。")) return;
        const oldLevel = task.finalLevel;
        task.finalLevel = newLevel;
        task.reviewStatus = newLevel === task.initialLevel ? "已确认" : "已调整";
        task.reason = reason;
        security.changeLogsV2.unshift({ id: `chg-${Date.now()}`, materialId: task.materialId, oldLevel, newLevel, operator: "数据管理员", time: `${TWOD_SECURITY_TODAY} 11:00`, reason });
        closeModal("twodIngestSecurityModal");
        renderTwodSecurityPage("lowdim-ingest-twod");
        showToast("定级审核", `${task.materialId} 已更新为${twodSecurityLevelDefinition(newLevel).levelText}。`);
        return;
      }
      if (editing.mode === "level-edit") {
        const level = security.levelDefinitions.find((item) => item.code === editing.recordId);
        if (!level) return;
        const dataRange = (document.getElementById("twodSecurityLevelRange")?.value || "").trim();
        const accessCondition = (document.getElementById("twodSecurityLevelCondition")?.value || "").trim();
        const accessControl = (document.getElementById("twodSecurityLevelControl")?.value || "").trim();
        if (!dataRange || !accessCondition || !accessControl) return showToast("等级规则", "请完整填写数据范围、访问条件和访问控制规则。");
        Object.assign(level, { dataRange, accessCondition, accessControl });
        closeModal("twodIngestSecurityModal");
        renderTwodSecurityPage("lowdim-ingest-twod");
        showToast("等级规则", "安全等级规则已保存。");
        return;
      }
      if (editing.mode === "eval-add" || editing.mode === "eval-edit") {
        const draft = {
          title: (document.getElementById("twodSecurityEvalTitle")?.value || "").trim(),
          condition: (document.getElementById("twodSecurityEvalCondition")?.value || "").trim(),
          action: (document.getElementById("twodSecurityEvalAction")?.value || "").trim(),
          enabled: document.getElementById("twodSecurityEvalEnabled")?.value !== "false"
        };
        if (!draft.title || !draft.condition || !draft.action) return showToast("评估规则", "请完整填写规则名称、条件和动作。");
        if (editing.mode === "eval-edit") {
          const index = security.evaluationRules.findIndex((item) => item.id === editing.recordId);
          if (index >= 0) security.evaluationRules[index] = Object.assign({}, security.evaluationRules[index], draft);
        } else {
          security.evaluationRules.push(Object.assign({ id: `rule-${Date.now()}` }, draft));
        }
        closeModal("twodIngestSecurityModal");
        renderTwodSecurityPage("lowdim-ingest-twod");
        showToast("评估规则", "数据范围评估规则已保存。");
        return;
      }
      if (editing.mode === "auth-review") {
        const app = security.authApplicationsV2.find((item) => item.id === editing.recordId);
        if (!app) return;
        const decision = document.getElementById("twodSecurityAuthDecision")?.value || "reject";
        const expiryDate = document.getElementById("twodSecurityAuthExpiry")?.value || "";
        const reason = (document.getElementById("twodSecurityAuthReason")?.value || "").trim();
        if (decision === "approve" && !expiryDate) return showToast("授权审核", "批准时需要设置授权到期日。");
        if (decision === "reject" && !reason) return showToast("授权审核", "驳回时需要填写驳回原因。");
        if (!window.confirm("请再次确认授权申请审核结果。")) return;
        app.status = decision === "approve" ? "已批准" : "已驳回";
        app.expiryDate = expiryDate;
        app.rejectReason = reason;
        if (decision === "approve") {
          const existing = security.authorizedUsersV2.find((user) => user.userId === app.userId);
          const draft = { userId: app.userId, name: app.name, org: app.org, email: `${app.userId.toLowerCase()}@example.org`, dataRange: `${app.dataRange} / 第2级半公开`, authorizedTo: expiryDate, status: "有效", reminderStatus: "未发送" };
          if (existing) Object.assign(existing, draft);
          else security.authorizedUsersV2.push(draft);
        }
        closeModal("twodIngestSecurityModal");
        renderTwodSecurityPage("lowdim-ingest-twod");
        showToast("授权审核", `${app.id} ${app.status}。`);
        return;
      }
      if (editing.mode === "renew-review") {
        const renew = security.renewalApplications.find((item) => item.id === editing.recordId);
        if (!renew) return;
        const decision = document.getElementById("twodSecurityRenewDecision")?.value || "reject";
        const reason = (document.getElementById("twodSecurityRenewReason")?.value || "").trim();
        if (!window.confirm("请再次确认续期审核结果。")) return;
        const user = security.authorizedUsersV2.find((item) => item.userId === renew.userId);
        renew.status = decision === "approve" ? "已批准" : "已驳回";
        renew.reviewReason = reason;
        if (user && decision === "approve") {
          user.authorizedTo = renew.requestUntil;
          user.status = "有效";
          user.reminderStatus = "已续期申请";
        } else if (user) {
          user.status = "已降级";
          user.dataRange = "第1级公开数据";
        }
        closeModal("twodIngestSecurityModal");
        renderTwodSecurityPage("lowdim-ingest-twod");
        showToast("续期审核", `${renew.name} 的续期申请${renew.status}。`);
      }
    }

    function deleteTwodSecurityEvaluationRule(ruleId) {
      const security = getTwodSecurityState();
      const rule = security.evaluationRules.find((item) => item.id === ruleId);
      if (!rule) return;
      if (!window.confirm(`确认删除规则「${rule.title}」吗？`)) return;
      security.evaluationRules = security.evaluationRules.filter((item) => item.id !== ruleId);
      renderTwodSecurityPage("lowdim-ingest-twod");
      showToast("评估规则", "规则已删除。");
    }

    function revokeTwodSecurityAuthorization(userId) {
      const security = getTwodSecurityState();
      const user = security.authorizedUsersV2.find((item) => item.userId === userId);
      if (!user) return;
      if (!window.confirm(`确认撤销「${user.name}」的第2级数据授权吗？`)) return;
      user.status = "已撤销";
      user.dataRange = "第1级公开数据";
      renderTwodSecurityPage("lowdim-ingest-twod");
      showToast("授权用户", "授权已撤销。");
    }

    function extendTwodSecurityAuthorization(userId) {
      const security = getTwodSecurityState();
      const user = security.authorizedUsersV2.find((item) => item.userId === userId);
      if (!user) return;
      security.renewalApplications.unshift({ id: `REN-${Date.now()}`, userId: user.userId, name: user.name, originalExpiry: user.authorizedTo, requestUntil: "2027-02-06", appliedAt: TWOD_SECURITY_TODAY, status: "待审核" });
      security.activeTab = "renewal";
      renderTwodSecurityPage("lowdim-ingest-twod");
      showToast("延期申请", "已生成续期审核记录。");
    }

    function sendTwodSecurityReminder(userId) {
      const security = getTwodSecurityState();
      const user = security.authorizedUsersV2.find((item) => item.userId === userId);
      if (!user) return;
      user.reminderStatus = "已发送邮件";
      renderTwodSecurityPage("lowdim-ingest-twod");
      showToast("续期提醒", `已模拟向 ${user.email} 发送续期提醒邮件。`);
    }

    function getLowdimUnifiedIngestSummary(materialKey, material) {
      const summaries = {
        opto: [["资源对象", "12", "分子、光谱与器件性能对象"], ["待处理任务", "08", "文献与实验数据采集"], ["已入库记录", material.records, "已完成字段映射与校验"], ["支持格式", "4", material.format]],
        electrolyte: [["资源对象", "10", "配方、输运与测试对象"], ["待处理任务", "06", "实验数据与文献数据采集"], ["已入库记录", material.records, "已完成单位统一与复核"], ["支持格式", "4", material.format]],
        mlff: [["资源对象", "09", "轨迹、能量与模型对象"], ["待处理任务", "05", "计算轨迹批量处理"], ["已入库记录", material.records, "已完成格式检查与切分"], ["支持格式", "4", material.format]],
        catalyst: [["资源对象", "11", "催化剂、反应与性能对象"], ["待处理任务", "07", "计算与实验数据采集"], ["已入库记录", material.records, "已完成来源绑定与质检"], ["支持格式", "4", material.format]]
      };
      return summaries[materialKey] || [["资源对象", "08", "材料数据资源对象"], ["待处理任务", "05", "采集加工任务"], ["已入库记录", material.records, "已完成质量检查"], ["支持格式", "4", material.format]];
    }

    function renderLowdimUnifiedIngestStyle() {
      return `<style>
        .lowdim-unified-ingest-page { background:#f4f6fa; margin:-24px; padding:24px; min-height:calc(100vh - 80px); color:#1f2d3d; }
        .lowdim-unified-ingest-head { display:flex; align-items:flex-start; justify-content:space-between; gap:20px; margin-bottom:18px; }
        .lowdim-unified-ingest-head h1 { margin:0 0 6px; color:#1f2d3d; font-size:24px; line-height:32px; font-weight:800; }
        .lowdim-unified-ingest-head p { margin:0; color:#74849a; font-size:13px; line-height:21px; }
        .lowdim-ingest-summary { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px; margin-bottom:18px; }
        .lowdim-ingest-summary-card { min-height:88px; padding:16px 18px; border:1px solid #e2e8f0; border-radius:10px; background:#fff; box-shadow:0 2px 8px rgba(35,64,96,.04); }
        .lowdim-ingest-summary-card span { display:block; margin-bottom:7px; color:#8191a5; font-size:12px; }
        .lowdim-ingest-summary-card strong { display:block; color:#25364d; font-size:24px; line-height:28px; }
        .lowdim-ingest-summary-card small { display:block; margin-top:5px; color:#98a5b4; font-size:11px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
        .lowdim-ingest-stepper { display:flex; align-items:stretch; min-height:72px; border:1px solid #e1e7ef; border-radius:10px 10px 0 0; background:#fff; overflow:auto; }
        .lowdim-ingest-stepper button { position:relative; display:flex; align-items:center; gap:10px; flex:1 0 170px; min-height:72px; padding:0 20px; border:0; border-right:1px solid #edf1f5; color:#8796a8; background:#fff; cursor:pointer; font:inherit; text-align:left; }
        .lowdim-ingest-stepper button:last-child { border-right:0; }
        .lowdim-ingest-stepper button:hover { background:#f8fbff; }
        .lowdim-ingest-stepper button.active { color:#1f63ff; background:#f5f9ff; }
        .lowdim-ingest-stepper button.active::after { content:""; position:absolute; left:0; right:0; bottom:0; height:3px; background:#1f63ff; }
        .lowdim-ingest-step-index { width:30px; height:30px; display:grid; place-items:center; flex:none; border:1px solid #d6dee8; border-radius:50%; color:#8998aa; background:#f5f7fa; font-size:12px; font-weight:800; }
        .lowdim-ingest-stepper button.active .lowdim-ingest-step-index { border-color:#1f63ff; color:#fff; background:#1f63ff; box-shadow:0 0 0 4px rgba(31,99,255,.12); }
        .lowdim-ingest-step-copy strong { display:block; color:inherit; font-size:13px; line-height:18px; }
        .lowdim-ingest-step-copy small { display:block; margin-top:2px; color:#9aa8b8; font-size:11px; }
        .lowdim-ingest-content { padding:20px; border:1px solid #e1e7ef; border-top:0; border-radius:0 0 10px 10px; background:var(--color-bg-table-head, #f5f5f5); }
        .lowdim-ingest-content-head { display:flex; align-items:flex-start; justify-content:space-between; gap:16px; margin-bottom:16px; }
        .lowdim-ingest-content-head h2 { margin:0 0 4px; color:#25364d; font-size:18px; line-height:26px; }
        .lowdim-ingest-content-head p { margin:0; color:#8191a5; font-size:12px; line-height:19px; }
        .lowdim-ingest-content .lowdim-workflow-panel { border-radius:9px; box-shadow:0 2px 8px rgba(35,64,96,.035); }
        .lowdim-ingest-content .lowdim-workflow-panel-head { background:#fff; }
        .lowdim-ingest-content .lowdim-workflow-table th { background:#f3f6fa; color:#52667d; }
        .lowdim-ingest-content .lowdim-workflow-table td { background:#fff; }
        @media (max-width:900px) { .lowdim-ingest-summary { grid-template-columns:repeat(2,minmax(0,1fr)); } .lowdim-unified-ingest-head { flex-direction:column; } }
        @media (max-width:560px) {
          .lowdim-unified-ingest-page { margin:-16px; padding:16px; }
          .lowdim-ingest-summary { grid-template-columns:1fr; }
          .lowdim-ingest-content { padding:14px; }
          .lowdim-ingest-content .lowdim-workflow-panel { overflow-x:auto; }
          .lowdim-ingest-content .lowdim-workflow-table-wrap { overflow-x:auto; }
          .lowdim-ingest-content .lowdim-workflow-table { min-width:760px; table-layout:fixed; }
        }
      </style>`;
    }

    function renderLowdimUnifiedIngestPage(pageId) {
      const page = document.getElementById(`page-${pageId}`);
      if (!page) return;
      const material = getLowdimMaterialConfig(pageId);
      const materialKey = getLowdimMaterialKey(pageId);
      const activeTab = getLowdimIngestActiveTab(pageId);
      const tabMeta = LOWDIM_INGEST_TABS.find((tab) => tab.key === activeTab) || LOWDIM_INGEST_TABS[0];
      const table = getLowdimIngestTableWithCustomRows(pageId, activeTab, material);
      const summaries = getLowdimUnifiedIngestSummary(materialKey, material);
      const stepDescriptions = { objects:"定义字段范围", collection:"配置来源与任务", entry:"导入结构化数据", processing:"执行清洗与质检", security:"管理访问权限" };
      const content = activeTab === "entry"
        ? renderLowdimEntryPrototype(pageId)
        : activeTab === "processing"
          ? renderLowdimProcessingPrototype(pageId)
          : renderLowdimWorkflowTable(table.columns, table.rows);
      page.innerHTML = `
        ${getLowdimWorkflowStyle()}${renderLowdimUnifiedIngestStyle()}
        <div class="lowdim-unified-ingest-page">
          <header class="lowdim-unified-ingest-head"><div><h1>${material.ingestTitle}</h1><p>统一管理${material.short}的数据对象、采集任务、结构化录入、质量加工与安全分级，形成可追溯的数据入库链路。</p></div></header>
          <div class="lowdim-ingest-summary" aria-label="${material.short}采集加工概览">${summaries.map((item) => `<div class="lowdim-ingest-summary-card"><span>${item[0]}</span><strong>${item[1]}</strong><small>${item[2]}</small></div>`).join("")}</div>
          <div class="lowdim-ingest-stepper" role="tablist" aria-label="${material.ingestTitle}">${LOWDIM_INGEST_TABS.map((tab, index) => `<button class="${tab.key === activeTab ? "active" : ""}" type="button" role="tab" aria-selected="${tab.key === activeTab ? "true" : "false"}" data-lowdim-ingest-page="${pageId}" data-lowdim-ingest-tab="${tab.key}"><span class="lowdim-ingest-step-index">${index + 1}</span><span class="lowdim-ingest-step-copy"><strong>${tab.label}</strong><small>${stepDescriptions[tab.key]}</small></span></button>`).join("")}</div>
          <main class="lowdim-ingest-content"><div class="lowdim-ingest-content-head"><div><h2>${tabMeta.label}</h2><p>${material.short}${tabMeta.label}配置与执行情况</p></div>${activeTab === "objects" || activeTab === "collection" ? `<button class="btn-primary" type="button" data-twod-ingest-generic-add="${activeTab}">${activeTab === "objects" ? "新增资源对象" : "新建采集任务"}</button>` : ""}</div><div class="lowdim-workflow-panel">${content}</div></main>
        </div>
      `;
      if (activeTab === "entry" && getLowdimEntryState(pageId).mode === "manual") requestAnimationFrame(applyLowdimManualEntryValidation);
    }

    function renderLowdimIngestPage(pageId) {
      /* 详情页不是采集加工处理页，交由 renderLowdimIngestDetailPage 处理 */
      if (pageId === "lowdim-ingest-detail") {
        renderLowdimIngestDetailPage();
        return;
      }
      const page = document.getElementById(`page-${pageId}`);
      if (!page) return;
      const material = getLowdimMaterialConfig(pageId);
      const materialKey = getLowdimMaterialKey(pageId);
      if (LOWDIM_TASK_WIZARD_CONFIGS[materialKey]) {
        const wizard = state.lowdimIngestWizards?.[pageId];
        /* 主内容：有向导时展示分步向导，否则展示任务列表；两者下方统一追加审核状态列表，
           确保「审核不通过需重新提交」等状态在任何视图下都能直接看到 */
        /* 列表页三块列表（任务表 / 存档分组表 / 审核状态列表）已合并为一张统一任务总表；
           创建采集任务向导内也不保留任何非步骤列表，只展示当前步骤内容 */
        const twodMainContent = wizard ? renderTwodTaskWizard(pageId) : renderLowdimUnifiedIngestTaskTable(pageId);
        page.innerHTML = `${getLowdimWorkflowStyle()}${renderTwodTaskWizardStyle(pageId)}<div class="twod-main-page" data-twod-wizard-page="${escapeLowDimHtml(pageId)}"><header class="twod-main-head"><div><h1>${escapeLowDimHtml(material.ingestTitle)}</h1><p>${wizard ? `分步引导完成${escapeLowDimHtml(material.short)}数据的采集、加工与入库` : `管理${escapeLowDimHtml(material.short)}数据的采集与加工任务，涵盖数据采集、加工、安全判定、标准化与入库全流程`}</p></div>${wizard ? "" : `<div class="twod-main-actions">${renderTwodIngestCollectionActions(pageId)}</div>`}</header>${twodMainContent}</div>`;
        return;
      }
      const activeTab = getLowdimIngestActiveTab(pageId);
      if (materialKey === "twod" && activeTab === "security") {
        renderTwodSecurityPage(pageId);
        return;
      }
      const tabMeta = LOWDIM_INGEST_TABS.find((item) => item.key === activeTab) || LOWDIM_INGEST_TABS[0];
      const table = getLowdimIngestTableWithCustomRows(pageId, activeTab, material);
      const isTwodResourceObjects = materialKey === "twod" && activeTab === "objects";
      const isTwodCollection = materialKey === "twod" && activeTab === "collection";
      const isEntryPrototype = activeTab === "entry";
      const isProcessingPrototype = materialKey === "twod" && activeTab === "processing";
      const isTwodIngestEditableTab = materialKey === "twod";
      page.innerHTML = `
        ${getLowdimWorkflowStyle()}
        <div class="lowdim-workflow-page">
          <div class="lowdim-workflow-head">
            <div>
              <h2>${material.ingestTitle}</h2>
              <p>围绕${material.short}入库前的数据对象定义、采集、录入、加工和安全分级进行统一管理，支撑后续标准化和数据库发布。</p>
            </div>
          </div>
          <div class="lowdim-workflow-tabs" role="tablist" aria-label="${material.ingestTitle}">
            ${LOWDIM_INGEST_TABS.map((tab) => `<button class="lowdim-workflow-tab${tab.key === activeTab ? " active" : ""}" type="button" role="tab" aria-selected="${tab.key === activeTab ? "true" : "false"}" data-lowdim-ingest-page="${pageId}" data-lowdim-ingest-tab="${tab.key}">${tab.label}</button>`).join("")}
          </div>
          <div class="lowdim-workflow-panel">
            <div class="lowdim-workflow-panel-head">
              <div>
                <h3>${isTwodCollection ? (state.twodTaskWizard ? "创建采集任务" : "任务列表") : tabMeta.label}</h3>
                <span>${isTwodCollection ? "统一管理二维材料数据采集任务，查看任务状态与资源对象" : `${material.short}数据采集加工处理配置`}</span>
              </div>
              ${isTwodResourceObjects
                ? `<button class="btn-primary" type="button" data-twod-ingest-resource-add>新增资源对象</button>`
                : (isTwodCollection
                  ? renderTwodIngestCollectionActions()
                  : ((isEntryPrototype || isProcessingPrototype) ? "" : (isTwodIngestEditableTab ? `<button class="btn-primary" type="button" data-twod-ingest-generic-add="${activeTab}">${getTwodIngestGenericAddLabel(activeTab)}</button>` : "")))}
            </div>
            ${isTwodResourceObjects ? renderTwodIngestResourceObjectTable() : (isTwodCollection ? (state.twodTaskWizard ? renderTwodTaskWizard(pageId) : renderTwodIngestCollectionTaskTable()) : (isEntryPrototype ? renderLowdimEntryPrototype(pageId) : (isProcessingPrototype ? renderLowdimProcessingPrototype(pageId) : renderLowdimWorkflowTable(table.columns, table.rows))))}
          </div>
        </div>
      `;
      if (isEntryPrototype && getLowdimEntryState(pageId).mode === "manual") {
        requestAnimationFrame(applyLowdimManualEntryValidation);
      }
    }

    const TWOD_STANDARDIZATION_CATEGORIES = [
      { key: "calc", label: "计算方法标准化" },
      { key: "format", label: "数据格式标准化" },
      { key: "table", label: "数据表格标准化" },
      { key: "image", label: "数据图片标准化" },
      { key: "unit", label: "数据单位标准化" }
    ];

    const TWOD_STANDARDIZATION_DEFAULT_RULES = {
      calc: [
        { id: "calc-method", item: "calc_method", value: "VASP方法", type: "字符", example: "calc_method=VASP", note: "统一二维材料第一性原理计算方法字段。" },
        { id: "calc-version", item: "calc_software_version", value: "VASP 6.x", type: "字符", example: "calc_software_version=VASP 6.4", note: "记录计算软件版本，便于复核与重算。" },
        { id: "calc-functional", item: "functional", value: "GGA-PBE泛函", type: "字符", example: "functional=GGA-PBE", note: "交换关联泛函统一采用 GGA-PBE。" },
        { id: "calc-encut", item: "encut", value: "500 eV", type: "数字+单位", example: "encut=500", note: "平面波截断能标准值。" },
        { id: "calc-kpoint", item: "kpoint_grid", value: "15 x 15 x 1", type: "字符", example: "kpoint_grid=15x15x1", note: "二维材料默认 K 点网格。" },
        { id: "calc-convergence", item: "convergence_criteria", value: "1e-6 eV；0.01 eV/A", type: "字符", example: "energy=1e-6, force=0.01", note: "能量和力收敛标准。" },
        { id: "calc-vdw", item: "vdw_correction", value: "DFT-D3范德华修正", type: "字符", example: "vdw_correction=DFT-D3", note: "层状体系范德华相互作用修正。" },
        { id: "calc-u", item: "DFT+U", value: "按元素体系配置 U 值", type: "字符", example: "U(Co)=3.3 eV", note: "过渡金属体系启用 DFT+U。" },
        { id: "calc-quality", item: "quality_grade", value: "A / B / C", type: "枚举", example: "quality_grade=A", note: "按计算完整性和复核结果分级。" }
      ],
      format: [
        { id: "fmt-vasp", item: "VASP输出格式标准", value: "OUTCAR / CONTCAR / vasprun.xml / DOSCAR / EIGENVAL", type: "文件集合", example: "OUTCAR + CONTCAR + vasprun.xml", note: "VASP输出文件需保留核心计算结果和结构文件。" },
        { id: "fmt-dat", item: ".dat文件格式标准", value: "UTF-8；首行为字段名；空格或制表符分隔", type: "文本", example: "energy(eV) density(states/eV)", note: "曲线和谱图源数据统一为可解析文本格式。" },
        { id: "fmt-source", item: "源文件格式标准", value: "CIF / POSCAR / JSON / PNG / DAT", type: "枚举", example: "MoS2_band.dat", note: "源文件需保留原始文件名、格式和来源。" }
      ],
      table: [
        { id: "tab-col", item: "统一列名", value: "material_id, formula, property_name, value, unit, source", type: "字符", example: "material_id, band_gap, value, unit", note: "表格列名使用英文小写和下划线。" },
        { id: "tab-type", item: "数据类型", value: "string / number / array / file_ref", type: "枚举", example: "band_gap:number", note: "字段类型需与数据库字段定义一致。" },
        { id: "tab-precision", item: "数值精度", value: "能量 1e-4；长度 1e-3；温度 0.1", type: "数字", example: "formation_energy=-1.2345", note: "统一数值有效位数和入库精度。" },
        { id: "tab-unit-list", item: "标准单位列表", value: "A、度、N/m2、eV、uB/atom", type: "单位", example: "bond_length=A", note: "表格单位必须匹配标准单位定义。" }
      ],
      image: [
        { id: "img-png", item: "图片格式", value: "PNG格式", type: "文件", example: "band_structure.png", note: "标准图谱统一使用 PNG。" },
        { id: "img-dpi", item: "图片分辨率", value: "300 dpi", type: "数字+单位", example: "dpi=300", note: "用于归档和页面展示的最低分辨率。" },
        { id: "img-size", item: "文件大小", value: "200 KB - 1 MB", type: "数字+单位", example: "512 KB", note: "图片文件大小需处于标准范围。" },
        { id: "img-3d", item: "3D模型格式", value: "DAE格式", type: "文件", example: "structure.dae", note: "三维模型统一使用 DAE 格式。" }
      ],
      unit: [
        { id: "unit-bond-length", item: "键长", value: "A", type: "单位", example: "2.410 A", note: "原子间键长标准单位。" },
        { id: "unit-bond-angle", item: "键角", value: "度", type: "单位", example: "120 度", note: "键角标准单位。" },
        { id: "unit-young", item: "杨氏模量", value: "N/m2", type: "单位", example: "2.7e11 N/m2", note: "杨氏模量标准单位。" },
        { id: "unit-formation", item: "形成能", value: "eV", type: "单位", example: "-1.24 eV", note: "材料形成能标准单位。" },
        { id: "unit-bandgap", item: "带隙", value: "eV", type: "单位", example: "1.82 eV", note: "电子带隙标准单位。" },
        { id: "unit-moment", item: "磁矩", value: "uB/atom", type: "单位", example: "0.43 uB/atom", note: "原子磁矩标准单位。" }
      ]
    };

    const TWOD_STANDARDIZATION_NONSTANDARD_DEFAULTS = [
      { id: "ns-001", material: "MoS2-2H", field: "encut", current: "420 eV", target: "500 eV", reason: "截断能低于标准值", status: "待处理" },
      { id: "ns-002", material: "Graphene-001", field: "functional", current: "LDA", target: "GGA-PBE", reason: "泛函不符合当前标准", status: "待处理" },
      { id: "ns-003", material: "h-BN-003", field: "image_dpi", current: "180 dpi", target: "300 dpi", reason: "图片分辨率低于标准", status: "待处理" },
      { id: "ns-004", material: "WSe2-006", field: "bond_length_unit", current: "nm", target: "A", reason: "键长单位需转换", status: "待处理" }
    ];

    function getTwodStandardizationState() {
      if (!state.twodStandardization) {
        state.twodStandardization = {
          activeCategory: "calc",
          rules: Object.fromEntries(Object.entries(TWOD_STANDARDIZATION_DEFAULT_RULES).map(([key, rows]) => [key, rows.map((item) => Object.assign({}, item))])),
          dirty: {},
          selected: [],
          scan: { running: false, progress: 0, complete: false, results: [] }
        };
      }
      return state.twodStandardization;
    }

    function getTwodStandardizationStyle() {
      return `
        <style>
          #page-lowdim-standardization-twod .twod-std-shell {
            display: grid;
            grid-template-columns: 240px minmax(0, 1fr);
            gap: 18px;
            margin-top: 20px;
          }
          #page-lowdim-standardization-twod .twod-std-nav,
          #page-lowdim-standardization-twod .twod-std-card {
            border: 1px solid #d7dce8;
            background: #ffffff;
          }
          #page-lowdim-standardization-twod .twod-std-nav {
            padding: 10px;
          }
          #page-lowdim-standardization-twod .twod-std-nav button {
            width: 100%;
            min-height: 44px;
            margin-bottom: 6px;
            padding: 0 12px;
            border: 0;
            border-radius: 4px;
            background: transparent;
            color: #334155;
            text-align: left;
            font-weight: 700;
          }
          #page-lowdim-standardization-twod .twod-std-nav button.active {
            background: #eaf2ff;
            color: #1f63ff;
          }
          #page-lowdim-standardization-twod .twod-std-card-head {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            flex-wrap: wrap;
            padding: 16px 18px;
            border-bottom: 1px solid #e5eaf3;
          }
          #page-lowdim-standardization-twod .twod-std-card-head h3 {
            margin: 0;
            color: #111827;
            font-size: 18px;
          }
          #page-lowdim-standardization-twod .twod-std-status {
            display: inline-flex;
            align-items: center;
            min-height: 28px;
            padding: 3px 10px;
            border-radius: 999px;
            background: #ecfdf5;
            color: #047857;
            font-size: 13px;
            font-weight: 800;
          }
          #page-lowdim-standardization-twod .twod-std-status.dirty {
            background: #fff7ed;
            color: #c2410c;
          }
          #page-lowdim-standardization-twod .twod-std-actions {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
          }
          #page-lowdim-standardization-twod .twod-std-table-wrap {
            overflow: hidden;
          }
          #page-lowdim-standardization-twod .twod-std-table {
            width: 100%;
            max-width: 100%;
            min-width: 0;
            border-collapse: collapse;
            table-layout: fixed;
          }
          #page-lowdim-standardization-twod .twod-std-table th,
          #page-lowdim-standardization-twod .twod-std-table td {
            padding: 12px 14px;
            border-bottom: 1px solid #edf1f7;
            color: #111827;
            font-size: 14px;
            line-height: 22px;
            text-align: left;
            overflow-wrap: anywhere;
            word-break: break-word;
          }
          #page-lowdim-standardization-twod .twod-std-table th {
            background: #eaf2ff;
            color: #1f63ff;
            font-weight: 800;
          }
          #page-lowdim-standardization-twod .twod-std-cell {
            display: block;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
          }
          #page-lowdim-standardization-twod .twod-std-row-actions {
            display: flex;
            gap: 8px;
          }
          #page-lowdim-standardization-twod .twod-std-detect {
            margin-top: 18px;
          }
          #page-lowdim-standardization-twod .twod-std-progress {
            height: 8px;
            border-radius: 999px;
            background: #e2e8f0;
            overflow: hidden;
          }
          #page-lowdim-standardization-twod .twod-std-progress span {
            display: block;
            height: 100%;
            background: #1f63ff;
            transition: width 180ms ease;
          }
          .twod-standardization-rule-modal .twod-std-form-grid {
            display: grid;
            gap: 16px;
          }
          .twod-standardization-rule-modal .field > span {
            display: block;
            margin-bottom: 6px;
            color: #334155;
            font-size: 14px;
            font-weight: 700;
          }
          .twod-standardization-rule-modal .field input,
          .twod-standardization-rule-modal .field textarea {
            width: 100%;
          }
          @media (max-width: 900px) {
            #page-lowdim-standardization-twod .twod-std-shell {
              grid-template-columns: 1fr;
            }
          }
        </style>
      `;
    }

    function renderTwodStdCell(value) {
      const text = escapeLowDimHtml(value || "-");
      return `<span class="twod-std-cell" title="${text}">${text}</span>`;
    }

    function renderTwodStandardizationRules(activeKey) {
      const std = getTwodStandardizationState();
      const rows = std.rules[activeKey] || [];
      return `
        <div class="twod-std-table-wrap">
          <table class="twod-std-table">
            <thead>
              <tr>
                <th style="width:190px;">标准规则</th>
                <th style="width:170px;">数据字段</th>
                <th style="width:220px;">标准值</th>
                <th style="width:130px;">类型</th>
                <th>示例/说明</th>
                <th style="width:150px;">操作</th>
              </tr>
            </thead>
            <tbody>
              ${rows.map((row) => `
                <tr>
                  <td>${renderTwodStdCell(row.item)}</td>
                  <td>${renderTwodStdCell(row.field || row.item)}</td>
                  <td>${renderTwodStdCell(row.value)}</td>
                  <td>${renderTwodStdCell(row.type)}</td>
                  <td>${renderTwodStdCell(`${row.example || ""}${row.note ? `；${row.note}` : ""}`)}</td>
                  <td>
                    <div class="twod-std-row-actions">
                      <button class="btn btn-sm" type="button" data-twod-std-rule-edit="${row.id}">编辑</button>
                      <button class="btn btn-sm btn-danger-outline" type="button" data-twod-std-rule-delete="${row.id}">删除</button>
                    </div>
                  </td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>
      `;
    }

    function renderTwodNonstandardPanel() {
      const std = getTwodStandardizationState();
      const scan = std.scan;
      const selected = new Set(std.selected || []);
      const pendingCount = (scan.results || []).filter((item) => item.status !== "已标准化").length;
      return `
        <div class="twod-std-card twod-std-detect">
          <div class="twod-std-card-head">
            <div>
              <h3>非标数据检测</h3>
              <span>自动扫描并列出不符合当前标准的数据</span>
            </div>
            <div class="twod-std-actions">
              <button class="btn" type="button" data-twod-std-scan ${scan.running ? "disabled" : ""}>非标数据检测</button>
              <button class="btn-primary" type="button" data-twod-std-batch ${selected.size ? "" : "disabled"}>批量标准化</button>
            </div>
          </div>
          <div style="padding:16px 18px;">
            <div class="twod-std-progress" aria-label="扫描进度"><span style="width:${scan.progress || 0}%;"></span></div>
            <p style="margin:10px 0 0;color:#64748b;font-size:13px;">${scan.running ? `正在扫描数据库：${scan.progress}%` : (scan.complete ? `扫描完成，发现 ${pendingCount} 条待处理非标数据。` : "点击检测后扫描当前数据库中的非标数据。")}</p>
          </div>
          ${scan.results?.length ? `
            <div class="twod-std-table-wrap">
              <table class="twod-std-table">
                <thead>
                  <tr>
                    <th style="width:56px;">选择</th>
                    <th>材料</th>
                    <th>字段</th>
                    <th>当前值</th>
                    <th>标准值</th>
                    <th>问题说明</th>
                    <th style="width:110px;">状态</th>
                  </tr>
                </thead>
                <tbody>
                  ${scan.results.map((item) => `
                    <tr>
                      <td><input type="checkbox" data-twod-std-nonstandard-check="${item.id}" ${selected.has(item.id) ? "checked" : ""} ${item.status === "已标准化" ? "disabled" : ""}></td>
                      <td>${renderTwodStdCell(item.material)}</td>
                      <td>${renderTwodStdCell(item.field)}</td>
                      <td>${renderTwodStdCell(item.current)}</td>
                      <td>${renderTwodStdCell(item.target)}</td>
                      <td>${renderTwodStdCell(item.reason)}</td>
                      <td>${renderTwodStdCell(item.status)}</td>
                    </tr>
                  `).join("")}
                </tbody>
              </table>
            </div>
          ` : ""}
        </div>
      `;
    }

    function renderTwodStandardizationPage(pageId) {
      const page = document.getElementById(`page-${pageId}`);
      if (!page) return;
      const std = getTwodStandardizationState();
      const active = TWOD_STANDARDIZATION_CATEGORIES.find((item) => item.key === std.activeCategory) || TWOD_STANDARDIZATION_CATEGORIES[0];
      const dirty = Boolean(std.dirty?.[active.key]);
      const affected = Number(std.affectedCount || 0);
      page.innerHTML = `
        ${getLowdimWorkflowStyle()}
        ${getTwodStandardizationStyle()}
        <div class="lowdim-workflow-page">
          <div class="lowdim-workflow-head">
            <div>
              <h2>二维材料数据库标准化</h2>
              <p>围绕计算方法、数据格式、表格、图片和单位规则进行统一配置，并对存量非标数据执行检测和批量标准化。</p>
            </div>
          </div>
          ${affected ? `
            <div class="twod-std-card" style="margin-top:16px;padding:14px 18px;display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;">
              <span style="color:#92400e;font-weight:800;">标准更新影响存量数据：预计 ${affected} 条需要重新标准化。</span>
              <button class="btn-primary" type="button" data-twod-std-restandardize>批量重新标准化</button>
            </div>
          ` : ""}
          <div class="twod-std-shell">
            <nav class="twod-std-nav" aria-label="标准化类别导航">
              ${TWOD_STANDARDIZATION_CATEGORIES.map((item) => `<button type="button" class="${item.key === active.key ? "active" : ""}" data-twod-std-category="${item.key}">${item.label}</button>`).join("")}
            </nav>
            <section>
              <div class="twod-std-card">
                <div class="twod-std-card-head">
                  <div>
                    <h3>${active.label}</h3>
                    <span>当前类别标准规则列表</span>
                  </div>
                  <div class="twod-std-actions">
                    <span class="twod-std-status ${dirty ? "dirty" : ""}">${dirty ? "未保存" : "已保存"}</span>
                    <button class="btn" type="button" data-twod-std-rule-add>新增</button>
                    <button class="btn-primary" type="button" data-twod-std-save-standard ${dirty ? "" : "disabled"}>保存标准</button>
                  </div>
                </div>
                ${renderTwodStandardizationRules(active.key)}
              </div>
              ${renderTwodNonstandardPanel()}
            </section>
          </div>
        </div>
      `;
    }

    function openTwodStandardizationRuleModal(mode, ruleId = "") {
      const std = getTwodStandardizationState();
      const category = std.activeCategory || "calc";
      const rows = std.rules[category] || [];
      const record = mode === "edit" ? rows.find((item) => item.id === ruleId) : null;
      state.twodStandardizationEditing = { mode, category, ruleId };
      const title = document.getElementById("twodStandardizationRuleModalTitle");
      const body = document.getElementById("twodStandardizationRuleModalBody");
      if (title) title.textContent = mode === "edit" ? "编辑标准规则" : "新增标准规则";
      if (body) {
        body.innerHTML = `
          <div class="twod-std-form-grid">
            <label class="field"><span>标准规则</span><input id="twodStdRuleItem" type="text" value="${escapeLowDimHtml(record?.item || "")}" placeholder="请输入标准规则"></label>
            <label class="field"><span>数据字段</span><input id="twodStdRuleField" type="text" value="${escapeLowDimHtml(record?.field || record?.item || "")}" placeholder="请输入数据字段"></label>
            <label class="field"><span>标准值</span><input id="twodStdRuleValue" type="text" value="${escapeLowDimHtml(record?.value || "")}" placeholder="请输入标准值"></label>
            <label class="field"><span>数据类型</span><input id="twodStdRuleType" type="text" value="${escapeLowDimHtml(record?.type || "")}" placeholder="请输入数据类型"></label>
            <label class="field"><span>格式示例</span><textarea id="twodStdRuleExample" rows="3" placeholder="请输入格式示例">${escapeLowDimHtml(record?.example || "")}</textarea></label>
            <label class="field"><span>说明</span><textarea id="twodStdRuleNote" rows="3" placeholder="请输入说明">${escapeLowDimHtml(record?.note || "")}</textarea></label>
          </div>
        `;
      }
      openModal("twodStandardizationRuleModal");
    }

    function saveTwodStandardizationRule() {
      const editing = state.twodStandardizationEditing || {};
      const category = editing.category || getTwodStandardizationState().activeCategory || "calc";
      const item = (document.getElementById("twodStdRuleItem")?.value || "").trim();
      const field = (document.getElementById("twodStdRuleField")?.value || "").trim();
      const value = (document.getElementById("twodStdRuleValue")?.value || "").trim();
      const type = (document.getElementById("twodStdRuleType")?.value || "").trim();
      const example = (document.getElementById("twodStdRuleExample")?.value || "").trim();
      const note = (document.getElementById("twodStdRuleNote")?.value || "").trim();
      if (!item || !value || !type) {
        showToast("标准规则校验", "请填写标准规则、标准值和数据类型。");
        return;
      }
      const std = getTwodStandardizationState();
      const rows = std.rules[category] || [];
      const draft = { item, field: field || item, value, type, example, note };
      if (editing.mode === "edit") {
        const index = rows.findIndex((row) => row.id === editing.ruleId);
        if (index >= 0) rows[index] = Object.assign({}, rows[index], draft);
      } else {
        rows.push(Object.assign({ id: `${category}-${Date.now()}` }, draft));
      }
      std.dirty[category] = true;
      closeModal("twodStandardizationRuleModal");
      renderTwodStandardizationPage("lowdim-standardization-twod");
      showToast("标准规则", editing.mode === "edit" ? "规则已编辑，当前未保存。" : "规则已新增，当前未保存。");
    }

    function deleteTwodStandardizationRule(ruleId) {
      const std = getTwodStandardizationState();
      const category = std.activeCategory || "calc";
      const rows = std.rules[category] || [];
      const record = rows.find((row) => row.id === ruleId);
      if (!record) return;
      if (!window.confirm(`确认删除「${record.item}」吗？`)) return;
      std.rules[category] = rows.filter((row) => row.id !== ruleId);
      std.dirty[category] = true;
      renderTwodStandardizationPage("lowdim-standardization-twod");
      showToast("标准规则", "规则已删除，当前未保存。");
    }

    function saveTwodStandardizationStandard() {
      const std = getTwodStandardizationState();
      const category = std.activeCategory || "calc";
      std.dirty[category] = false;
      std.affectedCount = 128;
      renderTwodStandardizationPage("lowdim-standardization-twod");
      showToast("标准保存", "标准已保存，存量数据影响已计算。");
    }

    function runTwodStandardizationScan() {
      const std = getTwodStandardizationState();
      if (std.scan.running) return;
      std.scan = { running: true, progress: 0, complete: false, results: [] };
      std.selected = [];
      renderTwodStandardizationPage("lowdim-standardization-twod");
      clearInterval(runTwodStandardizationScan.timer);
      runTwodStandardizationScan.timer = setInterval(() => {
        const current = getTwodStandardizationState();
        current.scan.progress = Math.min(100, current.scan.progress + 20);
        if (current.scan.progress >= 100) {
          clearInterval(runTwodStandardizationScan.timer);
          current.scan.running = false;
          current.scan.complete = true;
          current.scan.results = TWOD_STANDARDIZATION_NONSTANDARD_DEFAULTS.map((item) => Object.assign({}, item));
        }
        renderTwodStandardizationPage("lowdim-standardization-twod");
      }, 220);
    }

    function batchTwodStandardization() {
      const std = getTwodStandardizationState();
      const selected = new Set(std.selected || []);
      if (!selected.size) {
        showToast("批量标准化", "请先勾选非标数据。");
        return;
      }
      std.scan.results = (std.scan.results || []).map((item) => selected.has(item.id) ? Object.assign({}, item, { current: item.target, status: "已标准化" }) : item);
      std.selected = [];
      renderTwodStandardizationPage("lowdim-standardization-twod");
      showToast("批量标准化", `${selected.size} 条非标数据已完成标准化。`);
    }

    function restandardizeTwodAffectedData() {
      const std = getTwodStandardizationState();
      std.affectedCount = 0;
      std.scan.results = (std.scan.results || []).map((item) => Object.assign({}, item, { current: item.target, status: "已标准化" }));
      std.selected = [];
      renderTwodStandardizationPage("lowdim-standardization-twod");
      showToast("批量重新标准化", "受影响的存量数据已完成重新标准化。");
    }

