    function renderTwodDbCell(value) {
      const text = escapeLowDimHtml(value || "-");
      return `<span class="twod-db-cell" title="${text}">${text}</span>`;
    }

    function renderTwodAtomicStructureSvg(label = "MoS2", large = false) {
      const safeLabel = escapeLowDimHtml(label || "二维结构");
      const radius = large ? 14 : 9;
      return `
        <svg viewBox="0 0 180 120" role="img" aria-label="${safeLabel} 原子结构图">
          <line x1="42" y1="36" x2="90" y2="60" stroke="#64748b" stroke-width="3"/>
          <line x1="90" y1="60" x2="138" y2="36" stroke="#64748b" stroke-width="3"/>
          <line x1="42" y1="84" x2="90" y2="60" stroke="#64748b" stroke-width="3"/>
          <line x1="90" y1="60" x2="138" y2="84" stroke="#64748b" stroke-width="3"/>
          <line x1="42" y1="36" x2="42" y2="84" stroke="#cbd5e1" stroke-width="2"/>
          <line x1="138" y1="36" x2="138" y2="84" stroke="#cbd5e1" stroke-width="2"/>
          <circle cx="90" cy="60" r="${radius + 2}" fill="#2563eb"/>
          <circle cx="42" cy="36" r="${radius}" fill="#f59e0b"/>
          <circle cx="138" cy="36" r="${radius}" fill="#f59e0b"/>
          <circle cx="42" cy="84" r="${radius}" fill="#10b981"/>
          <circle cx="138" cy="84" r="${radius}" fill="#10b981"/>
          ${large ? `<text x="90" y="112" text-anchor="middle" fill="#334155" font-size="14" font-weight="700">${safeLabel}</text>` : ""}
        </svg>
      `;
    }

    function renderTwodDbDatasetValue(row, field) {
      if (field.kind === "image") {
        const label = row[field.key] || row.formula || "二维结构";
        return `<button class="twod-db-structure-thumb" type="button" title="点击放大 ${escapeLowDimHtml(label)}" data-twod-db-structure-preview="${row.id}">${renderTwodAtomicStructureSvg(label)}</button>`;
      }
      return renderTwodDbCell(row[field.key]);
    }

    function renderTwodDbDatasetTable(activeKey) {
      const db = getTwodDatabaseState();
      const config = getTwodDatabaseTabConfig(activeKey);
      const rows = db.datasets[activeKey] || [];
      const minWidth = activeKey === "structure" ? 1320 : Math.max(760, config.fields.length * 240 + 180);
      return `
        <div class="twod-db-table-wrap">
          <table class="twod-db-table" style="min-width:${minWidth}px;">
            <thead>
              <tr>
                ${config.fields.map((field) => `<th style="${field.width ? `width:${field.width};` : ""}">${field.label}</th>`).join("")}
                <th style="width:150px;">操作</th>
              </tr>
            </thead>
            <tbody>
              ${rows.length ? rows.map((row) => `
                <tr>
                  ${config.fields.map((field) => `<td>${renderTwodDbDatasetValue(row, field)}</td>`).join("")}
                  <td>
                    <div class="twod-db-row-actions">
                      <button class="btn-primary btn-sm" type="button" data-twod-db-dataset-view="${row.id}">查看详情</button>
                    </div>
                  </td>
                </tr>
              `).join("") : `<tr><td colspan="${config.fields.length + 1}"><div class="sys-empty">暂无数据集</div></td></tr>`}
            </tbody>
          </table>
        </div>
      `;
    }

    function renderTwodDbDatasetCards(activeKey) {
      const db = getTwodDatabaseState();
      const config = getTwodDatabaseTabConfig(activeKey);
      const rows = db.datasets[activeKey] || [];
      if (!rows.length) {
        return `<div class="sys-empty">暂无数据集</div>`;
      }
      return `
        <div class="twod-db-card-grid">
          ${rows.map((row, index) => {
            const meta = getTwodDatabaseDatasetMeta(activeKey, index);
            const title = getTwodDatabaseDatasetName(row, config);
            const fieldPreview = config.fields
              .filter((field) => row[field.key])
              .slice(0, 4)
              .map((field) => `<span class="twod-db-card-field">${escapeLowDimHtml(field.label)}</span>`)
              .join("");
            return `
              <article class="twod-db-card">
                <div class="twod-db-card-head">
                  <div class="twod-db-card-title">
                    <h4>${escapeLowDimHtml(title)}</h4>
                    <p>二维材料数据库 · ${escapeLowDimHtml(config.label)}</p>
                  </div>
                  <span class="twod-db-card-index">${String(index + 1).padStart(2, "0")}</span>
                </div>
                <div class="twod-db-card-meta">
                  <div class="twod-db-card-stat">
                    <span>更新时间</span>
                    <strong data-twod-db-updated>${escapeLowDimHtml(meta.updatedAt)}</strong>
                  </div>
                  <div class="twod-db-card-stat">
                    <span>数据大小</span>
                    <strong data-twod-db-size>${escapeLowDimHtml(meta.dataSize)}</strong>
                  </div>
                </div>
                <div class="twod-db-card-fields">${fieldPreview}</div>
                <div class="twod-db-card-actions">
                  <button class="btn-primary btn-sm" type="button" data-twod-db-dataset-view="${row.id}">查看详情</button>
                </div>
              </article>
            `;
          }).join("")}
        </div>
      `;
    }

