    function formatLowdimDbVolume(value) {
      return String(value).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    }

    function getLowdimDbOverviewState(pageId) {
      if (!state.lowdimDbOverview) state.lowdimDbOverview = {};
      if (!state.lowdimDbOverview[pageId]) {
        /* 五个子库统一为「以材料为主体的数据集视图」：搜索 + 安全等级筛选 + 分页 */
        state.lowdimDbOverview[pageId] = { search: "", safety: "all", page: 1, pageSize: 6 };
      }
      return state.lowdimDbOverview[pageId];
    }

    function getLowdimDbFilteredDatasets(pageId) {
      const config = LOWDIM_DB_OVERVIEW_CONFIGS[pageId];
      const filters = getLowdimDbOverviewState(pageId);
      const keyword = (filters.search || "").trim().toLowerCase();
      return (config?.datasets || []).filter((item) => {
        if (filters.type !== "all" && item.title !== filters.type) return false;
        if (filters.format !== "all" && !item.format.split("/").map((part) => part.trim()).includes(filters.format)) return false;
        if (filters.status !== "all" && item.status !== filters.status) return false;
        if (keyword && !`${item.title} ${item.description} ${item.fields.join(" ")}`.toLowerCase().includes(keyword)) return false;
        return true;
      });
    }

