          const domain = form?.dataset.lowdimEntryDomainCurrent || getLowdimEntryState(pageId).materialDomain || "twod";
          const entry = getLowdimEntryState(pageId);
          if (!entry.manual[domain]) entry.manual[domain] = {};
          entry.manual[domain][manualField.dataset.lowdimEntryField] = manualField.value;
          applyLowdimManualEntryValidation();
