    function renderMlffDetailBasicPage(material) {
      const isReal = isLowDimRealCase("mlff", material);
      const realCase = getLowDimRealCase("mlff", material.id);
      const fields = realCase?.fields || {};
      const fieldValue = function (keys) {
        for (const key of keys) {
          const value = material[key] ?? fields[key];
          if (!isLowDimMissing(value)) return value && typeof value === "object" && "value" in value ? `${value.value}${value.unit ? ` ${value.unit}` : ""}` : value;
        }
        return "未记录";
      };
      const basicRows = isReal ? [
        { label: "材料编号", value: material.id },
        { label: "材料名称", value: material.name },
        { label: "分子式", value: material.formula },
        { label: "平衡能量", value: formatLowDimValue(material.equilibriumEnergy ?? fields.equilibrium_energy_ev, { numeric: true, digits: 8, suffix: " eV" }) },
        { label: "平衡原子电荷", value: `${(material.equilibriumAtomicCharges || fields.equilibrium_atomic_charges || []).length} 条` },
        { label: "保留构型帧", value: formatLowDimValue(material.retainedFrames ?? fields.retained_frames, { numeric: true, digits: 0 }) },
        { label: "原始构型帧", value: formatLowDimValue(material.rawFrames ?? fields.raw_frames, { numeric: true, digits: 0 }) },
        { label: "剔除构型帧", value: formatLowDimValue(material.rejectedFrames ?? fields.rejected_frames, { numeric: true, digits: 0 }) },
        { label: "数据拆分", value: fieldValue(["split", "datasetSplit", "data_split"]) },
        { label: "净电荷", value: formatLowDimValue(material.netCharge ?? fields.net_charge, { numeric: true, digits: 0, suffix: " e" }) },
        { label: "电荷状态", value: formatLowDimValue(material.chargeStatus ?? fields.charge_status) }
      ] : [
        { label: "材料编号", value: material.id }, { label: "化学名称", value: material.name }, { label: "英文名称", value: material.english },
        { label: "分子式", value: material.formula }, { label: "PubChem", value: material.pubchem }, { label: "力场类型", value: material.forceField },
        { label: "计算方法", value: material.method }, { label: "核心参数项", value: material.parameterName }, { label: "参数值", value: material.parameterValue },
        { label: "更新时间", value: material.updatedAt }
      ];
      const fileRows = isReal ? [
        { label: "PDB结构文件", value: `<div class="mlff-inline-actions"><span>真实分子坐标已内嵌于当前页面</span><button class="twod-detail-link-btn" type="button" onclick="return triggerMlffDownload('pdb')">下载</button></div>` },
      ] : [
        { label: "PDB结构文件", value: `<div class="mlff-inline-actions"><span>包含原子种类和原子三维坐标</span><button class="twod-detail-link-btn" type="button" onclick="return triggerMlffDownload('pdb')">下载</button></div>` },
        { label: "XML力场文件", value: `<div class="mlff-inline-actions"><span>包含力场参数映射和结构节点信息</span><button class="twod-detail-link-btn" type="button" onclick="return triggerMlffDownload('xml')">下载</button></div>` }
      ];
      const realViewer = renderLowDimRealViewer("mlff", material);
      const scene = realViewer ? null : buildMlffScene(material, "molecule");
      return `
        <div class="twod-detail-page-head">
          <div>
            <h4>${material.name}基础信息</h4>
            <p>展示当前机器学习力场材料的基础信息与文件下载入口。</p>
          </div>
        </div>
        <div class="mlff-basic-layout">
          <section class="twod-detail-table-card mlff-basic-left-card">
            <h5 class="twod-detail-basic-title">基础信息</h5>
            ${renderDetailKvSection("材料基础信息", basicRows, {
              fallback: "未记录",
              redLabels: ["平衡能量", "平衡原子电荷", "保留构型帧", "原始构型帧", "剔除构型帧", "数据拆分", "净电荷", "电荷状态"]
            })}
          </section>
          <div class="mlff-basic-right-column">
            <section class="twod-detail-visual-card mlff-basic-visual-card">
              <h5 class="twod-detail-basic-title">3D分子结构图</h5>
              <div class="mlff-structure-stage">
                ${realViewer || `<div class="material-atom-cluster mlff-scene" data-mlff-scene-size="${scene.size}">${renderMlffSceneMarkup(scene)}</div>`}
                <p class="mlff-basic-visual-caption">${realViewer ? "真实分子坐标，可拖拽旋转、滚轮缩放并切换显示样式。" : `${material.name} 的 3D 分子结构示意图，用于展示当前力场样本的原子组成与空间构型。`}</p>
              </div>
            </section>
            <section class="twod-detail-table-card mlff-file-card">
              <h5 class="twod-detail-basic-title">参数力场文件</h5>
              ${renderDetailKvSection("", fileRows, { fallback: "未记录" })}
            </section>
          </div>
        </div>
      `;
    }

    function renderMlffChargePage(material) {
      const realCase = getLowDimRealCase("mlff", material.id);
      const rawChargeRows = material.equilibriumAtomicCharges
        ?? material.chargeRows
        ?? realCase?.fields?.equilibrium_atomic_charges;
      const normalizedChargeRows = Array.isArray(rawChargeRows) ? rawChargeRows.map((row, index) => ({
        atomIndex: row?.atom_index ?? row?.atomIndex ?? row?.index ?? index + 1,
        element: row?.element ?? row?.atom ?? row?.symbol ?? "未记录",
        charge: row?.charge_e ?? row?.charge ?? row?.partial_charge_e ?? row?.value,
        method: row?.charge_method ?? row?.method ?? row?.charge_status ?? ""
      })) : [];
      const chargeValues = Array.isArray(material.chargeValues) ? material.chargeValues : [];
      let chargeRows = normalizedChargeRows.length ? normalizedChargeRows : buildMlffNodeCoordinates(material).map((node, index) => ({
        atomIndex: index + 1,
        element: node.atom,
        charge: chargeValues[index],
        method: ""
      }));
      if (!chargeRows.length) chargeRows = [{ atomIndex: 1, element: LOW_DIM_NO_PROPERTY_TEXT, charge: LOW_DIM_NO_PROPERTY_TEXT, method: "" }];
      return `
        <div class="twod-detail-page-head">
          <div>
            <h4>电荷</h4>
            <p>展示当前材料的原子电荷分布和对应的数值明细。</p>
          </div>
        </div>
        <section class="twod-detail-section-card">
          <h5>原子电荷明细</h5>
          <table class="mlff-data-table">
            <thead><tr><th>序号</th><th>原子</th><th>电荷值 (e)</th></tr></thead>
            <tbody>
              ${chargeRows.map((row) => `<tr><td>${formatLowDimValue(row.atomIndex)}</td><td>${formatLowDimValue(row.element)}</td><td>${formatLowDimValue(row.charge, { numeric: true, digits: 6 })}</td></tr>`).join("")}
            </tbody>
          </table>
        </section>
      `;
    }

    /* 读取由真实平衡态坐标算出的分子几何统计（纯几何，本地快速计算） */
    function getMlffGeomText(material, kind) {
      const g = getLowDimRealCase("mlff", material?.id)?.fields?.geom_calc;
      if (!g) return null;
      if (kind === "bondRange") {
        return g.bond_len_min != null
          ? g.bond_len_min.toFixed(3) + " ~ " + g.bond_len_max.toFixed(3) + " Å（共 " + g.bond_count + " 条键）"
          : null;
      }
      if (kind === "bondAvg") {
        return g.bond_len_avg != null ? g.bond_len_avg.toFixed(3) + " Å" : null;
      }
      if (kind === "bondTypes") {
        return Array.isArray(g.bond_types) && g.bond_types.length
          ? g.bond_types.map((b) => b.type + "×" + b.count + " (" + b.avg.toFixed(3) + " Å)").join("， ")
          : null;
      }
      if (kind === "angleRange") {
        return g.angle_min != null
          ? g.angle_min.toFixed(1) + "° ~ " + g.angle_max.toFixed(1) + "°（均值 " + g.angle_avg.toFixed(1) + "°，共 " + g.angle_count + " 个）"
          : null;
      }
      if (kind === "rg") {
        return g.radius_of_gyration_ang != null ? g.radius_of_gyration_ang.toFixed(3) + " Å" : null;
      }
      if (kind === "span") {
        return g.max_span_ang != null ? g.max_span_ang.toFixed(3) + " Å" : null;
      }
      return null;
    }

    function renderMlffMultipolePage(material) {
      const realCase = getLowDimRealCase("mlff", material.id);
      const f = realCase?.fields || {};
      const mag = toLowDimFiniteNumber(f.dipole_debye);
      const vec = Array.isArray(f.dipole_vector_debye) ? f.dipole_vector_debye.map(toLowDimFiniteNumber) : null;
      const charges = Array.isArray(f.equilibrium_atomic_charges) ? f.equilibrium_atomic_charges : [];
      const rows = [
        { label: "偶极矩 |μ|", value: mag != null ? mag.toFixed(4) + " Debye" : LOW_DIM_NO_PROPERTY_TEXT },
        vec && vec.every((v) => v != null)
          ? { label: "偶极分量 (x, y, z)", value: vec.map((v) => v.toFixed(4)).join(" , ") + " Debye" }
          : null,
        charges.length ? { label: "参与求和的原子数", value: charges.length + " 个" } : null,
        f.equilibrium_charge_sum_e != null
          ? { label: "电荷守恒残差", value: Number(f.equilibrium_charge_sum_e).toExponential(2) + " e" }
          : null
      ].filter(Boolean);
      return `
        <div class="twod-detail-page-head">
          <div>
            <h4>${escapeLowDimHtml(material.name)}　多级矩</h4>
            <p>由平衡态逐原子电荷与平衡几何求得的分子偶极矩。</p>
          </div>
        </div>
        <section class="twod-detail-section-card">
          <h5>偶极矩</h5>
          <div class="twod-detail-property-grid">
            ${rows.map((item) => `
              <article class="twod-detail-property-item">
                <span>${item.label}</span>
                <strong>${item.value}</strong>
              </article>
            `).join("")}
          </div>

        </section>
      `;
    }

    function renderMlffStructurePage(material, tabKey, titleText, descText) {
      const isRealMolecule = isLowDimRealCase("mlff", material) && tabKey === "molecule";
      const facts = isRealMolecule
        ? [
            { label: "结构页面", value: "分子结构" },
            { label: "化学名称", value: `${material.name} / ${material.english}` },
            { label: "保留构型帧", value: formatLowDimValue(material.retainedFrames, { numeric: true, digits: 0 }) },
            { label: "数据拆分", value: formatLowDimValue(material.split) },
            { label: "推荐下载", value: "PDB结构文件" }
          ]
        : buildMlffDetailFacts(material, tabKey);
      const realViewer = renderLowDimRealViewer("mlff", material);
      const scene = realViewer ? null : buildMlffScene(material, tabKey);
      const actionButton = tabKey === "smallSystem"
        ? `<button class="btn-primary" type="button" onclick="return triggerMlffDownload('smallSystem')">小体系结构下载</button>`
        : tabKey === "largeSystem"
          ? `<button class="btn-primary" type="button" onclick="return triggerMlffDownload('largeSystem')">大体系结构下载</button>`
          : `<button class="btn-primary" type="button" onclick="return triggerMlffDownload('pdb')">PDB结构文件下载</button>`;
      const structureRows = [
        ...facts,
        { label: "原子组成", value: material.atoms },
        { label: "键长范围", value: getMlffGeomText(material, "bondRange") },
        { label: "平均键长", value: getMlffGeomText(material, "bondAvg") },
        { label: "键角范围", value: getMlffGeomText(material, "angleRange") },
        { label: "回转半径", value: getMlffGeomText(material, "rg") },
        { label: "最大跨度", value: getMlffGeomText(material, "span") },
        { label: "分子式", value: material.formula }
      ];
      return `
        <div class="twod-detail-page-head">
          <div>
            <h4>${titleText}</h4>
            <p>${descText}</p>
          </div>
          <div class="twod-detail-page-action">
            ${actionButton}
          </div>
        </div>
        <div class="mlff-basic-layout">
          <section class="twod-detail-visual-card mlff-basic-visual-card">
            <h5 class="twod-detail-basic-title">${titleText}预览</h5>
            <div class="mlff-structure-stage">
              ${realViewer || `<div class="material-atom-cluster mlff-scene" data-mlff-scene-size="${scene.size}">${renderMlffSceneMarkup(scene)}</div>`}
              <p class="mlff-basic-visual-caption">${realViewer ? "真实分子坐标，可拖拽旋转、滚轮缩放并切换显示样式。" : scene.caption}</p>
            </div>
          </section>
          <section class="twod-detail-table-card mlff-basic-left-card">
            <h5 class="twod-detail-material-title">${titleText}信息</h5>
            ${renderDetailKvSection("", structureRows, isRealMolecule ? { fallback: "未记录", redAll: true } : { redAll: true })}
          </section>
        </div>
      `;
    }

    function renderMlffDetailTreeOverride() {
      const wrap = document.getElementById("twodDetailTree");
      if (!wrap) return;
      const items = [
        { key: "basic", label: "基础信息" },
        { key: "molecule", label: "分子结构" },
        { key: "smallSystem", label: "小体系结构" },
        { key: "largeSystem", label: "大体系结构" }
      ];
      wrap.innerHTML = items.map((item) => `
        <div class="twod-tree-item">
          <button class="twod-tree-node${item.key === "smallSystem" ? " mlff-red-field" : ""}${state.selectedTwodDetailSection === item.key ? " active" : ""}" type="button" onclick="return openMlffDetailSection('${item.key}')">${item.label}</button>
        </div>
      `).join("");
    }

    function renderMlffDetailPage(material) {
      const title = document.getElementById("twodDetailPageTitle");
      const subtitle = document.getElementById("twodDetailPageSubtitle");
      const content = document.getElementById("twodDetailPageContent");
      const page = document.getElementById("page-twod-detail");
      if (page) page.setAttribute("data-source", "mlff");
      if (title) title.textContent = `${material.name} 材料详情`;
      if (subtitle) subtitle.textContent = `材料编号 ${material.id} · 基础信息与来源性质；算法计算结果请见「发起预测」`;
      if (!content) return;
      // 详情页左侧仅保留基础信息与三类结构视图。
      const MLFF_DETAIL_SECTIONS = ["basic", "molecule", "smallSystem", "largeSystem"];
      if (!MLFF_DETAIL_SECTIONS.includes(state.selectedTwodDetailSection)) {
        state.selectedTwodDetailSection = "basic";
      }
      renderMlffDetailTreeOverride();
if (state.selectedTwodDetailSection === "molecule") {
        content.innerHTML = renderMlffStructurePage(material, "molecule", "分子结构", "展示当前材料的分子级结构与组成信息。");
        return;
      }
      if (state.selectedTwodDetailSection === "smallSystem") {
        content.innerHTML = renderMlffStructurePage(material, "smallSystem", "小体系结构", "展示当前材料的小体系结构与力场参数上下文。");
        return;
      }
      if (state.selectedTwodDetailSection === "largeSystem") {
        content.innerHTML = renderMlffStructurePage(material, "largeSystem", "大体系结构", "展示当前材料的大体系扩展结构与力场参数上下文。");
        return;
      }
      content.innerHTML = renderMlffDetailBasicPage(material);
    }

    function openMlffDetailSection(section) {
      state.selectedTwodDetailSection = section;
      const material = getCanonicalMaterialBySource("mlff", state.selectedMaterialId);
      if (material) renderMlffDetailPage(material);
      return false;
    }

    function openMlffDetailPage(materialToken, targetView = "basic") {
      const parsed = parseMaterialToken(materialToken);
      const material = getCanonicalMaterialBySource("mlff", parsed.id);
      if (!material) return false;
      state.selectedMaterialSource = "mlff";
      state.selectedMaterialId = material.id;
      state.twodDetailReturnPage = state.page === "twod-detail" ? "mlff" : (state.page || "mlff");
      state.selectedTwodDetailSection = targetView === "molecule" || targetView === "structure"
        ? "molecule"
        : targetView === "charge"
          ? "charge"
          : targetView === "multipole"
            ? "multipole"
            : "basic";
      renderMlffDetailPage(material);
      switchPage("twod-detail");
      return false;
    }

    window.triggerMlffDownload = triggerMlffDownload;
    window.openMlffDetailSection = openMlffDetailSection;

    const mlffOverrideUpdateBreadcrumb = updateBreadcrumb;
    updateBreadcrumb = function (page) {
      if (page === "twod-detail" && state.selectedMaterialSource === "mlff") {
        const breadcrumb = document.getElementById("breadcrumb");
        if (!breadcrumb) return;
        breadcrumb.innerHTML = `<span>低维材料主题应用</span><span>/</span><span>机器学习力场应用</span><span>/</span><strong>机器学习力场详情</strong>`;
        return;
      }
      mlffOverrideUpdateBreadcrumb(page);
    };

    const mlffOverrideRenderTwodDetailPage = renderTwodDetailPage;
    renderTwodDetailPage = function (material) {
      if (state.selectedMaterialSource === "mlff") {
        renderMlffDetailPage(material);
        return;
      }
      mlffOverrideRenderTwodDetailPage(material);
    };

    const mlffOverrideOpenRichMaterialModal = openRichMaterialModal;
    openRichMaterialModal = function (materialToken, targetView = "detail") {
      const parsed = parseMaterialToken(materialToken);
      if (parsed.source === "mlff") return openMlffDetailPage(materialToken, targetView);
      return mlffOverrideOpenRichMaterialModal(materialToken, targetView);
    };

    const mlffOverrideHandleMaterialDetailOpen = handleMaterialDetailOpen;
    handleMaterialDetailOpen = function (materialToken, targetView = "detail") {
      const parsed = parseMaterialToken(materialToken);
      if (parsed.source === "mlff") return openMlffDetailPage(materialToken, targetView);
      return mlffOverrideHandleMaterialDetailOpen(materialToken, targetView);
    };

    function bindMlffDetailPageOverrides() {
      const backBtn = document.getElementById("twodDetailBackBtn");
      if (!backBtn || backBtn.dataset.mlffBackBound === "true") return;
      backBtn.dataset.mlffBackBound = "true";
      backBtn.addEventListener("click", (event) => {
        if (state.selectedMaterialSource !== "mlff") return;
        event.preventDefault();
        event.stopImmediatePropagation();
        const target = state.twodDetailReturnPage || "mlff";
        switchPage(target);
        if (target === "mlff") renderMlffModule();
      }, true);
    }

