    function buildElectrolyteExternalReferences(material) {
      const rows = (material.detailTabs?.external || []).map((item) => ({ title: item.label, text: item.value }));
      const generated = [
        { title: "数据来源", text: material.source || "系统内置数据源" },
        { title: "参考文献 1", text: `${material.alias || material.formula} electrolyte dataset and structural benchmark.` },
        { title: "参考文献 2", text: `${material.name} related literature and external structure mapping records.` }
      ];
      return rows.length
        ? rows.concat(generated)
        : generated;
    }

