    function generateRegisterCaptchaOverride() {
      const chars = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
      state.registerCaptchaCode = Array.from({ length: 4 }).map(() => chars[Math.floor(Math.random() * chars.length)]).join("");
      const box = document.getElementById("registerCaptchaBox");
      if (box) box.textContent = state.registerCaptchaCode;
    }

    function setRegisterErrorOverride(message = "") {
      const error = document.getElementById("registerError");
      if (error) error.textContent = message;
    }

    function switchAuthTabOverride(tab) {
      state.authTab = tab === "register" ? "register" : "login";
      renderAuthShellOverride();
      bindLoginInteractions();
      generateLoginCaptcha();
      generateRegisterCaptchaOverride();
      setLoginError("");
      setRegisterErrorOverride("");
    }

    function handleRegisterSubmitOverride(event) {
      event.preventDefault();
      const account = document.getElementById("registerAccount")?.value.trim() || "";
      const password = document.getElementById("registerPassword")?.value || "";
      const confirmPassword = document.getElementById("registerConfirmPassword")?.value || "";
      const captcha = (document.getElementById("registerCaptchaInput")?.value || "").trim().toUpperCase();

      if (!account || !password || !confirmPassword || !captcha) {
        setRegisterErrorOverride("请完整填写注册信息和验证码。");
        generateRegisterCaptchaOverride();
        return;
      }
      if (password.length < 6) {
        setRegisterErrorOverride("密码长度不少于 6 位。");
        generateRegisterCaptchaOverride();
        return;
      }
      if (password !== confirmPassword) {
        setRegisterErrorOverride("两次输入的密码不一致。");
        generateRegisterCaptchaOverride();
        return;
      }
      if (captcha !== state.registerCaptchaCode) {
        setRegisterErrorOverride("验证码输入错误，请重新输入。");
        generateRegisterCaptchaOverride();
        const captchaInput = document.getElementById("registerCaptchaInput");
        if (captchaInput) captchaInput.value = "";
        return;
      }

      setRegisterErrorOverride("");
      showToast("注册申请", `账号 ${account} 已提交注册申请，请返回登录。`);
      state.authTab = "login";
      renderAuthShellOverride();
      bindLoginInteractions();
      generateLoginCaptcha();
      generateRegisterCaptchaOverride();
    }

    syncAuthView = function () {
      const loginShell = document.getElementById("loginShell");
      const appRoot = document.getElementById("appRoot");
      if (!loginShell || !appRoot) return;

      if (state.isAuthenticated) {
        loginShell.hidden = true;
        appRoot.hidden = false;
        ensureTopbarSessionActions();
        const captchaInput = document.getElementById("loginCaptchaInput");
        if (captchaInput) captchaInput.value = "";
        setLoginError("");
        setRegisterErrorOverride("");
        return;
      }

      loginShell.hidden = false;
      appRoot.hidden = true;
      renderAuthShellOverride();
      generateLoginCaptcha();
      generateRegisterCaptchaOverride();
      bindLoginInteractions();
    };

    bindLoginInteractions = function () {
      document.getElementById("loginForm")?.addEventListener("submit", handleLoginSubmit);
      document.getElementById("registerForm")?.addEventListener("submit", handleRegisterSubmitOverride);
      document.getElementById("loginCaptchaRefresh")?.addEventListener("click", () => {
        setLoginError("");
        generateLoginCaptcha();
      });
      document.getElementById("registerCaptchaRefresh")?.addEventListener("click", () => {
        setRegisterErrorOverride("");
        generateRegisterCaptchaOverride();
      });
      if (!document.body.dataset.authBoundOverride) {
        document.body.dataset.authBoundOverride = "true";
        document.body.addEventListener("click", (event) => {
          const roleButton = event.target.closest("[data-login-role]");
          if (roleButton && roleButton.closest("#loginShell")) {
            event.preventDefault();
            state.loginRole = roleButton.dataset.loginRole === "researcher" ? "researcher" : "admin";
            renderAuthShellOverride();
            bindLoginInteractions();
            setLoginError("");
            return;
          }
          const tabButton = event.target.closest("[data-auth-tab]");
          if (tabButton && tabButton.closest("#loginShell")) {
            event.preventDefault();
            switchAuthTabOverride(tabButton.dataset.authTab);
            return;
          }
          if (event.target.closest("#portalReturnBtn")) {
            window.location.href="portal.html";
          }
        });
      }
    };

    function triggerCatalystSiteExport() {
      const result = state.catalystSiteResult;
      if (!result) return;
      const filename = `${String(result.materialId || "catalyst_site").replace(/[^a-zA-Z0-9_-]+/g, "_")}_site_result.txt`;
      const content = buildCatalystSiteExportContent(result);
      if (typeof triggerTwodDetailDownload === "function") {
        triggerTwodDetailDownload(filename, content, "text/plain;charset=utf-8");
        return;
      }
      const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
      const link = document.createElement("a");
      const url = URL.createObjectURL(blob);
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 0);
    }

    function bindCatalystSiteWorkbenchOverrides() {
      if (document.body.dataset.catalystSiteWorkbenchOverrideBound === "true") return;
      document.body.dataset.catalystSiteWorkbenchOverrideBound = "true";

      document.body.addEventListener("click", (event) => {
        const siteWorkbenchTrigger = event.target.closest('[data-catalyst-workbench="site"]');
        const siteCalc = event.target.closest("[data-catalyst-site-calc]");
        const siteExport = event.target.closest("[data-catalyst-site-export]");

        if (siteWorkbenchTrigger) {
          event.preventDefault();
          event.stopPropagation();
          ensureCatalystPlatformState();
          if (state.catalystBatchSelection.length) {
            const picked = state.catalystBatchSelection.map(findCatalystMaterial).filter(Boolean)[0];
            if (picked) state.catalystSiteMaterialId = picked.id;
          }
          openCatalystWorkbenchPage("site");
          return;
        }

        if (siteCalc) {
          event.preventDefault();
          event.stopPropagation();
          runCatalystSiteCalculationV2();
          return;
        }

        if (siteExport) {
          event.preventDefault();
          event.stopPropagation();
          triggerCatalystSiteExport();
        }
      }, true);

      document.body.addEventListener("change", (event) => {
        if (event.target.id === "catalystSiteMaterialSelect") {
          state.catalystSiteMaterialId = event.target.value || "";
          state.catalystSiteCalcStatus = "idle";
          state.catalystSiteResult = null;
          renderCatalystWorkbenchPage("site");
          return;
        }

        if (event.target.id && Object.prototype.hasOwnProperty.call(state.catalystSiteParams || {}, event.target.id)) {
          state.catalystSiteParams[event.target.id] = event.target.value;
          state.catalystSiteCalcStatus = "idle";
          state.catalystSiteResult = null;
        }
      }, true);
    }

