    function ensureCatalystBuildReadonlyState() {
      if (!state.catalystBuildMaterialId || !getCatalystBuildReadonlyResource(state.catalystBuildMaterialId)) {
        const fallback = (state.catalystBatchSelection || []).map(findCatalystMaterial).find((item) => item && getCatalystBuildReadonlyResource(item.id))
          || (Array.isArray(catalystMaterials) ? catalystMaterials : []).find((item) => getCatalystBuildReadonlyResource(item.id));
        state.catalystBuildMaterialId = (fallback && fallback.id) || (catalystMaterials[0] && catalystMaterials[0].id) || "";
      }
    }

